window.__VD__=window.__VD__||{};window.__VD__["u"]={"update":[["ʌpˈdeɪt；ˈʌp.deɪt","ˌʌpˈdeɪt；ˈʌpˌdeɪt"],["CET6","考研","IELTS"],[["复数","updates"],["原形","update"],["第三人称单数","updates"],["现在分词","updating"],["过去式","updated"],["过去分词","updated"],["形容词","updatable",1],["名词","updater",1]],[4,1.5,3,3,1],[["v.","使现代化；更新",2],["v.","向…提供最新信息；给…增加最新信息",1],["n.","最新报道；最新消息；最新进展",0],["n.","（计算机程序的）更新，最新校正数据",0],["n.","新信息，新情况;更新",1]],[["2025 英二 · 阅读 · Part B","When it works, it works great — because you’re ready for your stubborn supervisor’s pushback with answers like, “Actually, I connected with a few people in our tech department to discuss how much time these kinds of website updates would take, and they suggested they have the bandwidth.”","如果这样做奏效，效果会非常好：面对固执上司的反对，你已准备好这样回应：“其实，我联系了技术部门的几位同事，讨论这类网站更新需要多少时间，他们说自己有余力承担。”","正文"],["2025 英二 · 阅读 · Part B","So, instead of saying, “Martha, our current slogan is confusing and should be updated,” you could try, “Martha raises a great point that our current slogan has a long history for our stakeholders, but I wonder if we might be able to brainstorm a tagline that could build on that — and be clearer for new customers.”","所以，与其说“玛莎，我们目前的口号容易让人困惑，应当更新”，不如试试说：“玛莎提了很好的意见：我们现在的口号与利益相关者有长期渊源。不过，我在想，我们能否一起想出一句在此基础上改进、又让新顾客更容易理解的宣传语？”","正文"],["2015 英一 · 阅读 · Part A · Text 2","Enough of the implications are discernable, even obvious, so that the justices can and should provide updated guidelines to police, lawyers and defendants.","这些影响已有足够多可以辨明，甚至显而易见，因此大法官能够且应当为警方、律师和被告提供符合当下情况的指引。","正文"],["2016 英二 · 阅读 · Part A · Text 3 · 第32题 · 选项A","The “empty bottles” metaphor illustrates that people feel a pressure to update their to-do lists.","“空瓶子”这一比喻说明，人们感到有压力，觉得必须更新待办事项清单。","选项"]],"update.mp3",{"r":[["词根","do-,don-,dit-,dot-,dow- = to give 给予"]],"d":[["updating","1. n. 更新 2. v. 更新（update的ing形式）"],["de-updating","不更新"]]}],"upgrade":[["ʌpˈɡreɪd；ˈʌp.ɡreɪd","ˌʌpˈɡreɪd"],["CET6","考研","TOEFL","GRE"],[["复数","upgrades"],["原形","upgrade"],["第三人称单数","upgrades"],["现在分词","upgrading"],["过去式","upgraded"],["过去分词","upgraded"],["名词","upgradability",1],["形容词","upgradable",1]],[18,3.0,11,6,8],[["v.","使（机器、计算机系统等）升级；提高；改进",6],["v.","提高（设施、服务等的）档次；改善；使升格",4],["v.","提高（飞机乘客、旅馆住客等的）待遇；优待",0],["v.","提升；提拔",0],["n.","使（机器、计算机系统等）升级；提高；改进",7],["n.","提高（设施、服务等的）档次；改善；使升格",1],["n.","提高（飞机乘客、旅馆住客等的）待遇；优待",0]],[["2026 英二 · 阅读 · Part A · Text 3","One of the most important changes the upgrades will bring is the segregation of the high-speed line from the regular one in certain urban centres through the construction of underground rail links.","这些升级工程带来的最重要变化之一，是通过修建地下铁路联络线，在部分城市中心将高铁线路与普通线路分开。","正文"],["2023 英二 · 阅读 · Part B","Gareth Belsham, of surveyors Naismiths, says people who are upgrading, or extending their home, will be directly affected.","测量师事务所Naismiths的加雷思·贝尔沙姆表示，正在升级或扩建住宅的人会受到直接影响。","正文"],["2016 英一 · 阅读 · Part B","How do we know when to invest in an upgrade?","我们怎样知道什么时候该投入资源提升形象？","正文"],["2016 英一 · 阅读 · Part B","Maybe there’s no need for an upgrade and that’s OK.","也许你根本无需提升形象，那也没关系。","正文"],["2016 英一 · 阅读 · Part B","The point of a style upgrade isn’t to become more vain or to spend more time fussing over what to wear.","提升着装风格的目的，不是变得更爱慕虚荣，也不是花更多时间纠结穿什么。","正文"],["2016 英一 · 阅读 · Part B","As an executive coach, I’ve seen image upgrades be particularly helpful during transitions — when looking for a new job, stepping into a new or more public role, or changing work environments.","作为高管教练，我发现形象提升在过渡时期特别有帮助，例如找新工作、担任新职务或更需要面对公众的职务，或是转换工作环境时。","正文"]],"upgrade.mp3",{"r":[["词根","up- = up, over, 表示“向上”。"],["词根","grad- = step, grade, 表示“步，级”，源自拉丁语 gradus \"step\"。"]],"d":[]}],"uphold":[["ʌpˈhəʊld","ˈʌpˈhoʊld"],["CET6","考研","TOEFL","IELTS","GRE"],[["原形","uphold"],["第三人称单数","upholds"],["现在分词","upholding"],["过去式","upheld"],["过去分词","upheld"],["名词","upholder",1]],[4,1.5,3,4,0],[["v.","支持，维护（正义等）",1],["v.","维持（原判）；受理（申诉）",3]],[["2021 英一 · 阅读 · Part A · Text 4","On Tuesday, the appeals court unanimously upheld the 2017 order deregulating broadband providers, citing a Supreme Court ruling from 2005 that upheld a similarly deregulatory move.","周二，上诉法院一致维持了 2017 年放松宽带服务商监管的命令，理由是最高法院 2005 年的一项裁决曾维持过一项类似的放松监管措施。","正文"],["2020 英一 · 阅读 · Part C","Copernicus theorized in 1543 that in actual fact, all of the planets that we knew of revolved not around the Earth, but the Sun, a system that was later upheld by Galileo at his own expense.","哥白尼在1543年提出理论：事实上，我们所知的所有行星都不是围绕地球，而是围绕太阳运行；后来伽利略不惜付出代价，也支持了这一体系。","正文"],["2010 英一 · 阅读 · Part A · Text 2","Last April, for example, the justices signaled that too many patents were being upheld for “inventions” that are obvious.","例如，去年四月，最高法院的法官们表明，有太多显而易见的“发明”获得了专利保护。","正文"]],"uphold.mp3",{"r":[["词根","up- = up, over, 表示“向上”。"]],"d":[["upholder","n. 支撑物；支持者"]]}],"upset":[["ʌpˈset；ˈʌp.set","ˌʌpˈset；ˈʌpˌset"],["高中","CET4","CET6","考研","TOEFL","IELTS"],[["复数","upsets"],["原形","upset"],["第三人称单数","upsets"],["现在分词","upsetting"],["过去式","upset"],["过去分词","upset"],["名词","upsetter",1]],[10,2.5,7,7,0],[["adj.","难过；不高兴；失望；沮丧",1],["adj.","肠胃病；腹泻",0],["v.","使烦恼；使心烦意乱；使生气",7],["v.","打乱；搅乱",2],["v.","使（肠胃）不适",0],["v.","打翻；碰倒；使倾覆",0],["n.","（意外的）混乱，困扰，麻烦",0],["n.","意外的结果；爆冷门",0],["n.","肠胃病；腹泻",0],["n.","不痛快；烦闷；失望；苦恼",0]],[["2016 英一 · 阅读 · Part A · Text 4","“Figuring out a way to accelerate that transition would make sense for them,” he said, “but if you discontinue it, you’re going to have your most loyal customers really upset with you.”","他说：“想办法加快这一转型对他们是有意义的，但如果直接停掉印刷版，最忠实的顾客会非常不满。”","正文"],["2015 英一 · 阅读 · Part A · Text 2","California has asked the justices to refrain from a sweeping ruling, particularly one that upsets the old assumption that authorities may search through the possessions of suspects at the time of their arrest.","加利福尼亚州请求大法官们不要作出适用范围过广的裁决，尤其不要推翻一项旧有假定：当局可以在逮捕嫌疑人时搜查其随身物品。","正文"],["2013 英一 · 阅读 · Part A · Text 2","If it is trying to upset Google, which relies almost wholly on advertising, it has chosen an indirect method: there is no guarantee that DNT by default will become the norm.","如果微软是想打击几乎完全依赖广告的谷歌，它选用的是一种间接办法：无法保证默认开启 DNT 会成为普遍做法。","正文"],["2013 英一 · 阅读 · Part A · Text 4","But on the more important matter of the Constitution, the decision was an 8-0 defeat for the Administration’s effort to upset the balance of power between the federal government and the states.","但在更重要的宪法问题上，这项裁决以八比零的结果，挫败了政府试图改变联邦政府与各州之间权力平衡的努力。","正文"],["2005 英一 · 阅读 · Part A · Text 3","As soon as you awaken, identify what is upsetting about the dream.","醒来后，立即找出梦中令你不安的地方。","正文"],["2005 英一 · 阅读 · Part A · Text 2","There are upsetting parallels today, as scientists in one wave after another try to awaken us to the growing threat of global warming.","如今出现了令人不安的相似情形：一批又一批科学家试图唤醒我们，正视全球变暖日益严重的威胁。","正文"]],"upset.mp3",{"r":[["词根","up- = up, over, 表示“向上”。"],["词根","set- = fix, 表示“安置好”。"]],"d":[["upsetting","adj. 令人心烦意乱的，令人苦恼的； n. 缩锻，镦锻；倾复，倒转"]]}],"up-to-date":[["ˌʌp.tə ˈdeɪt","ˌʌp·təˈdeɪt"],["CET4","CET6","IELTS"],[["副词","up-to-dately",1],["名词","up-to-dateness",1]],[1,0.5,1,0,1],[["adj.","现代的；最新的；时髦的；新式的",1],["adj.","拥有（或包含）最新信息的",0]],[["2010 英二 · 阅读 · Part A · Text 1 · 第25题 · 选项B","The most appropriate title for this text could be Up-to-date Art Auctions.","本文最恰当的标题可以是《最新的艺术品拍卖》。","选项"]],"up-to-date.mp3",null],"urban":[["ˈɜː.bᵊn","ˈɜr·bən"],["高中","CET4","CET6","考研","TOEFL"],[],[16,3.0,6,11,5],[["adj.","城市的；都市的；城镇的",16],["adj.","都市音乐的，城市音乐的（如节奏布鲁斯音乐、雷盖音乐）",0]],[["2026 英二 · 阅读 · Part A · Text 3","One of the most important changes the upgrades will bring is the segregation of the high-speed line from the regular one in certain urban centres through the construction of underground rail links.","这些升级工程带来的最重要变化之一，是通过修建地下铁路联络线，在部分城市中心将高铁线路与普通线路分开。","正文"],["2025 英二 · 阅读 · Part A · Text 3","To help improve HAPs, urban planner Kotharkar’s team is working on a model plan that outlines best practices and could be adapted to local conditions.","为改进高温应对计划，城市规划师科塔卡尔的团队正在制定一份范本，概述最佳做法，并可根据当地情况调整。","正文"],["2025 英二 · 阅读 · Part A · Text 4","Urban planners interpret desire paths as more than just convenient shortcuts; they offer valuable insights into the dynamics between planning and behaviour.","城市规划师认为，愿望路径不只是方便的捷径；它们还能为理解规划与行为之间的相互作用提供宝贵线索。","正文"],["2025 英二 · 阅读 · Part A · Text 4","This clash highlights an ongoing struggle between the organic, user-driven evolution of public spaces and the desire for a visually curated and controlled urban environment.","这种冲突凸显出一场持续的角力：一方希望公共空间由使用者自发演变，另一方则希望城市环境经过精心设计、视觉整齐且便于管控。","正文"],["2025 英二 · 阅读 · Part A · Text 4","Navigating beyond the organised pavements and parks of our urban spaces, desire paths are the unofficial footprints of a community, revealing the unspoken preferences, shared shortcuts and collective choices of humans.","在城市规划好的步道和公园之外延伸的“愿望路径”，是社区留下的非正式足迹，显露出人们未说出口的偏好、共同走出的捷径和集体选择。","正文"],["2016 英一 · 阅读 · Part A · Text 2","We do not ruin urban conservation areas.","我们不会毁掉城市里的保护区。","正文"]],"urban.mp3",{"r":[["词根","urb- = city, 表示“城市”。"],["后缀","-an 表名词和形容词，“…地方，…人”。"]],"d":[["urbane","adj. 彬彬有礼的，温文尔雅的；都市化的"],["exurban","adj. 城市远郊的"],["inurbane","adj. 粗野的；粗鄙的"],["suburban","1. adj. 土气的；郊区的，城郊的；见闻不广的 2. n. 郊区居民"],["urbanism","n. 都市生活；都市集中"]]}],"urge":[["ɜːdʒ","ɜrdʒ"],["高中","CET4","CET6","考研","TOEFL"],[["复数","urges"],["原形","urge"],["第三人称单数","urges"],["现在分词","urging"],["过去式","urged"],["过去分词","urged"],["名词","urger",1]],[14,3.0,9,9,3],[["v.","敦促；催促；力劝",5],["v.","大力推荐；竭力主张",2],["v.","驱赶；鞭策",0],["n.","强烈的欲望；冲动",7]],[["2013 英一 · 阅读 · Part C","Another urge or need that these gardens appear to respond to, or to arise from, is so intrinsic that we are barely ever conscious of its abiding claims on us.","这些花园似乎回应了另一种欲望或需求，或正是从中产生；这种需求根深蒂固，以至于我们几乎从未察觉它一直在向我们提出要求。","正文"],["2013 英一 · 阅读 · Part C","One of these urges has to do with creating a state of peace in the midst of turbulence, a “still point of the turning world,” to borrow a phrase from T. S. Eliot.","其中一种渴望，是在动荡中营造宁静的状态；借用 T. S. 艾略特的话来说，就是“旋转世界中的静止点”。","正文"],["2013 英一 · 阅读 · Part C","There is no doubt that the gardens evidence an irrepressible urge to create, express, fashion, and beautify and that self-expression is a basic human urge; (46) yet when one looks at the photographs of the gardens created by the homeless, it strikes one that, for all their diversity of styles, these gardens speak of various other fundamental urges, beyond that of decoration and creative expression.","毫无疑问，这些花园表明，人有一种不可遏制的欲望，想要创造、表达、塑造并美化；自我表达确实是人的基本欲望；（46）然而，看着无家可归者创造的花园照片，人会发现：尽管风格各异，这些花园所体现的还有装饰和创造性表达以外的种种基本渴望。","正文"],["2012 英二 · 阅读 · Part A · Text 3","Last year a federal task-force urged reform for patents related to genetic tests.","去年，一个联邦特别工作组呼吁改革与基因检测有关的专利制度。","正文"],["2011 英二 · 阅读 · Part B","He also urged councils to impose “fast-food-free zones” around schools and hospitals — areas within which takeaways cannot open.","他还敦促地方议会在学校和医院周围设立“禁开快餐店区”，禁止外卖店在这些区域营业。","正文"],["2004 英一 · 阅读 · Part A · Text 4","From the beginning of our history, says Hofstadter, our democratic and populist urges have driven us to reject anything that smells of elitism.","霍夫施塔特说，自美国历史之初，民主和平民主义的倾向就驱使我们排斥一切带有精英主义气息的事物。","正文"]],"urge.mp3",null],"urgent":[["ˈɜː.dʒᵊnt","ˈɜr·dʒənt"],["高中","CET4","CET6","考研","TOEFL","GRE"],[["副词","urgently",1]],[11,2.5,11,7,3],[["adj.","紧急的；紧迫的；迫切的",11],["adj.","催促的；急切的",0]],[["2025 英二 · 阅读 · Part A · Text 2","Together, we are calling for a much more open and honest conversation about the future of health in the UK, and an “urgent rethink” of the hospital-centric model we retain.","我们共同呼吁，就英国医疗卫生的未来开展更加开放、坦诚的讨论，并“紧急重新思考”目前沿用的以医院为中心的模式。","正文"],["2024 英二 · 阅读 · Part A · Text 2","The forestry and wood trade body has called for urgent action to reduce the country’s reliance on timber imports and provide a stable supply of wood for future generations.","这一林业和木材行业组织呼吁采取紧急行动，减少英国对木材进口的依赖，并为后代提供稳定的木材供应。","正文"],["2019 英二 · 阅读 · Part A · Text 2","The need for such planning is increasingly urgent.","制定这类规划的需要日益迫切。","正文"],["2015 英一 · 阅读 · Part A · Text 2","They could still invalidate Fourth Amendment protections when facing severe, urgent circumstances, and they could take reasonable measures to ensure that phone data are not erased or altered while waiting for a warrant.","遇到严重而紧急的情况时，他们仍可突破第四修正案的保护；等待搜查令期间，也可采取合理措施，确保手机数据不被删除或更改。","正文"],["2014 英二 · 阅读 · Part A · Text 4","It needs to put historical prejudices to one side and take some steps to address our urgent housing need.","政府需要放下历史成见，采取措施解决我们迫切的住房需求。","正文"],["2013 英一 · 阅读 · Part C","This distinction is so much so that where the latter is lacking, as it is for these unlikely gardeners, the former becomes all the more urgent.","这种区分意义重大：当后一种需求得不到满足时，就像这些意想不到的园丁那样，前一种需求反而愈加迫切。","正文"]],"urgent.mp3",{"r":[["后缀","-ent 表示形容词，“…的”。"]],"d":[["urgent-mail","n. 急件"]]}],"utilize":[["ˈjuː.tᵊl.aɪz","ˈju·t̬ᵊlˌɑɪz"],["CET4","CET6","考研","TOEFL","GRE"],[["原形","utilize"],["第三人称单数","utilizes"],["现在分词","utilizing"],["过去式","utilized"],["过去分词","utilized"],["形容词","utilizable",1],["名词","utilization",1],["名词","utilizer",1]],[2,1.0,2,1,1],[["v.","使用；利用；运用；应用",2]],[["2000 英一 · 阅读 · Part B","It also means that governments are increasingly compelled to interfere in these sectors in order to step up production and ensure that it is utilized to the best advantage.","这还意味着，政府越来越不得不干预这些部门，以提高产量并确保产品得到最有效的利用。","正文"],["2021 英二 · 阅读 · Part A · Text 2 · 第27题 · 选项A","The report by the University of Leeds shows that in the UK farmland has been inefficiently utilized.","利兹大学的报告表明，英国的农田未得到高效利用。","选项"]],"utilize.mp3",{"r":[["词根","us-,ut- = use, 表示“用”。"],["后缀","-ise, -ize 动词后缀，一般缀于形容词后。-ise 是英式英语，-ize 是美式英语。"]],"d":[["utilization","利用"],["utilizable","可利用"],["underutilize","vt. 未充分使用"]]}],"utter":[["ˈʌt.əʳ","ˈʌt̬·ər"],["CET4","CET6","考研","TOEFL","GRE"],[["原形","utter"],["第三人称单数","utters"],["现在分词","uttering"],["过去式","uttered"],["过去分词","uttered"],["形容词","utterable",1],["名词","utterer",1],["副词","utterly",1],["名词","utterness",1]],[0,0.0,0,0,0],[["adj.","完全的；十足的；彻底的",0],["v.","出声；说；讲",0]],[],"utter.mp3",null],"ultimate":[["ˈʌl.tɪ.mət","ˈʌl·tə·mət"],["CET4","CET6","考研","TOEFL","GRE"],[["复数","ultimates"],["原形","ultimate"],["第三人称单数","ultimates"],["现在分词","ultimating"],["过去式","ultimated"],["过去分词","ultimated"],["名词","ultimateness",1],["名词","ultimation",1]],[5,2.0,5,5,0],[["adj.","最后的；最终的；终极的",4],["adj.","极端的；最好（或坏、伟大、重要等）的",1],["adj.","根本的；基本的；基础性的",0],["n.","最好（或先进、伟大等）的事物；极品；精华",0]],[["2021 英一 · 阅读 · Part B","“There are experiments that show that, naturally, the results of interviews are much more biased than what AI does,” says Pedro Domingos, author of The Master Algorithm: How the Quest for the Ultimate Learning Machine Will Remake Our World and a computer science professor at the University of Washington.","《终极算法：对终极学习机器的探索将如何重塑我们的世界》一书作者、华盛顿大学计算机科学教授佩德罗·多明戈斯说：\"有实验表明，面试结果自然比人工智能得出的结果偏见大得多。\"","正文"],["2018 英一 · 阅读 · Part A · Text 4","And interest groups ranging from postal unions to greeting-card makers exert self-interested pressure on the USPS’s ultimate overseer — Congress — insisting that whatever else happens to the Postal Service, aspects of the status quo they depend on get protected.","从邮政工会到贺卡制造商，各种利益集团都向美国邮政署的最终监管者——国会——施加只顾自身利益的压力，坚持要求不管邮政署发生什么变化，他们所依赖的现状中某些方面必须得到保护。","正文"],["2009 英一 · 阅读 · Part C","If humanity has made some headway in realizing that the ultimate value of every institution is its distinctively human effect we may well believe that this lesson has been learned largely through dealings with the young.","如果人类已经在认识到每种制度的最终价值在于其对人所特有的影响这一点上取得一些进展，我们大可以相信，这一认识主要来自与年轻人的交往。","正文"],["2003 英一 · 阅读 · Part A · Text 2","Finally, because the ultimate stakeholders are patients, the health research community should actively recruit to its cause not only well-known personalities such as Stephen Cooper, who has made courageous statements about the value of animal research, but all who receive medical treatment.","最后，鉴于最终的利益攸关者是患者，医疗研究界应积极争取所有接受医疗服务的人支持这一事业，而不只是争取斯蒂芬·库珀等知名人士；库珀曾勇敢地公开肯定动物研究的价值。","正文"],["2001 英一 · 阅读 · Part A · Text 4","This phenomenon has created serious concerns over the role of smaller economic firms, of national businessmen and over the ultimate stability of the world economy.","这一现象引发人们严重担忧：规模较小的企业和本国企业家将扮演什么角色，世界经济最终又能否保持稳定。","正文"]],"ultimate.mp3",{"r":[["词根","ultim- = last, 表示“最后的”。"]],"d":[["ultimately","adv. 最后;最终"],["ultimatum","n. 最后通牒；最后结论；基本原理"],["penultimate","倒数第二的"],["ultimateness","n. 结论,终结"]]}],"underestimate":[["ˌʌn.dəˈres.tɪ.meɪt；ˌʌn.dəˈres.tɪ.mət","ˌʌn·dəˈres·təˌmeɪt"],["CET6","考研","TOEFL","IELTS"],[["原形","underestimate"],["第三人称单数","underestimates"],["现在分词","underestimating"],["过去式","underestimated"],["过去分词","underestimated"],["名词","underestimation",1]],[12,2.5,11,2,6],[["v.","低估；对…估计不足",5],["v.","对…认识不足（或重视不够）；低估；轻视",5],["n.","低估；轻视",2]],[["2022 英一 · 阅读 · Part B","But she underestimates the educational value of zoos.","但她低估了动物园的教育价值。","正文"],["2006 英一 · 阅读 · Part A · Text 3","Some individuals would therefore not have been caught, since no baited hooks would have been available to trap them, leading to an underestimate of fish stocks in the past.","因此，有些鱼没有上钩，因为已经没有带饵的钩子可以钓到它们；这会导致对过去鱼类种群数量的低估。","正文"],["2026 英二 · 阅读 · Part A · Text 2 · 第30题 · 选项B","According to the last paragraph, we may easily fall victim to AI as we underestimate its economic costs.","根据最后一段，我们可能轻易成为人工智能的受害者，因为我们低估其经济成本。","选项"],["2026 英一 · 阅读 · Part A · Text 4 · 第38题 · 选项C","What did the study find about the wildfires over the past few decades? Their threats have been underestimated.","这项研究对过去几十年的野火有什么发现？野火带来的威胁被低估了。","选项"],["2025 英一 · 阅读 · Part A · Text 3 · 第34题 · 选项D","According to Hawley, digital piracy has been underestimated by some analysts.","霍利认为，一些分析人士低估了数字盗版问题。","选项"],["2025 英二 · 完形","The findings showed that help-seekers generally underestimate how willing other people will be to help and how good it will make the help-giver feel (for most people, having the chance to help someone is highly rewarding ).","研究发现，求助者通常低估别人愿意帮忙的程度，也低估帮助他人会让施助者感觉多好（对大多数人来说，有机会帮助别人非常令人满足）。",""]],"underestimate.mp3",{"r":[["前缀","under- = beneath, below, underneath, 表示“在…下”，源自古英语。和源自拉丁语的前缀 infra- 同源。"],["词根","estim-,esteem- = value, 表示“价值”，来源于拉丁语 estimare 价值。es-=ase 表示铜，tim- 表示砍，字面含义“砍铜的人”，引申估价、尊重等。"],["后缀","-ate 表动词，“做，造成”。"]],"d":[["underestimated","vt. 对…估计不足, 低估 n. 估计不足, 低估"],["underestimation","n. 过低之估价"]]}],"undergo":[["ˌʌn.dəˈɡəʊ","ˌʌn·dərˈɡoʊ"],["CET4","CET6","考研","TOEFL","IELTS"],[["原形","undergo"],["现在分词","undergoing"],["过去式","underwent"],["过去分词","undergone"]],[5,2.0,4,3,2],[["v.","经历，经受（变化、不快的事等）",5]],[["2017 英一 · 阅读 · Part A · Text 2","Hawaiian culture is not a relic of the past; it is a living culture undergoing a renaissance today.","夏威夷文化不是过去的遗物；它是一种今天正经历复兴的活文化。","正文"],["2000 英一 · 阅读 · Part A · Text 3","Consequently, our feelings, thoughts and emotions have undergone a corresponding change.","因而，我们的感受、思想和情绪也发生了相应变化。","正文"],["2000 英一 · 阅读 · Part B","For example, (34) in the early industrialized countries of Europe the process of industrialization — with all the far-reaching changes in social patterns that followed — was spread over nearly a century, whereas nowadays a developing nation may undergo the same process in a decade or so.","例如，（34）在欧洲那些早期实现工业化的国家，工业化的过程及其随后带来的所有深远的社会形态变化，延续了近一个世纪；而如今，一个发展中国家可能在十年左右经历同样的过程。","正文"],["2026 英一 · 阅读 · Part A · Text 1 · 第21题 · 选项B","What can be learned about donkeys from Paragraph 1? They underwent multiple domestication events.","从第一段可以了解到驴的什么情况？驴经历过多次驯化。","选项"],["2024 英一 · 阅读 · Part A · Text 1 · 第24题 · 选项A","It can be learned from Paragraph 5 that nails have undergone many technological improvements.","从第五段可以了解到，钉子经历了许多技术改进。","选项"]],"undergo.mp3",{"r":[["前缀","under- = beneath, below, underneath, 表示“在…下”，源自古英语。和源自拉丁语的前缀 infra- 同源。"]],"d":[]}],"underlie":[["ˌʌn.dəˈlaɪ","ˌʌn·dərˈlɑɪ"],["考研","TOEFL"],[["原形","underlie"],["第三人称单数","underlies"],["现在分词","underlying"],["过去式","underlay"],["过去分词","underlain"]],[5,2.0,5,4,1],[["v.","构成…的基础；作为…的原因",5]],[["2023 英二 · 阅读 · Part A · Text 4","Is there some common factor that underlies these apparently contradictory developments?","这些看似矛盾的发展背后，是否存在某种共同因素？","正文"],["2017 英一 · 阅读 · Part A · Text 4","“The basic compact underlying representative government,” wrote Chief Justice John Roberts for the court, “assumes that public officials will hear from their constituents and act on their concerns.”","首席大法官约翰·罗伯茨代表法院写道：“代议制政府赖以建立的基本约定，预设公职人员会倾听选民的意见，并回应他们关切的问题。”","正文"],["2005 英一 · 阅读 · Part A · Text 1","Such behaviour is regarded as “all too human,” with the underlying assumption that other animals would not be capable of this finely developed sense of grievance.","这种反应被视为“太符合人性了”，其背后的假设是，其他动物不可能具有这种高度发达的委屈感。","正文"],["2001 英一 · 阅读 · Part A · Text 4","I believe that the most important forces behind the massive M&A wave are the same that underlie the globalization process: falling transportation and communication costs, lower trade and investment barriers and enlarged markets that require enlarged operations capable of meeting customers’ demands.","我认为，推动大规模并购浪潮的最重要力量，也正是推动全球化的力量：运输和通信成本下降、贸易和投资壁垒降低，以及市场扩大，从而需要企业扩大经营规模以满足顾客需求。","正文"],["2004 英一 · 阅读 · Part A · Text 4 · 第40题 · 选项D","What does the author think of intellect? It underlies power.","作者如何看待智识？智识是权力的基础。","选项"]],"underlie.mp3",{"r":[["前缀","under- = beneath, below, underneath, 表示“在…下”，源自古英语。和源自拉丁语的前缀 infra- 同源。"],["词根","lag-,law,lay- 这是一组同源词，原始含义表示 \"to lay, put, place 放下\"。其原始印欧语形式为 *legh。law 词义由“放置”引申为“法律”。"]],"d":[]}],"underlying":[["ˌʌn.dəˈlaɪ.ɪŋ","ˌʌn·dərˈlɑɪ·ɪŋ"],["CET6","考研","TOEFL","IELTS","GRE"],[],[2,1.0,2,2,0],[["adj.","根本的；潜在的；隐含的",2],["adj.","表面下的；下层的",0]],[["2020 英二 · 阅读 · Part A · Text 4","The booming economy seems to have done little to assuage this underlying generational sense of anxious urgency, especially for those who have college debt.","蓬勃的经济似乎几乎没有缓解这一代人心底的焦虑和紧迫感，尤其是对那些背负大学贷款的人而言。","正文"],["2005 英一 · 阅读 · Part A · Text 1","Such behaviour is regarded as “all too human,” with the underlying assumption that other animals would not be capable of this finely developed sense of grievance.","这种反应被视为“太符合人性了”，其背后的假设是，其他动物不可能具有这种高度发达的委屈感。","正文"]],"underlying.mp3",{"r":[["前缀","under- = beneath, below, underneath, 表示“在…下”，源自古英语。和源自拉丁语的前缀 infra- 同源。"],["词根","lag-,law,lay- 这是一组同源词，原始含义表示 \"to lay, put, place 放下\"。其原始印欧语形式为 *legh。law 词义由“放置”引申为“法律”。"],["后缀","-ing 表形容词，“正…的”，“令人…的”。"]],"d":[]}],"underline":[["ˌʌn.dəˈlaɪn","ˈʌn·dərˌlɑɪn"],["高中","CET4","CET6","考研","IELTS"],[["复数","underlines"],["原形","underline"],["第三人称单数","underlines"],["现在分词","underlining"],["过去式","underlined"],["过去分词","underlined"]],[33,4.0,28,4,0],[["v.","在（词语等下）画线；画底线标出",29],["v.","强调；突出",4]],[["2024 英一 · 阅读 · Part A · Text 1","The idea that one might burn down an entire house just to reclaim the nails underlines how scarce, costly and valuable the simple-seeming technology was.","有人竟会为了取回钉子而烧掉整栋房屋，这一想法凸显了这项看似简单的技术当时何等稀缺、昂贵而有价值。","正文"],["2018 英二 · 阅读 · Part A · Text 2","President Trump has underlined fossil fuels — especially coal — as the path to economic growth.","特朗普总统强调，化石燃料，尤其是煤炭，是经济增长之路。","正文"],["2018 英一 · 阅读 · Part A · Text 1","The challenge of coping with automation underlines the need for the U.S. to revive its fading business dynamism: Starting new companies must be made easier.","应对自动化的挑战凸显出美国重振日渐衰退的商业活力的必要性：必须让创办新公司变得更容易。","正文"],["2005 英一 · 阅读 · Part C","(48) This alone demonstrates that the television business is not an easy world to survive in, a fact underlined by statistics that show that out of eighty European television networks, no less than 50% took a loss in 1989.","（48）仅这一点就表明，在电视行业生存并不容易；统计数据进一步证实了这一事实：1989年，欧洲80家电视网中至少有50%处于亏损状态。","正文"],["2026 英一 · 阅读 · Part C","Read the following text carefully and then translate the underlined segments into Chinese.","仔细阅读下文，然后将画线部分译成中文。",""],["2017 英一 · 阅读 · Part A · Text 4 · 第36题 · 选项C","The underlined sentence (Para. 1) most probably shows that the court was contemptuous of McDonnell’s conduct.","第1段中画线的句子最有可能表明，法院对麦克唐纳的行为十分鄙视。","题干"]],"underline.mp3",{"r":[["前缀","under- = beneath, below, underneath, 表示“在…下”，源自古英语。和源自拉丁语的前缀 infra- 同源。"],["词根","line-,lign- = line, 表示“直线，线条”。lign- 是来自法语的变体。"]],"d":[]}],"understand":[["ˌʌn.dəˈstænd","ˌʌn·dərˈstænd"],["中考","高中","TOEFL"],[["原形","understand"],["第三人称单数","understands"],["现在分词","understanding"],["过去式","understood"],["过去分词","understood"],["名词","understandability",1],["形容词","understandable",1]],[59,4.5,31,42,2],[["v.","懂；理解；领会",35],["v.","了解；认识到；明了",15],["v.","了解；谅解；体谅",8],["v.","得知；据信；认为",1],["v.","默认；默许；不言而喻",0],["v.","领会；清楚；推断出",0]],[["2026 英一 · 阅读 · Part A · Text 1","But understanding where the animals were first domesticated could guide archaeologists to a narrow region to search for insights about the original tamed donkeys.","不过，弄清这些动物最初在哪里被驯化，可以帮助考古学家缩小寻找范围，以发掘有关最早驯养的驴的线索。","正文"],["2026 英一 · 阅读 · Part A · Text 1","Not only does understanding the equines’ genetic makeup help reveal their contribution to human history, but it also might improve their management in the future, as climate change alters the planet’s environment, write the authors.","作者写道，了解这些马科动物的遗传构成，不仅有助于揭示它们对人类历史的贡献；随着气候变化改变地球环境，这种了解也可能改善未来对它们的管理。","正文"],["2025 英一 · 阅读 · Part A · Text 2","However, this is a price we must pay for understanding the world.","然而，这是我们为了解世界必须付出的代价。","正文"],["2025 英一 · 阅读 · Part A · Text 4","Librarians are uniquely positioned to understand how end users seek and use information.","图书馆员在理解最终用户如何寻找和使用信息方面具有独特优势。","正文"],["2025 英二 · 阅读 · Part B","Instead, listen to their concerns fully, try to understand their perspective, and include their concerns (and possible remedies) in future discussions.","相反，要充分倾听他们的顾虑，试着理解他们的立场，并在之后的讨论中考虑他们的顾虑（以及可能的解决办法）。","正文"],["2025 英一 · 阅读 · Part C","You don’t even need any formal training, just an inquisitive mind and the enthusiasm to join one of the thousands of citizen science projects to generate new knowledge and the means to understand a genuine scientific outcome.","你甚至不需要接受任何正规培训，只需有一颗好奇心，并热衷于加入数千个公民科学项目之一，创造新知识，并获得理解真正科学成果的方法。","正文"]],"understand.mp3",{"r":[["前缀","under- = beneath, below, underneath, 表示“在…下”，源自古英语。和源自拉丁语的前缀 infra- 同源。"],["词根","st-,sta-,stat-,stan-,stant-,stin- = stand, 表示“站、立”。"]],"d":[["misunderstand","vt. 误会, 误解"],["understanding","理解"],["understandable","adj. 能懂的;可理解的;可同情的"]]}],"understanding":[["ˌʌn.dəˈstæn.dɪŋ","ˌʌn·dərˈstæn·dɪŋ"],["高中","CET4","CET6","考研","IELTS"],[["复数","understandings"],["副词","understandingly",1],["形容词","ununderstanding",1]],[22,3.5,19,13,3],[["n.","理解；领悟；了解",14],["n.","理解；谅解；体谅",4],["n.","（非正式的）协议",0],["n.","理解；看法；解释；意见",4],["adj.","善解人意的；富有同情心的；体谅人的",0]],[["2025 英一 · 阅读 · Part A · Text 1","She added “The emotional understanding was very evident and it is probably related to the [rehearsal room process] where you are used to trying to imagine your way through.","她补充说：“他们对情感的理解表现得非常明显，这可能与‘排练室过程’有关，在这个过程中，你习惯于发挥想象，设身处地去体会。","正文"],["2025 英二 · 阅读 · Part A · Text 2","What health functions should remain at the centre, and what should be given to local leaders, often responsible for services that create health, and with a much better understanding of the needs of their populations?","哪些卫生职能应继续由中央承担，哪些又应交给地方领导者？他们往往负责提供促进健康的服务，也更了解当地居民的需求。","正文"],["2019 英二 · 阅读 · Part A · Text 1","Yet this understanding is outdated.","然而，这种认识已经过时。","正文"],["2017 英一 · 阅读 · Part A · Text 4","Good government rests on an understanding of the inherent worth of each individual.","良好的治理建立在承认每个人都具有内在价值的基础之上。","正文"],["2017 英二 · 阅读 · Part A · Text 3","This isn’t surprising, considering the basic mandatory high school curriculum leaves students with a poor understanding of the vast academic possibilities that await them in college.","这并不奇怪：高中规定的基础课程让学生对大学里等待着他们的众多专业方向了解甚少。","正文"],["2015 英二 · 阅读 · Part B","When our time of mourning is over, we press forward, stronger with a greater understanding and respect for life.","哀悼的时日过去后，我们继续前行，变得更加坚强，对生命也有了更深的理解和敬重。","正文"]],"understanding.mp3",{"r":[["前缀","under- = beneath, below, underneath, 表示“在…下”，源自古英语。和源自拉丁语的前缀 infra- 同源。"],["词根","st-,sta-,stat-,stan-,stant-,stin- = stand, 表示“站、立”。"],["后缀","-ing 名词后缀，表示动词的动作或其过程、状态；表示用于制作或形成某物的材料；表示动作的结果或产物。"]],"d":[]}],"undertake":[["ˌʌn.dəˈteɪk","ˌʌn·dərˈteɪk"],["高中","CET4","CET6","考研","TOEFL","IELTS"],[["原形","undertake"],["第三人称单数","undertakes"],["现在分词","undertaking"],["过去式","undertook"],["过去分词","undertaken"]],[1,0.5,1,0,0],[["v.","承担；从事；负责",1],["v.","承诺；允诺；答应",0]],[["2024 英二 · 阅读 · Part B · 选项C","Undertaking too many extracurricular activities will hardly be seen as a plus by colleges.","参加过多课外活动几乎不会被大学视为加分项。","选项"]],"undertake.mp3",{"r":[["前缀","under- = beneath, below, underneath, 表示“在…下”，源自古英语。和源自拉丁语的前缀 infra- 同源。"],["词根","tact-,tag-,tig-,ting- = touch, 表示“接触”。"]],"d":[["undertaking","n. 任务;事业 企业;工作 保证;许诺 殡仪业"],["undertaker","n. 殡仪业人员"],["undertaken","undertaked的过去分词"]]}],"uneasy":[["ʌnˈiː.zi","ʌnˈi·zi"],["CET4","CET6","考研","IELTS"],[["比较级","uneasier"],["最高级","uneasiest"],["名词","uneasiness",1],["副词","uneasily",1]],[2,1.0,2,1,0],[["adj.","担心的；忧虑的；不安的",2],["adj.","不稳定的；靠不住的；不确定的",0],["adj.","令人不安的；令人不舒服的；不安稳的",0],["adj.","不和谐的；不协调的；矛盾的",0]],[["2016 英二 · 阅读 · Part A · Text 2","In particular, they called for forging closer collaborations with western state governments, which are often uneasy with federal action, and with the private landowners who control an estimated 95% of the prairie chicken’s habitat.","他们尤其呼吁与西部各州政府和私人土地所有者建立更紧密的合作：前者常对联邦行动感到不安，后者控制着据估计95%的小草原松鸡栖息地。","正文"],["2014 英一 · 阅读 · Part A · Text 1 · 第24题 · 选项A","According to Paragraph 3, being unemployed makes one feel uneasy.","根据第3段，失业会让人感到不安。","选项"]],"uneasy.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","eas- = easy, 表示“舒适的”。"]],"d":[["uneasiness","n. 担心;不安;局促;拘束"]]}],"unemployment":[["ˌʌn.ɪmˈplɔɪ.mənt","ˌʌn·ɪmˈplɔɪ·mənt"],["高中","CET6","考研","IELTS"],[],[16,3.0,9,10,3],[["n.","失业；失业人数",13],["n.","无业；没有工作",2],["n.","失业（状态）",1]],[["2021 英二 · 阅读 · Part A · Text 1","With the pandemic, unemployment is very high indeed.","疫情暴发后，失业率确实很高。","正文"],["2021 英二 · 阅读 · Part A · Text 1","In February, at 3.5 percent and 5.5 percent respectively, unemployment rates in Canada and the U.S. were at generational lows and worker shortages were everywhere.","2月，加拿大和美国的失业率分别为3.5%和5.5%，处于几代人以来的低位，各地都缺少劳动力。","正文"],["2021 英二 · 阅读 · Part A · Text 1","Efforts in Canada and elsewhere have been arguably languid at best, and have given us a situation where we frequently hear of employers begging for workers even at times and in regions where unemployment is high.","可以说，加拿大等地的行动充其量也只是迟缓无力，结果造成一种局面：我们经常听到雇主求贤若渴，即使在失业率高的时期和地区也是如此。","正文"],["2021 英一 · 阅读 · Part B","When it comes to AI in business, we often hear about it in relation to automation and the impending loss of jobs, but in what ways is AI changing companies and the larger economy that don’t involve doom-and-gloom mass unemployment predictions?","说到商业领域的人工智能，我们经常听到它与自动化和即将到来的失业潮有关；但不涉及大规模失业这类悲观预测的人工智能应用，又是如何改变企业和更广泛的经济的？","正文"],["2017 英一 · 阅读 · Part A · Text 3","By most recent measures, the UK’s GDP has been the envy of the Western world, with record low unemployment and high growth figures.","按大多数近期指标衡量，英国的GDP令西方世界艳羡：失业率创历史新低，增长数据很高。","正文"],["2015 英二 · 阅读 · Part A · Text 4","Many people talked of the 288,000 new jobs the Labor Department reported for June, along with the drop in the unemployment rate to 6.1 percent, as good news.","许多人把劳工部报告的6月份新增28.8万个岗位以及失业率降至6.1%，视为好消息。","正文"]],"unemployment.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["前缀","em,en- 表示“入、内、在...之内、使...”，来自古法语 en-。在字母 b, m, p 前拼写同化为 em-。"],["词根","ploy- = use, 表示“用，参与”，和表示折叠的词根 ply- 同源。"],["后缀","-ment 表名词，“行为或结果”。"]],"d":[]}],"unexpected":[["ˌʌn.ɪkˈspek.tɪd","ˌʌn·ɪkˈspek·tɪd"],["CET4","CET6","考研"],[["副词","unexpectedly",1],["名词","unexpectedness",1]],[7,2.0,7,3,1],[["adj.","出乎意料的；始料不及的",7]],[["2014 英二 · 阅读 · Part A · Text 3","In our rapidly changing economy, we more than ever need people in the workplace who can take initiative and exercise their imagination “to respond to unexpected events”.","在快速变化的经济中，我们比以往任何时候都更需要能够主动作为、发挥想象力以“应对意外事件”的职场人员。","正文"],["2010 英一 · 阅读 · Part A · Text 3","The theory also seems to explain the sudden and unexpected popularity of certain looks, brands, or neighborhoods.","这一理论似乎也能解释某些造型、品牌或街区为何会突然出人意料地走红。","正文"],["2002 英一 · 阅读 · Part A · Text 1","It often comes from the unexpected.","它往往来自出人意料的地方。","正文"],["2026 英一 · 阅读 · Part A · Text 3 · 第33题 · 选项C","It is indicated in Paragraph 4 that radio listeners could make unexpected gains.","第四段表明，广播听众可能有意想不到的收获。","选项"],["2022 英二 · 翻译","Unexpected results have two benefits: you pretty quickly learn to deal with disappointment and realise that when one door closes, another opens.","意料之外的结果有两个好处：你会很快学会面对失望，并意识到一扇门关上时，另一扇门会打开。",""],["2020 英二 · 翻译","Failing at something can help you discover your truest friends, or help you find unexpected motivation to succeed.","在某件事上失败，能帮你认清谁是真正的朋友，也可能帮你找到意想不到的成功动力。",""]],"unexpected.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","spect-,spic- = look, see, 表示“看”，引申为“光谱”。源自拉丁语 specere \"to look, to see\"。"],["前缀","e-,ef-,ex- 表示“从，从...离开，从...向外，向外，向上”，来自PIE *eghs, 向外。该原始印欧语根进入希腊语产生变体形式 ek-, 进入英语拼写演变为 ec-；进入拉丁语演变成 ex-；在浊辅音 b, d, g 和半辅音 j, l, m, n, r, v 前缩写成 e-；在字母f前同化为 ef-。"],["后缀","-ed 形容词后缀，加在名词后表示“如...的”；加在动词后表示“被...的”。"]],"d":[]}],"unify":[["ˈjuː.nɪ.faɪ","ˈju·nəˌfɑɪ"],["CET6","考研","TOEFL","IELTS","GRE"],[["原形","unify"],["第三人称单数","unifies"],["现在分词","unifying"],["过去式","unified"],["过去分词","unified"],["形容词","unifiable",1],["名词","unifier",1]],[4,1.5,1,3,0],[["v.","统一；使成一体；使一元化",4]],[["2012 英二 · 阅读 · Part A · Text 1","It is not too late for L.A. Unified to do homework right.","洛杉矶联合学区现在还来得及把家庭作业这件事做好。","正文"],["2012 英二 · 阅读 · Part A · Text 1","School districts across the country, most recently Los Angeles Unified, are revising their thinking on this educational ritual.","全国各地的学区，最近还有洛杉矶联合学区，都在重新审视这种教育惯例。","正文"],["2012 英二 · 阅读 · Part A · Text 1","Unfortunately, L.A. Unified has produced an inflexible policy which mandates that with the exception of some advanced courses, homework may no longer count for more than 10% of a student’s academic grade.","遗憾的是，洛杉矶联合学区出台了一项僵硬的政策，规定除部分高级课程外，家庭作业在学生学业成绩中所占的比重不得超过10%。","正文"],["2012 英二 · 阅读 · Part A · Text 1 · 第22题 · 选项C","22. L.A. Unified has made the rule about homework mainly because poor students may have problems finishing their homework.","22. 洛杉矶联合学区制定这项有关家庭作业的规定，主要是因为贫困学生在完成家庭作业时可能遇到困难。","题干"]],"unify.mp3",{"r":[["前缀","un,uni = one, 表示“单一、一个”。"],["后缀","-fy,-ify 缀于名词或形容词后，构成表示“使成…”“…化”“作成…”等意思的动词"]],"d":[["reunify","vt. 使重新统一；再统一，再联合"],["unifier","n. 统一者"],["unifying","vt. （unify的过去分词）使成一体；使统一"],["unifiable","adj. 可联合的,可统一的,能一致的"],["unification","n. 统一,联合,一致"]]}],"union":[["ˈjuː.njən","ˈjun·jən"],["高中","CET4","CET6","考研","TOEFL","IELTS"],[["复数","unions"]],[32,4.0,10,18,5],[["n.","工会",22],["n.","协会；联合会；会社；俱乐部",3],["n.","同盟；联盟；联邦",6],["n.","（尤指内战时期的）美利坚合众国，美国",0],["n.","联合；结合；合并",0],["n.","结为夫妻；婚姻",1]],[["2026 英一 · 阅读 · Part A · Text 2","If that sounds melodramatic, consider this: The Art Directors Guild, a labor union representing about 3,000 film workers, has suspended a training program and issued a statement explaining that “we cannot in good conscience encourage you to pursue our profession” This is a reaction to Hollywood’s decline, which is reaching a critical point for the industry and Southern California.","如果这听起来太夸张，不妨看看这件事：代表约3000名电影从业者的工会——艺术指导协会——暂停了一项培训计划，并发表声明称，“凭良心说，我们不能鼓励你们投身这一职业”。这是对好莱坞衰落的回应，而这种衰落正使行业和南加州走向危急关头。","正文"],["2021 英一 · 阅读 · Part A · Text 1","The responsibility for the latest wave of strikes rests on the unions.","最近这一波罢工的责任在工会。","正文"],["2020 英一 · 阅读 · Part A · Text 4","At the same time, the European Union, Spain, Britain and several other countries have all seriously contemplated digital services taxes.","与此同时，欧盟、西班牙、英国和其他几个国家也都认真考虑过征收数字服务税。","正文"],["2018 英一 · 阅读 · Part A · Text 4","The latter step would largely offset the financial burden of annually pre-funding retiree health care, thus addressing a long-standing complaint by the USPS and its unions.","后一项举措将大体抵消每年预先拨付退休人员医疗费用的财政负担，从而回应美国邮政署及其工会长期以来的抱怨。","正文"],["2018 英一 · 阅读 · Part A · Text 4","Now comes word that everyone involved — Democrats, Republicans, the Postal Service, the unions and the system’s heaviest users — has finally agreed on a plan to fix the system.","如今有消息称，所有相关方——民主党、共和党、邮政署、工会和该体系的最大用户——终于就一项修复方案达成一致。","正文"],["2018 英一 · 阅读 · Part A · Text 4","And interest groups ranging from postal unions to greeting-card makers exert self-interested pressure on the USPS’s ultimate overseer — Congress — insisting that whatever else happens to the Postal Service, aspects of the status quo they depend on get protected.","从邮政工会到贺卡制造商，各种利益集团都向美国邮政署的最终监管者——国会——施加只顾自身利益的压力，坚持要求不管邮政署发生什么变化，他们所依赖的现状中某些方面必须得到保护。","正文"]],"union.mp3",{"r":[["前缀","un,uni = one, 表示“单一、一个”。"],["后缀","-ion,-ation,-ition 表名词，“行为、动作、状态、过程、结果；物品”等。"]],"d":[["reunion","n. 重聚"],["unionize","1. vt. 使……加入工会；使……成立工会 2. vi. 加入工会；成立工会"],["disunion","n. 分裂；分开；不统一"],["malunion","n. [医]骨连接不正"],["nonunion","1. adj. 不属于工会的；不承认工会的 2. n. 骨折不愈合"]]}],"unique":[["juːˈniːk","jʊˈnik"],["高中","CET4","CET6","考研","TOEFL","IELTS","GRE"],[["副词","uniquely",1],["名词","uniqueness",1],["名词","uniquity",1]],[23,3.5,17,13,2],[["adj.","唯一的；独一无二的",2],["adj.","独特的；罕见的",12],["adj.","（某人、地或事物）独具的，特有的",9]],[["2026 英二 · 阅读 · Part A · Text 4","We are eliminating a stage, booking fewer performers and making additional cuts to reduce our costs, all while striving to keep the festival as vibrant as ever, as supportive of local artists and businesses, and as true to Wicker Park’s unique spirit and reputation as festgoers have come to expect.","我们取消一个舞台，少请一些表演者，并采取其他削减措施以降低成本；与此同时，我们仍努力保持节庆一贯的活力，继续支持本地艺术家和商家，不辜负参加者对威克公园独特精神与声誉的期待。","正文"],["2024 英二 · 阅读 · Part B","“Again, since one of the big questions high school seniors must consider is ‘What makes you unique?,’ having an uncommon extracurricular activity vs. a conventional one is an advantage,” he wrote in an email.","他在邮件中写道：“再说，高中毕业班学生必须思考的一个重要问题是‘你有什么独特之处？’因此，与参加常规活动相比，拥有不常见的课外活动是一个优势。”","正文"],["2023 英一 · 阅读 · Part C","(46) AI can also be used to identify the lifestyle choices of customers regarding their hobbies, favourite celebrities, music choices, and fashions to provide unique content in marketing messages put out through social media.","（46）人工智能还可以识别客户在爱好、喜爱的名人、音乐选择和时尚方面的生活方式偏好，从而为通过社交媒体发布的营销信息提供独特内容。","正文"],["2015 英一 · 阅读 · Part A · Text 3","He agreed to join because he “found the foresight behind the establishment of the SBoRE to be novel, unique and likely to have a lasting impact.","他同意加入，是因为他“认为设立SBoRE的远见新颖、独特，而且很可能产生持久影响。","正文"],["2014 英二 · 阅读 · Part A · Text 1","It is far better to spend money on experiences, say Ms Dunn and Mr Norton, like interesting trips, unique meals or even going to the cinema.","邓恩女士和诺顿先生说，把钱花在体验上要好得多，例如有趣的旅行、别具一格的美食，甚至看一场电影。","正文"],["2013 英二 · 阅读 · Part A · Text 1","Therefore, everyone needs to find their extra — their unique value contribution that makes them stand out in whatever is their field of employment.","因此，每个人都需要找到自己的额外优势——独特的价值贡献，使自己在所从事的领域脱颖而出。","正文"]],"unique.mp3",{"r":[["前缀","un,uni = one, 表示“单一、一个”。"]],"d":[["uniqueness","n. 唯一性;单值性;独特性"]]}],"universal":[["ˌjuː.nɪˈvɜː.sᵊl","ˌju·nəˈvɜr·səl"],["高中","CET4","CET6","考研","TOEFL","IELTS"],[["复数","universals"],["副词","universally",1],["名词","universalness",1]],[9,2.5,6,8,0],[["adj.","普遍的；全体的；全世界的；共同的",3],["adj.","普遍存在的；广泛适用的",4],["n.","普遍存在的事物或现象",1],["noun","共同点",1]],[["2022 英一 · 阅读 · Part A · Text 2","As degrees became universal, they became devalued.","随着学位变得普遍，其价值也降低了。","正文"],["2012 英一 · 阅读 · Part C","Since the days of Aristotle, a search for universal principles has characterized the scientific enterprise.","自亚里士多德时代以来，探寻普遍原理一直是科学事业的特征。","正文"],["2012 英一 · 阅读 · Part C","Neither of these patterns is borne out by the analysis, suggesting that the structures of the languages are lineage-specific and not governed by universals.","分析结果并未证实这两种模式中的任何一种，这表明语言结构因谱系而异，并非由普遍规律支配。","正文"],["2012 英一 · 阅读 · Part C","The most famous of these efforts was initiated by Noam Chomsky, who suggested that humans are born with an innate language-acquisition capacity that dictates a universal grammar.","这些尝试中最著名的一项由诺姆·乔姆斯基发起。他认为人类生来就具备先天的语言习得能力，而这种能力决定了一套普遍语法。","正文"],["2012 英二 · 阅读 · Part B","“Universal history, the history of what man has accomplished in this world, is at bottom the History of the Great Men who have worked here,” wrote the Victorian sage Thomas Carlyle.","维多利亚时代的思想家托马斯·卡莱尔写道：“世界通史，即人类在这个世界上取得成就的历史，归根结底就是在这里有所作为的伟人们的历史。”","正文"],["2012 英一 · 阅读 · Part C","Just as the bewildering variety of human courtship rituals might all be considered forms of sexual selection, perhaps the world’s languages, music, social and religious customs and even history are governed by universal features.","正如人类繁多得令人眼花缭乱的求偶仪式都可被视为性选择的表现形式一样，也许世界各地的语言、音乐、社会和宗教习俗，乃至历史，都受普遍特征支配。","正文"]],"universal.mp3",{"r":[["前缀","un,uni = one, 表示“单一、一个”。"],["词根","ver-,vers-,vert-,vir- = turn, 表示“转”，来自拉丁语。"],["后缀","-al,-ial 表形容词，“…的”，一般缀于名词后。"]],"d":[["universally","普遍地"],["universalism","普遍性"],["universalist","普"],["universality","n. 普遍性；通用性；普适性；一般性 (知识、才能、兴趣等的)多方面性，广泛性"],["universalize","vt. 使一般化,使普遍化"]]}],"universe":[["ˈjuː.nɪ.vɜːs","ˈju·nəˌvɜrs"],["高中","CET4","CET6","考研","TOEFL"],[["复数","universes"]],[4,1.5,3,4,0],[["n.","宇宙；天地万物；万象",3],["n.","（已知宇宙以外的）宇宙",1],["n.","（某种）经验（或活动）领域；体系",0]],[["2020 英一 · 阅读 · Part C","(47) Before each of their revelations, many thinkers at the time had sustained more ancient ways of thinking, including the geocentric view that the Earth was at the centre of our universe.","（47）在他们各自揭示新发现之前，当时许多思想家一直沿袭更古老的思维方式，其中包括认为地球位于宇宙中心的地心说。","正文"],["2020 英一 · 阅读 · Part C","(48) Despite attempts by the Church to suppress this new generation of logicians and rationalists, more explanations for how the universe functioned were being made at a rate that the people could no longer ignore.","（48）尽管教会试图压制新一代逻辑学家和理性主义者，关于宇宙如何运作的解释仍接连出现，速度之快已让人们无法忽视。","正文"],["2013 英一 · 阅读 · Part A · Text 3","Take a broader look at our species’ place in the universe, and it becomes clear that we have an excellent chance of surviving for tens, if not hundreds, of thousands of years.","从更广阔的视角审视人类这一物种在宇宙中的位置，就会明白我们很有可能再存续数万年，甚至数十万年。","正文"],["2012 英一 · 阅读 · Part C","It is becoming less clear, however, that such a theory would be a simplification, given the dimensions and universes that it might entail.","然而，考虑到这种理论可能涉及的维度和宇宙，它是否真能简化问题，正变得越来越不明确。","正文"]],"universe.mp3",{"r":[["前缀","un,uni = one, 表示“单一、一个”。"],["词根","ver-,vers-,vert-,vir- = turn, 表示“转”，来自拉丁语。"]],"d":[["university","大学"],["universal","adj. 全体的 广泛的, 普遍的 在世界各地的, 世界性的"]]}],"unlike":[["ʌnˈlaɪk","ʌnˈlɑɪk"],["高中","CET4","CET6","考研"],[["名词","unlikeness",1]],[11,2.5,10,8,0],[["prep.","不像；与…不同",0],["prep.","（用于对比）与…不同",11],["prep.","非…的特征",0],["adj.","不同；不像；相异",0],["v.","（在社交网络、新闻网站、博客等上）对…取消点赞",0]],[["2026 英二 · 阅读 · Part A · Text 4","The fact is, unlike those large, city-produced music festivals, your neighborhood street festivals receive no city funding and rely on a combination of sponsorships, vendor fees and gate donations to cover their costs.","事实上，与那些由市政府主办的大型音乐节不同，你们街区的街头节庆没有市政府拨款，而要靠赞助费、摊位费和入口捐款共同支付开支。","正文"],["2020 英二 · 阅读 · Part B","But unlike in friendships, you need coworkers.","但与交朋友不同，你需要同事。","正文"],["2019 英二 · 阅读 · Part A · Text 3","The H-2A visa has no numerical cap, unlike the H-2B visa for nonagricultural work, which is limited to 66,000 a year.","H-2A签证没有数量上限，而用于非农业工作的H-2B签证每年限发6.6万份。","正文"],["2019 英二 · 阅读 · Part A · Text 1","Unlike so-called basic emotions such as sadness, fear, and anger, guilt emerges a little later, in conjunction with a child's growing grasp of social and moral norms.","与悲伤、恐惧和愤怒等所谓的基本情绪不同，内疚感出现得稍晚一些，与儿童对社会和道德规范日益深入的理解相伴而生。","正文"],["2015 英一 · 阅读 · Part A · Text 1","But unlike their absolutist counterparts in the Gulf and Asia, most royal families have survived because they allow voters to avoid the difficult search for a non-controversial but respected public figure.","但与海湾地区和亚洲实行专制的君主不同，欧洲大多数王室能够存续，是因为他们让选民免于艰难地寻找一位没有争议又受人尊敬的公众人物。","正文"],["2012 英一 · 阅读 · Part A · Text 3","But, unlike with mining claims, the community takes control of what happens next.","但与矿产权不同，接下来会发生什么由科学共同体掌控。","正文"]],"unlike.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"]],"d":[["unlikely","1. adj. 不太可能的；没希望的 2. adv. 未必"],["unlikeness","n. 不相等,不像"],["unlikelihood","n. 未必有,不可信"]]}],"unlikely":[["ʌnˈlaɪ.kli","ʌnˈlɑɪk·li"],["CET4","CET6","考研","TOEFL","IELTS"],[["比较级","unlikelier"],["最高级","unlikeliest"]],[14,3.0,10,10,0],[["adj.","不大可能发生的",13],["adj.","非心目中的；意料之外的",1],["adj.","难以相信的；不能信服的",0]],[["2024 英一 · 阅读 · Part A · Text 4","That seems unlikely.","这似乎不太可能。","正文"],["2024 英二 · 阅读 · Part A · Text 4","As to the prospects for federal legislation, commentators suggest that comprehensive federal privacy legislation seems unlikely in the short term.","至于联邦立法的前景，评论人士认为，短期内出台全面的联邦隐私法似乎不太可能。","正文"],["2022 英一 · 阅读 · Part A · Text 2","It is unlikely that Generation Z will be done with education at 18 or 21: they will need to be constantly upskilling throughout their career to stay employable.","Z世代不太可能在18岁或21岁时就结束学习：他们需要在整个职业生涯中不断提升技能，才能保持就业竞争力。","正文"],["2019 英二 · 阅读 · Part A · Text 3","The complaints are unlikely to stop without an overhaul of immigration rules for farm workers.","如果不全面改革针对农业工人的移民规定，这种抱怨恐怕不会停止。","正文"],["2014 英二 · 阅读 · Part A · Text 4","The housing sector needs to accept that we are very unlikely to ever return to the era of large-scale public grants.","住房行业需要接受这样一个现实：我们极不可能再回到大规模公共拨款的时代。","正文"],["2014 英二 · 阅读 · Part A · Text 4","While these measures would be welcome in the short term, we must face up to the fact that the existing £4.5bn programme of grants to fund new affordable housing, set to expire in 2015, is unlikely to be extended beyond then.","虽然短期内这些措施会受到欢迎，但我们必须面对这样一个事实：目前用于资助新建可负担住房的45亿英镑拨款计划将在2015年到期，而此后很可能不会延长。","正文"]],"unlikely.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["后缀","-ly 表形容词，通常缀于名词后。"]],"d":[]}],"unusual":[["ʌnˈjuː.ʒu.əl","ʌnˈju·ʒu·əl"],["高中","CET4","CET6","考研","IELTS"],[["副词","unusually",1],["名词","unusualness",1]],[6,2.0,6,4,1],[["adj.","特别的；不寻常的；罕见的",6],["adj.","独特的；与众不同的；别致的",0]],[["2019 英一 · 阅读 · Part A · Text 1","Financial regulators in Britain have imposed a rather unusual rule on the bosses of big banks.","英国金融监管机构对大型银行的高管施行了一项颇不寻常的规定。","正文"],["2011 英二 · 阅读 · Part A · Text 2","American papers have long been highly unusual in their reliance on ads.","美国报纸长期以来一直异乎寻常地依赖广告。","正文"],["2010 英一 · 阅读 · Part A · Text 2","The Federal Circuit issued an unusual order stating that the case would be heard by all 12 of the court’s judges, rather than a typical panel of three, and that one issue it wants to evaluate is whether it should “reconsider” its State Street Bank ruling.","联邦巡回上诉法院发布了一项不同寻常的命令，规定此案将由全院十二名法官审理，而非通常的三人合议庭；法院还表示，需评估的一个问题是是否应“重新考虑”其道富银行案裁决。","正文"],["2000 英一 · 阅读 · Part B","All this has the effect of building up unusual pressures and tensions within the community and consequently presents serious problems for the governments concerned.","所有这些变化产生的结果是，社会内部积聚起异常的压力和紧张情绪，进而给相关政府带来严重问题。","正文"],["2025 英一 · 阅读 · Part A · Text 4 · 第39题 · 选项A","The “ZIP disk” is cited as an example to show the hazard of retrieving files through unusual means.","文中举“ZIP 磁盘”的例子，是为了说明通过非常规手段提取文件的风险。","选项"],["2008 英一 · 完形","His argument is that the unusual history of these people has subjected them to unique evolutionary pressures that have resulted in this paradoxical state of affairs.","他的论点是，这一人群不同寻常的历史使他们承受了独特的进化压力，最终形成了这种看似矛盾的局面。",""]],"unusual.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","us-,ut- = use, 表示“用”。"],["后缀","-al,-ial 表形容词，“…的”，一般缀于名词后。"]],"d":[["unusually","adv. 不寻常地;非常"]]}],"unload":[["ʌnˈləʊd","ʌnˈloʊd"],["CET4","CET6","考研","TOEFL"],[["原形","unload"],["第三人称单数","unloads"],["现在分词","unloading"],["过去式","unloaded"],["过去分词","unloaded"],["名词","unloader",1]],[0,0.0,0,0,0],[["v.","（从车、船上）卸，取下",0],["v.","拆掉，退出，取出（子弹或胶卷等）",0],["v.","推卸（责任）；甩掉（包袱）",0],["v.","脱手，卖掉（尤指非法物品或次品）",0]],[],"unload.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","lead-,lod- 表示“走”，原始印欧语形式为 *leit-。"]],"d":[]}],"upper":[["ˈʌp.əʳ","ˈʌp·ər"],["高中","CET4","CET6","考研"],[["复数","uppers"]],[3,1.5,3,3,0],[["adj.","上边的，上面的，上层的（尤指同类或一对中的一个）",3],["adj.","上部的；靠上部的",0],["adj.","内陆的；高地的；向北部的",0],["n.","鞋帮；靴面",0],["n.","兴奋剂",0]],[["2017 英二 · 阅读 · Part A · Text 2","On the other hand, Tronick himself is concerned that the worries about kids’ use of screens are born out of an “oppressive ideology that demands that parents should always be interacting” with their children: “It’s based on a somewhat fantasised, very white, very upper-middle-class ideology that says if you’re failing to expose your child to 30,000 words you are neglecting them.”","另一方面，特罗尼克本人担心，人们对孩子使用屏幕的忧虑源于一种“要求父母始终与孩子互动的压迫性观念”。他说：“它建立在一种多少有些幻想色彩、极具白人及中上阶层色彩的观念之上：如果你没让孩子接触三万个词，就是忽视了他们。”","正文"],["2016 英二 · 阅读 · Part A · Text 4","“I still grew up in an upper middle-class home with parents who didn’t have college degrees,” Schneider said.","施奈德说：“我的父母都没有大学学位，但我还是在一个中上层家庭长大。”","正文"],["2000 英一 · 阅读 · Part A · Text 2","The grand mediocrity of today — everyone being the same in survival and number of offspring — means that natural selection has lost 80% of its power in upper-middle-class India compared to the tribes.","如今这种普遍的趋同——每个人的存活状况和子女数量都差不多——意味着，与部落群体相比，在印度中上层阶级中，自然选择的作用已减弱80%。","正文"]],"upper.mp3",{"r":[["词根","up- = up, over, 表示“向上”。"]],"d":[["uppercut","1. vt. 用上钩拳击 2. vi. 击上钩拳，用上钩拳击"],["uppercase","大写字母"],["uppermost","adj. 最高的;最上面的;最重要的 adv. 最重要地, 最突出地, 最主要地"],["upperworks","干舷"],["upper-class","adj. 上流社会的,中学(或高等学校)三年级的,四年级的"]]}],"upright":[["ˈʌp.raɪt","ˈʌpˌrɑɪt；ˈʌp·rɑɪt"],["CET4","CET6","考研","TOEFL","IELTS","GRE"],[["复数","uprights"],["副词","uprightly",1],["名词","uprightness",1]],[3,1.5,2,1,0],[["adj.","直立的；挺直的",2],["adj.","竖直的；直立的；垂直的",0],["adj.","正直的；诚实的；规矩的",0],["adv.","竖立着；垂直着",1],["n.","（支撑用的）直柱，立柱，立放构件",0],["n.","竖直的；直立的；垂直的",0]],[["2008 英一 · 阅读 · Part A · Text 3","Moreover, even though humans have been upright for millions of years, our feet and back continue to struggle with bipedal posture and cannot easily withstand repeated strain imposed by oversize limbs.","此外，尽管人类已经直立行走了数百万年，我们的双脚和背部仍在艰难适应双足行走姿态，难以轻松承受过长四肢带来的反复负担。","正文"],["2008 英一 · 阅读 · Part A · Text 3 · 第33题 · 选项B","On which of the following statements would the author most probably agree? Human height is conditioned by the upright posture.","作者最可能赞同以下哪种说法？人的身高受到直立姿势的制约。","选项"],["2005 英一 · 完形","Humans are often thought to be insensitive smellers compared with animals, but this is largely because, unlike animals, we stand upright.","与动物相比，人们常被认为嗅觉迟钝，但这主要是因为我们与动物不同，采用直立姿势。",""]],"upright.mp3",{"r":[["词根","up- = up, over, 表示“向上”。"],["词根","rect-,rig- = straight, right, 表示“正、直”。"]],"d":[]}],"upstairs":[["ʌpˈsteəz","ˈʌpˈsterz"],["中考","高中","CET4","CET6","考研"],[],[1,0.5,1,1,0],[["adv.","在（或向）楼上；在（或向）上一层",0],["n.","二楼；二楼以上各层；楼上",1]],[["2012 英二 · 阅读 · Part B","And it transformed public history too: downstairs became just as fascinating as upstairs.","这也改变了公众历史叙事：“楼下”的生活变得与“楼上”的生活一样引人入胜。","正文"]],"upstairs.mp3",{"r":[["词根","up- = up, over, 表示“向上”。"],["词根","stic-,stich- 表示“步，级；行”。"]],"d":[]}],"upward":[["ˈʌp.wəd","ˈʌp·wərd"],["高中","CET4","CET6","考研"],[["副词","upwardly",1],["名词","upwardness",1]],[2,1.0,2,2,0],[["adj.","向上的；朝上的；向高处的",0],["adj.","（数量、价格）上升的，上涨的，增长的",1],["adv.","向上地",0],["preposition","至少；超过",1]],[["2026 英二 · 阅读 · Part A · Text 4","Wicker Park Fest has long been one of Chicago’s most anticipated summer festivals, drawing upward of 70,000 attendees for a full weekend of live indie music, local art, small business vendors and, most importantly, community connection.","威克公园节长期以来一直是芝加哥最受期待的夏季节庆之一，整个周末的独立音乐现场演出、本地艺术、小商户摊位，以及最重要的社区联结，吸引了超过七万名参与者。","正文"],["2017 英二 · 阅读 · Part B","For factory owners, it all adds up to stiff competition for workers — and upward pressure on wages.","对工厂老板来说，这一切意味着争夺工人的竞争激烈，也给工资带来了上涨压力。","正文"]],"upward.mp3",{"r":[["词根","up- = up, over, 表示“向上”。"],["后缀","-ward 表形容词或副词，“向…”。"]],"d":[["upwards","adv. 向上；在上部；向上游"]]}],"usage":[["ˈjuː.sɪdʒ","ˈju·sɪdʒ"],["CET4","CET6","考研","IELTS"],[["复数","usages"]],[2,1.0,2,2,0],[["n.","（词语的）用法，惯用法",0],["n.","使用；利用；利用率",2]],[["2026 英二 · 阅读 · Part A · Text 2","With AI’s potential to simplify our professional lives, do the admin and enhance the work experience, it’s up to us to navigate its usage cautiously so it supports us without compromising our privacy.","人工智能有望简化我们的工作生活、处理行政事务并改善工作体验；如何谨慎使用它，以便得到帮助又不损害隐私，取决于我们自己。","正文"],["2017 英一 · 阅读 · Part C","Complex international, economic, technological and cultural changes could start to diminish the leading position of English as the language of the world market, and UK interests which enjoy advantage from the breadth of English usage would consequently face new pressures.","国际、经济、技术和文化领域的复杂变化可能开始削弱英语作为世界市场通用语言的领先地位，因此，因英语广泛使用而受益的英国利益方将面临新的压力。","正文"]],"usage.mp3",{"r":[["词根","us-,ut- = use, 表示“用”。"],["后缀","-age 表示“状态，总称”。"]],"d":[["ill-usage","n. 虐待,苛刻"]]}],"useful":[["ˈjuːs.fᵊl","ˈjus·fəl"],["中考","高中","CET4","CET6","考研","IELTS"],[["副词","usefully",1],["名词","use",1],["形容词","useless",1],["副词","uselessly",1],["名词","uselessness",1]],[14,3.0,13,8,0],[["adj.","有用的；有益的；实用的；有帮助的",14],["adj.","好的；合格的",0]],[["2025 英二 · 阅读 · Part A · Text 3","“A useful map can be created by looking at even a few key parameters.”","“即便只考察几个关键参数，也能制作出有用的地图。”","正文"],["2025 英二 · 阅读 · Part B","But other times, it’s useful to build a coalition among your co-workers or other stakeholders.","但另一些时候，在同事或其他利益相关者中建立支持联盟也很有用。","正文"],["2019 英一 · 阅读 · Part A · Text 3","Only then will they be useful servants and not Frankenstein’s out-of-control monster.","只有这样，它们才会成为有用的仆人，而不会变成弗兰肯斯坦笔下失控的怪物。","正文"],["2016 英二 · 阅读 · Part A · Text 3","Try to slot it in as a to-do list item and you’ll manage only goal-focused reading — useful, sometimes, but not the most fulfilling kind.","试着把它列为待办事项，你最终只能做有明确目标的阅读——这种阅读有时固然有用，却不是最令人满足的一种。","正文"],["2015 英二 · 阅读 · Part B","Fear is both useful and harmful.","恐惧既有益也有害。","正文"],["2015 英一 · 阅读 · Part B","Ideally, different kinds of reading inform each other, and act as useful reference points for and counterbalances to one another.","理想情况下，不同的阅读方式会相互启发，成为彼此有用的参照和制衡。","正文"]],"useful.mp3",{"r":[["词根","us-,ut- = use, 表示“用”。"],["后缀","-ful 表形容词，“有…的”，和单词full同源。"]],"d":[["usefulness","n. 有用,有益,有效"],["useful-life","n. 有效期限"]]}],"utmost":[["ˈʌt.məʊst","ˈʌtˌmoʊst；ˈʌt·moʊst"],["CET4","CET6","考研","IELTS"],[["复数","utmosts"]],[2,1.0,2,2,0],[["adj.","最大的；极度的",0],["n.","最大量；最大限度；极限；最大可能",2]],[["2023 英一 · 阅读 · Part A · Text 3","We are not boycotting PRH titles but we are doing our utmost to ensure that availability for customers remains good despite the lower overall levels of stock.”","我们没有抵制企鹅兰登书屋的书；尽管总体库存减少，我们仍在竭尽全力保证顾客能买到想要的书。”","正文"],["2019 英一 · 阅读 · Part A · Text 2","The use of this little-known practice has accelerated in recent years, as colleges continue to do their utmost to keep students in school (and paying tuition) and improve their graduation rates.","近年来，随着大学继续竭力让学生留在学校（并继续缴纳学费）和提高毕业率，这种鲜为人知的做法越来越普遍。","正文"]],"utmost.mp3",null],"unfold":[["ʌnˈfəʊld","ʌnˈfoʊld"],["高中","CET6","考研","TOEFL","IELTS","GRE"],[["原形","unfold"],["第三人称单数","unfolds"],["现在分词","unfolding"],["过去式","unfolded"],["过去分词","unfolded"],["名词","unfoldment",1]],[4,1.5,4,4,0],[["v.","（使）展开；打开",0],["v.","（使）逐渐展现；展示；透露",4]],[["2026 英一 · 阅读 · Part C","As the war unfolded, science rapidly assumed a central role.","随着战争推进，科学迅速占据了核心地位。","正文"],["2015 英一 · 阅读 · Part A · Text 4","This long story still unfolds.","这起旷日持久的事件仍在继续发展。","正文"],["2012 英一 · 阅读 · Part C","A few generative rules are then sufficient to unfold the entire fundamental structure of a language, which is why children can learn it so quickly.","这样，只需少数几条生成规则就足以展开一门语言的全部基本结构，这也解释了儿童为何能如此迅速地习得语言。","正文"],["2009 英一 · 阅读 · Part A · Text 4","According to many books and articles, New England’s leaders established the basic themes and preoccupations of an unfolding, dominant Puritan tradition in American intellectual life.","许多书籍和文章认为，新英格兰的领袖奠定了美国思想生活中逐渐展开并占据主导地位的清教徒传统的基本主题和核心关切。","正文"]],"unfold.mp3",{"r":[["前缀","un- 表示“打开，解开，弄出”。"]],"d":[]}],"unfortunately":[["ʌnˈfɔː.tʃᵊn.ət.li","ʌnˈfɔr·tʃə·nət.li"],["高中","CET4","CET6","考研","TOEFL"],[],[10,2.5,8,10,0],[["adv.","不幸地；遗憾地；可惜地；可悲地",10]],[["2022 英一 · 阅读 · Part A · Text 1","Unfortunately, the polyurethane foam he used is inherently unstable.","遗憾的是，他使用的聚氨酯泡沫塑料本身就不稳定。","正文"],["2022 英二 · 阅读 · Part A · Text 2","Unfortunately, many people who are opting to work in retirement are preparing to do so because they are worried about making ends meet in their later years, said Brent Weiss, a co-founder at Baltimore-based financial-planning firm Facet Wealth.","巴尔的摩理财公司Facet Wealth的联合创始人布伦特·韦斯说，遗憾的是，许多人选择退休后继续工作，并为此做准备，是因为担心晚年入不敷出。","正文"],["2019 英一 · 阅读 · Part C","Unfortunately, the long-term costs of using simple quantitative metrics to assess researcher merit are likely to be quite great.","遗憾的是，用简单的量化指标评价研究人员的能力，长期代价很可能相当高。","正文"],["2015 英二 · 阅读 · Part B","Unfortunately, life is not a bed of roses.","遗憾的是，生活并非总是美好的。","正文"],["2015 英二 · 阅读 · Part B","Unfortunately, people create inner barriers with a help of exaggerating fears.","遗憾的是，人们夸大恐惧，从而在内心筑起屏障。","正文"],["2014 英一 · 阅读 · Part A · Text 4","Unfortunately, despite 2½ years in the making, “The Heart of the Matter” never gets to the heart of the matter: the illiberal nature of liberal education at our leading colleges and universities.","遗憾的是，《问题的核心》虽历经两年半才完成，却从未触及真正的问题核心：我们顶尖高校的通识教育并不崇尚自由。","正文"]],"unfortunately.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","fort- = luck, 表示“运气”。"],["后缀","-ate 表形容词，“具有…的”。"],["后缀","-ly 表副词，通常缀于形容词后。"]],"d":[]}],"uniform":[["ˈjuː.nɪ.fɔːm","ˈju·nəˌfɔrm"],["高中","CET4","CET6","考研","TOEFL","IELTS","GRE"],[["复数","uniforms"],["原形","uniform"],["第三人称单数","uniforms"],["现在分词","uniforming"],["过去式","uniformed"],["过去分词","uniformed"],["副词","uniformly",1],["名词","uniformness",1],["形容词","uniformless",1],["形容词","uniformal",1],["形容词","ununiform",1],["副词","ununiformly",1]],[8,2.5,4,6,2],[["n.","制服；校服",5],["n.","（运动队）队服",1],["n.","清一色服装；统一服装",1],["adj.","一致的；统一的；一律的",1]],[["2016 英一 · 阅读 · Part B","Pick a standard work uniform or a few go-to options.","选定一套固定的工作装，或几种随手可用的搭配。","正文"],["2015 英一 · 阅读 · Part A · Text 1","Does that mean the writing is on the wall for all European royals, with their magnificent uniforms and majestic lifestyles?","这是否意味着，身着华丽制服、过着威严生活的欧洲王室都已大势将去？","正文"],["2013 英一 · 阅读 · Part A · Text 4","The Constitutional principles that Washington alone has the power to “establish a uniform Rule of Naturalization” and that federal laws precede state laws are noncontroversial.","以下宪法原则并无争议：只有联邦政府有权“制定统一的归化条例”，而且联邦法律优先于州法律。","正文"],["2008 英一 · 阅读 · Part A · Text 3","She says that, unlike those for basketball, the length of military uniforms has not changed for some time.","她说，军服与篮球队服不同，其长度已有一段时间没有改变。","正文"],["2008 英一 · 阅读 · Part A · Text 3","Claire C. Gordon, senior anthropologist at the Army Research Center in Natick, Mass., ensures that 90 percent of the uniforms and workstations fit recruits without alteration.","马萨诸塞州纳蒂克陆军研究中心的资深人类学家克莱尔·C.戈登负责确保90%的军服和工作台无需改动就能适合新兵使用。","正文"],["2008 英一 · 阅读 · Part A · Text 3","The bodies playing major professional sports have changed dramatically over the years, and managers have been more than willing to adjust team uniforms to fit the growing numbers of bigger, longer frames.","多年来，参加主要职业体育赛事的运动员体型发生了显著变化，球队管理者也十分乐意调整队服尺寸，以适应越来越多体型更大、更高的球员。","正文"]],"uniform.mp3",{"r":[["前缀","un,uni = one, 表示“单一、一个”。"],["词根","form- = shape, 表示“形状”，来自拉丁语 formare \"to shape, give form to\" 及 forma \"form\"。"]],"d":[["uniformly","均匀"],["uniformitarian","均变"],["uniformed","制服"],["nonuniform","不均匀"],["uniformity","n. 一致;单调;无差异;无变化"]]}],"unit":[["ˈjuː.nɪt","ˈju·nɪt"],["中考","高中","CET4","CET6","考研"],[["复数","units"]],[2,1.0,2,2,0],[["n.","单独的事物（或人、群体）；单位；单元",1],["n.","一件（商品）；单位",0],["n.","单元；课",0],["n.","班组；小队",0],["n.","科；病区",0],["n.","配套家具组件；（尤指）成套家具中的柜子",0],["n.","单位；单元",0],["n.","装置；机件；部件；元件",0],["n.","（一）套；单元",1],["n.","个位数",0]],[["2011 英二 · 阅读 · Part A · Text 3","The apartments in the elegant towers Mies built on Chicago’s Lake Shore Drive, for example, were smaller — two-bedroom units under 1,000 square feet — than those in their older neighbors along the city’s Gold Coast.","例如，密斯在芝加哥湖滨大道建造的雅致高层住宅中，公寓面积比该市黄金海岸沿线较老建筑里的公寓更小：两居室不足1000平方英尺。","正文"],["2001 英一 · 阅读 · Part A · Text 1","By splitting up the subject matter into smaller units, one man could continue to handle the information and use it as the basis for further research.","把研究对象划分成较小的单元后，一个人便仍能掌握有关信息，并以此为基础开展进一步研究。","正文"]],"unit.mp3",{"r":[["前缀","un,uni = one, 表示“单一、一个”。"]],"d":[["unitor","n. “或门”；联接器"],["subunit","n. 亚组；副族"],["unitize","vt. 使成为一单位；使成一整体；单元化"],["run-unit","n. 运行单位"]]}],"unite":[["juːˈnaɪt","jʊˈnɑɪt"],["高中","CET4","CET6","考研"],[["复数","unites"],["原形","unite"],["第三人称单数","unites"],["现在分词","uniting"],["过去式","united"],["过去分词","united"],["名词","uniter",1]],[52,4.5,27,44,0],[["v.","（为某事）联合，联手，团结",3],["v.","（与某人或集体）联结，联合；统一",49]],[["2026 英一 · 阅读 · Part C","In the United States, the desire to provide the public with a general, nontechnical education in science originated as far back as the late 1800s.","在美国，早在19世纪末，人们就有了向公众提供通识性、非技术性科学教育的愿望。","正文"],["2026 英一 · 阅读 · Part A · Text 2","Other regions in the United States, Canada and Europe have steadily increased incentives to attract TV shows and movies, leaving California in the dust.","美国其他地区以及加拿大和欧洲不断加大优惠力度，吸引电视剧和电影制作，让加利福尼亚州远远落后。","正文"],["2026 英一 · 阅读 · Part C","(50) The intense focus on scientific literacy in the United States originally grew out of the critical role of science and technology during World War II, as well as the perceived deficiencies of American soldiers.","（50）美国最初对科学素养的高度重视，源于第二次世界大战期间科学技术所起的关键作用，以及人们认为美国士兵存在的不足。","正文"],["2024 英一 · 阅读 · Part B","They serve no purpose in a museum in the United States or elsewhere except as curious objects.","在美国或其他地方的博物馆里，它们除了供人猎奇，便没有别的用途。","正文"],["2024 英一 · 阅读 · Part A · Text 4","And it carries “significant repercussions for water quality and flood control throughout the United States,” as Justice Brett Kavanaugh observed.","而且，正如布雷特·卡瓦诺大法官所指出的，这对全美的水质和防洪将产生“重大影响”。","正文"],["2024 英二 · 阅读 · Part A · Text 1","New AI technologies are particularly concentrated: Brookings’s Mark Muro and Sifan Liu estimate that just 15 cities account for two-thirds of the AI assets and capabilities in the United States.","新的人工智能技术分布尤为集中：布鲁金斯学会的马克·穆罗和刘思凡估计，仅15座城市就占据了美国三分之二的人工智能资产和能力。","正文"]],"unite.mp3",{"r":[["前缀","un,uni = one, 表示“单一、一个”。"],["后缀","-ite 形容词、名词、动词后缀，表示“属于或和...相关”，来自拉丁语和希腊语。"]],"d":[["united","adj. 团结的，和睦的；一致的，统一的"],["reunite","1. vt. 使再结合；使再联合；使重聚 2. vi. 再结合；再联合；重聚"],["uniting","1. n. 合并 2. v. 使联合；使团结；使结婚（unite的现在分词）"],["unitive","adj. 统一的；团结的；联合的"],["disunite","1. vt. 不和；使分离 2. vi. 分散；分离；变得分离"]]}],"unity":[["ˈjuː.nə.ti","ˈju·nɪ·t̬i"],["CET4","CET6","考研","TOEFL"],[["复数","unities"]],[4,1.5,2,4,0],[["n.","团结一致；联合；统一",4],["n.","完整；完美；和谐；协调",0],["n.","（情节、时间和地点的）统一性，一致性；三一律",0],["n.","统一体；联合体；整体",0],["n.","（数目或数字）一",0]],[["2015 英一 · 阅读 · Part A · Text 1","Symbolic of national unity as they claim to be, their very history — and sometimes the way they behave today — embodies outdated and indefensible privileges and inequalities.","尽管他们自称象征民族团结，但他们的历史本身，有时还有当下的行为，却体现着过时且站不住脚的特权与不平等。","正文"],["2015 英一 · 阅读 · Part A · Text 1","When public opinion is particularly polarised, as it was following the end of the Franco regime, monarchs can rise above “mere” politics and “embody” a spirit of national unity.","当公众意见严重两极分化时，比如佛朗哥政权终结后那样，君主可以超越“单纯”的政治，成为民族团结精神的“化身”。","正文"],["2005 英一 · 阅读 · Part C","A unity of objectives that nonetheless respect the varied peculiarities of each country.","目标上的团结，同时尊重各国不同的独特之处。","正文"],["2005 英一 · 阅读 · Part C","(50) In dealing with a challenge on such a scale, it is no exaggeration to say, “United we stand, divided we fall” — and if I had to choose a slogan it would be “Unity in our diversity.”","（50）面对如此规模的挑战，说“团结则存，分裂则亡”并不夸张；如果要我选一句口号，那就是“在多样性中团结”。","正文"]],"unity.mp3",{"r":[["前缀","un,uni = one, 表示“单一、一个”。"],["后缀","-ity 表名词，指具备某种性质。"]],"d":[["disunity","n. 不统一，不团结"],["triunity","n. 三位一体"]]}],"undo":[["ʌnˈduː","ʌnˈdu"],["高中","CET4","CET6","考研","TOEFL","IELTS"],[["原形","undo"],["第三人称单数","undoes"],["现在分词","undoing"],["过去式","undid"],["过去分词","undone"],["名词","undoer",1]],[1,0.5,1,0,0],[["v.","打开；解开；拆开",0],["v.","消除，取消，废止（某事的影响）",1],["v.","打败；挫败",0]],[["2013 英一 · 完形","This might sound small, but to undo the effects of such a decrease a candidate would need 30 more GMAT points than would otherwise have been necessary.","这个降幅听起来或许很小，但要抵消其影响，考生的 GMAT 成绩得比原本所需高出 30 分。",""]],"undo.mp3",{"r":[["前缀","un- 表示“打开，解开，弄出”。"]],"d":[]}],"undoubtedly":[["ʌnˈdaʊ.tɪd.li","ʌnˈdɑʊ·t̬ɪd·li"],["CET4","CET6","考研","TOEFL","IELTS"],[["副词","undoubtedly",1]],[4,1.5,4,2,0],[["adv.","无疑的；确实的；千真万确的",4]],[["2015 英一 · 阅读 · Part A · Text 1","Even so, kings and queens undoubtedly have a downside.","即便如此，国王和王后无疑也有不利的一面。","正文"],["2009 英一 · 阅读 · Part A · Text 3","Progress in both areas is undoubtedly necessary for the social, political, and intellectual development of these and all other societies; however, the conventional view that education should be one of the very highest priorities for promoting rapid economic development in poor countries is wrong.","这两个方面取得进展，无疑都是这些社会乃至所有社会在社会、政治和智识层面发展所必需的；然而，认为教育应成为促进贫穷国家经济快速发展最优先事项之一的传统观点是错误的。","正文"],["2026 英一 · 阅读 · Part B · 选项D","D) It is undoubtedly true that all work and no play really does make Jack, or Jill, dull.","D）毫无疑问，只工作不玩耍确实会让杰克或吉尔变得乏味。",""],["2020 英二 · 完形","But defining what it means to be a good parent is undoubtedly very tricky, particularly since children respond differently to the same style of parenting.","但要界定怎样才算好家长无疑很棘手，尤其是因为孩子对同一种养育方式的反应各不相同。",""]],"undoubtedly.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","dubit- = to doubt, 表示“怀疑”。"],["后缀","-ed 形容词后缀，加在名词后表示“如...的”；加在动词后表示“被...的”。"],["后缀","-ly 表副词，通常缀于形容词后。"]],"d":[]}],"ugly":[["ˈʌɡ.li","ˈʌɡ·li"],["中考","高中","CET4","CET6","考研","IELTS","GRE"],[["比较级","uglier"],["最高级","ugliest"],["副词","uglily",1],["名词","ugliness",1]],[0,0.0,0,0,0],[["adj.","丑陋的；难看的",0],["adj.","令人不快的；危险的；险恶的；凶险的",0]],[],"ugly.mp3",null],"ultraviolet":[["ˌʌl.trəˈvaɪə.lət","ˌʌl·trəˈvɑɪ·ə·lɪt"],["CET6","考研","TOEFL","IELTS"],[["复数","ultraviolets"]],[0,0.0,0,0,0],[["adj.","紫外线的；利用紫外线的",0]],[],"ultraviolet.mp3",{"r":[["前缀","ultra- 表示“极端（extremely），过度（beyond）”，来自拉丁语。"],["词根","viol- = violet, 表示“紫色”，和词根 iod- 碘，同源。"]],"d":[]}],"umbrella":[["ʌmˈbrel.ə","ʌmˈbrel·ə"],["中考","高中"],[["复数","umbrellas"],["原形","umbrella"],["第三人称单数","umbrellas"],["现在分词","umbrellaing"],["过去式","umbrellaed"],["过去分词","umbrellaed"]],[0,0.0,0,0,0],[["n.","伞；雨伞；阳伞",0],["n.","综合体；总体；整体",0],["n.","保护国（或体系）；保护伞；庇护",0]],[],"umbrella.mp3",{"r":[["词根","umbr- = shadow, 表示“影子”，来自于拉丁语。"]],"d":[["subumbrella","n. 下伞,内伞"]]}],"unanimous":[["juːˈnæn.ɪ.məs","jʊˈnæn·ə·məs"],["CET6","考研","TOEFL","IELTS","GRE"],[["副词","unanimously",1]],[1,0.5,1,1,0],[["adj.","（决定或意见）一致的，一致同意的",1],["adj.","（团体）意见一致的，一致同意某事的",0]],[["2017 英一 · 阅读 · Part A · Text 4","In a rare unanimous ruling, the US Supreme Court has overturned the corruption conviction of a former Virginia governor, Robert McDonnell.","美国最高法院罕见地一致裁决，推翻了弗吉尼亚州前州长罗伯特·麦克唐纳的贪腐定罪。","正文"]],"unanimous.mp3",{"r":[["前缀","un,uni = one, 表示“单一、一个”。"],["词根","anim- = life, spirit, 表示“生命，精神”等。古代人认为生命的本质是因为灵魂的存在。在拉丁文中，灵魂分为阴性和阳性两个单词，既阴性的 anima（阿尼玛）和阳性的 animus（阿尼姆斯）。表示生命的词根 anim- 就来自这两个拉丁文。由于生命和灵魂密不可分，所以词根 anim- 既有“生命”、“动”的含义，也有“精神”、“心”的含义。"],["后缀","-ous,-itious,-eous,-ious,-uous 表形容词，表示“…的”，用于化学领域表示“亚酸的，低价（金属）的”。"]],"d":[["unanimously","一致"]]}],"uncover":[["ʌnˈkʌv.əʳ","ʌnˈkʌv·ər"],["CET4","CET6","考研","TOEFL"],[["原形","uncover"],["第三人称单数","uncovers"],["现在分词","uncovering"],["过去式","uncovered"],["过去分词","uncovered"]],[2,1.0,2,1,1],[["v.","揭开盖子",0],["v.","发现；揭露；揭发",2]],[["2026 英一 · 阅读 · Part A · Text 4","In the study, the researchers compared the historical fire cadence with the wildfires recorded over the past few decades, and uncovered a striking shortfall.","在这项研究中，研究人员将历史上的火灾发生频率与过去几十年记录的野火作比较，发现两者之间存在显著的缺口。","正文"],["2017 英一 · 阅读 · Part A · Text 2 · 第29题 · 选项C","It can be inferred from Paragraph 5 that progress in today’s astronomy may uncover the origin of Hawaiian culture.","从第五段可以推断，当今天文学的进步可能揭示夏威夷文化的起源。","选项"]],"uncover.mp3",{"r":[["前缀","un- 表示“打开，解开，弄出”。"],["词根","cover- = cover, 表示“盖子”，复合词根：co-共同 + ver- ( = wer- ) 保护。"]],"d":[["uncovered","adj. 无盖的,未保险的"]]}],"undergraduate":[["ˌʌn.dəˈɡrædʒ.u.ət","ˌʌn·dərˈɡrædʒ·u·ət"],["CET4","CET6","考研","TOEFL","IELTS"],[["复数","undergraduates"]],[16,3.0,8,11,3],[["n.","本科生",12],["adjective","本科生的；供本科生的；由本科生组成的；本科生特有的",2],["adjective","本科",2]],[["2024 英二 · 阅读 · Part B","Experts say demonstrating talent in at least one extracurricular activity can help in the college admissions process, especially at top-tier undergraduate institutions.","专家表示，至少在一项课外活动中展现才能，有助于大学录取，尤其有助于申请一流本科院校。","正文"],["2024 英二 · 阅读 · Part B","High school students eager to stand out in the college application process often participate in a litany of extracurricular activities hoping to bolster their chances of admission to a selective undergraduate institution.","渴望在大学申请中脱颖而出的高中生，常常参加一长串课外活动，希望借此提高进入录取标准严格的本科院校的机会。","正文"],["2022 英一 · 阅读 · Part A · Text 2","As the latest crop of students pen their undergraduate application form and weigh up their options, it may be worth considering just how the point, purpose and value of a degree has changed and what Generation Z need to consider as they start the third stage of their educational journey.","当最新一批学生填写本科申请表、权衡各种选择时，或许值得想一想：学位的意义、目的和价值已经发生怎样的变化，以及Z世代在开启教育旅程的第三阶段时需要考虑什么。","正文"],["2019 英一 · 阅读 · Part A · Text 2","But now most colleges, save for many selective campuses, allow all undergraduates, and even graduate students, to get their low grades forgiven.","但现在，除了许多录取门槛高的学校，多数大学都允许所有本科生甚至研究生抹去低分记录。","正文"],["2018 英二 · 阅读 · Part A · Text 4","Tim Harford, author of Messy: The Power of Disorder to Transform Our Lives, points to a study in the early 1980s that divided undergraduates into two groups: some were advised to set out monthly goals and study activities; others were told to plan activities and goals in much more detail, day by day.","《混乱：无序改变生活的力量》的作者蒂姆·哈福德提到 20 世纪 80 年代初的一项研究：研究者将本科生分成两组，一组得到的建议是制定月度目标和学习活动计划，另一组则被要求按天更细致地规划活动和目标。","正文"],["2015 英二 · 阅读 · Part A · Text 2","Most of the first-generation students (59.1 percent) were recipients of Pell Grants, a federal grant for undergraduates with financial need, while this was true only for 8.6 percent of the students with at least one parent with a four-year degree.","第一代大学生中，大多数人（59.1%）获得了佩尔助学金——一种面向有经济需要的本科生的联邦补助；而父母至少一人拥有四年制大学学位的学生中，只有8.6%获得了这种补助。","正文"]],"undergraduate.mp3",{"r":[["前缀","under- = beneath, below, underneath, 表示“在…下”，源自古英语。和源自拉丁语的前缀 infra- 同源。"],["词根","grad- = step, grade, 表示“步，级”，源自拉丁语 gradus \"step\"。"],["后缀","-ate 表名词，“人或地位”。"]],"d":[]}],"underground":[["ˌʌn.dəˈɡraʊnd；ˈʌn.də.ɡraʊnd","ˌʌn·dərˈɡrɑʊnd；ˈʌn·dərˌɡrɑʊnd"],["中考","高中","TOEFL","IELTS"],[["复数","undergrounds"]],[4,1.5,4,4,0],[["adj.","地下的；地面以下的",2],["adj.","秘密的，非法的，暗中的，地下的（尤指反政府的）",0],["adv.","地下的；地面以下的",0],["adv.","隐蔽地；隐匿地",2],["n.","（城市的）地下铁路系统，地铁",0],["n.","秘密政治组织；（反政府）地下组织",0],["n.","反政府地下组织成员",0]],[["2026 英二 · 阅读 · Part A · Text 3","One of the most important changes the upgrades will bring is the segregation of the high-speed line from the regular one in certain urban centres through the construction of underground rail links.","这些升级工程带来的最重要变化之一，是通过修建地下铁路联络线，在部分城市中心将高铁线路与普通线路分开。","正文"],["2019 英二 · 阅读 · Part A · Text 3","The shortage is compounded by federal immigration raids, which remove some workers and drive others underground.","联邦政府的移民突袭执法进一步加剧了短缺：一些工人被带走，另一些则被迫转入地下。","正文"],["2012 英一 · 阅读 · Part A · Text 2","A string of accidents, including the partial collapse of a cooling tower in 2007 and the discovery of an underground pipe system leakage, raised serious questions about both Vermont Yankee’s safety and Entergy’s management — especially after the company made misleading statements about the pipe.","一连串事故，包括2007年一座冷却塔部分坍塌，以及一套地下管道系统被发现泄漏，引发了对佛蒙特扬基核电站安全性和安特吉管理能力的严重质疑，尤其是在该公司对管道作出误导性陈述之后。","正文"],["2000 英一 · 阅读 · Part A · Text 5","Consequences follow from this, of course, some of which are that ambition is driven underground, or made sly.","当然，这会产生一些后果，其中之一就是雄心被迫转入地下，或变得鬼祟。","正文"]],"underground.mp3",{"r":[["前缀","under- = beneath, below, underneath, 表示“在…下”，源自古英语。和源自拉丁语的前缀 infra- 同源。"]],"d":[["undergrounder","在地面下工作的人"]]}],"undermine":[["ˌʌn.dəˈmaɪn","ˌʌn·dərˈmɑɪn"],["CET6","考研","TOEFL","IELTS","GRE"],[["原形","undermine"],["第三人称单数","undermines"],["现在分词","undermining"],["过去式","undermined"],["过去分词","undermined"]],[11,2.5,8,4,3],[["v.","逐渐削弱（信心、权威等）；使逐步减少效力",11],["v.","从根基处破坏；挖…的墙脚",0]],[["2022 英一 · 阅读 · Part B","She uses outdated research and decades-old examples to undermine the noble mission of organizations committed to connecting children to a world beyond their own.","她借助过时的研究和几十年前的事例，贬损那些致力于帮助儿童认识自身世界之外的天地的机构所肩负的崇高使命。","正文"],["2021 英一 · 阅读 · Part A · Text 4","In the meantime, the court threw out the FCC’s attempt to block all state rules on net neutrality, while preserving the commission’s power to preempt individual state laws that undermine its order.","与此同时，法院驳回了 FCC 阻止所有州级网络中立性规则的企图，但保留了委员会排除那些破坏其命令的个别州法适用的权力。","正文"],["2017 英一 · 阅读 · Part A · Text 1","But demanding too much of air travelers or providing too little security in return undermines public support for the process.","但如果对航空旅客要求过多，或者付出这些代价却得不到相应的安全保障，就会削弱公众对安检程序的支持。","正文"],["2017 英一 · 阅读 · Part A · Text 4","If connections can be bought, a basic premise of democratic society — that all are equal in treatment by government — is undermined.","如果人脉关系可以买到，民主社会的一个基本前提——政府平等对待所有人——便会受到损害。","正文"],["2026 英二 · 完形","But the thing is, whether your self-worth really is being undermined is, to a large degree, subjective.","但问题在于，自我价值感是否真的受到损害，在很大程度上取决于主观判断。",""],["2026 英二 · 完形","Any comments or experiences that undermine those feelings of self-worth can be uncomfortable and it’s only natural to want to avoid them.","任何损害这些自我价值感的言论或经历，都可能令人不适；想要避开它们也是人之常情。",""]],"undermine.mp3",{"r":[["前缀","under- = beneath, below, underneath, 表示“在…下”，源自古英语。和源自拉丁语的前缀 infra- 同源。"]],"d":[["underminer","潜挖坑道者;暗中破坏者"]]}],"underneath":[["ˌʌn.dəˈniːθ","ˌʌn·dərˈniθ"],["CET4","CET6","考研","TOEFL","IELTS"],[],[0,0.0,0,0,0],[["preposition, adverb","在…底下；隐藏（或掩盖）在下面",0],["preposition, adverb","（指真实的感情或性格）在…表象之下",0],["n.","（物体的）下表面，底面，底部，下部",0]],[],"underneath.mp3",{"r":[["前缀","under- = beneath, below, underneath, 表示“在…下”，源自古英语。和源自拉丁语的前缀 infra- 同源。"],["词根","neth- = below, 表示“下面”"]],"d":[]}],"until":[["ənˈtɪl","ənˌtɪl"],["中考","高中"],[],[34,4.0,19,30,0],[["conjunction, preposition","到…时；直到…为止",34]],[["2026 英一 · 阅读 · Part C","(49) It wasn’t until the phrase “scientific literacy” came along in the 1940s that science had the formidable slogan it needed to command public attention and make improving science education an important national goal.","（49）直到20世纪40年代“科学素养”一词出现，科学才有了它所需要的有力口号，可以借此吸引公众关注，并使改进科学教育成为重要的国家目标。","正文"],["2024 英一 · 阅读 · Part C","Elephants are very choosy eaters, but until recently little was known about how they selected their food.","大象对食物十分挑剔，但直到最近，人们还不太清楚它们如何选择食物。","正文"],["2024 英一 · 阅读 · Part A · Text 1","Solar panels had few niche uses until they became cheap; now they are transforming the global energy system.","太阳能电池板在变得便宜之前只有少数专门用途；如今，它们正改变全球能源体系。","正文"],["2022 英一 · 阅读 · Part A · Text 1","Certain artifacts are especially vulnerable because some pioneers in plastic art didn’t always know how to mix ingredients properly, says Thea van Oosten, a polymer chemist who, until retiring a few years ago, worked for decades at the Cultural Heritage Agency of the Netherlands.","聚合物化学家泰娅·范·奥斯滕说，某些艺术品格外脆弱，是因为一些塑料艺术的先驱并非总能正确调配原料。她在几年前退休前，曾在荷兰文化遗产局工作数十年。","正文"],["2021 英二 · 阅读 · Part A · Text 3","Although only a research project at this stage, the request has raised the prospect of regulators wading into early-stage tech markets that until now have been beyond their reach.","虽然现阶段这只是一项研究，但这一要求使人们看到一种可能：监管机构会介入此前未曾触及的早期科技市场。","正文"],["2020 英一 · 阅读 · Part A · Text 2","Until this century, university libraries were not very price sensitive.","直到本世纪，大学图书馆对价格都不太敏感。","正文"]],"until.mp3",null],"upon":[["əˈpɒn","əˈpɑn；əˈpɔn"],["中考","高中","CET4","CET6","考研"],[],[13,3.0,10,9,0],[["prep.","（强调数目或数量大）",0],["prep.","在…上",12],["prep.","（表示需要或缘由）靠，指望，凭",1]],[["2015 英一 · 阅读 · Part C","(48) But the force of geographic conditions peculiar to America, the interplay of the varied national groups upon one another, and the sheer difficulty of maintaining old-world ways in a raw, new continent caused significant changes.","（48）然而，美洲特有的地理条件所起的作用、不同民族群体之间的相互影响，以及在一块原始的新大陆维持旧大陆生活方式的巨大困难，促成了显著的变化。","正文"],["2013 英二 · 阅读 · Part A · Text 4","After all, four decades of evidence has now shown that corporations in Europe as well as the US are evading the meritocratic hiring and promotion of women to top positions — no matter how much “soft pressure” is put upon them.","毕竟，四十年来的证据表明，欧洲和美国的企业一直回避按能力公平地招聘和提拔女性进入高层职位，不管对它们施加多少“软性压力”都一样。","正文"],["2009 英一 · 阅读 · Part C","(48) While it is easy to ignore in our contact with them the effect of our acts upon their disposition, it is not so easy as in dealing with adults.","（48）我们与年轻人接触时，或许容易忽视自己的行为对他们性情的影响，但要像对待成年人时那样忽视这种影响，却并不那么容易。","正文"],["2009 英一 · 阅读 · Part C","These groups mainly rely for instilling needed dispositions into the young upon the same sort of association which keeps the adults loyal to their group.","这些群体主要依靠与让成年人忠于群体的方式相同的交往方式，把所需的品性灌输给年轻人。","正文"],["2008 英一 · 阅读 · Part A · Text 2","The value of knowledge and the return on the public investment in research depends, in part, upon wide distribution and ready access.","知识的价值，以及公共研究投资的回报，部分取决于知识能否广泛传播和方便获取。","正文"],["2003 英一 · 阅读 · Part B","All the social sciences focus upon the study of humanity.","所有社会科学都以研究人类为中心。","正文"]],"upon.mp3",{"r":[["词根","up- = up, over, 表示“向上”。"]],"d":[["hereupon","adv. 于此；随即"],["sit-upon","n. 屁股"],["thereupon","于是"]]}],"used":[["juːst","juzd"],["中考","CET4","CET6","考研"],[["形容词","unused",1]],[29,3.5,22,9,11],[["adj.","习惯于；适应",2],["adj.","用过的；旧的；二手的",0],["modal v.","（用于过去持续或经常发生的事）曾经",2],["v.","过去惯常，过去常常做…",25]],[["2025 英二 · 阅读 · Part A · Text 1","Today’s tip requests are often not connected to the salary and service norms that used to determine when and how people tip.","如今，索要小费往往与过去决定人们何时及如何付小费的工资和服务惯例无关。","正文"],["2025 英一 · 阅读 · Part A · Text 1","She added “The emotional understanding was very evident and it is probably related to the [rehearsal room process] where you are used to trying to imagine your way through.","她补充说：“他们对情感的理解表现得非常明显，这可能与‘排练室过程’有关，在这个过程中，你习惯于发挥想象，设身处地去体会。","正文"],["2015 英二 · 阅读 · Part A · Text 3","“You have the importation of terminology that historically used to be associated with non-profit organizations and religious organizations: terms like vision, values, passion, and purpose,” said Khurana.","库拉纳说：“一些词语过去常与非营利组织和宗教组织联系在一起，如‘愿景’‘价值观’‘热情’和‘宗旨’，如今却被引入企业。”","正文"],["2013 英二 · 阅读 · Part A · Text 1","Being average just won’t earn you what it used to.","只做到普通水平，已无法让你获得过去那样的收入。","正文"],["2011 英一 · 阅读 · Part A · Text 3","The rough guide to marketing success used to be that you got what you paid for.","过去，营销成功的一条粗略准则是：一分钱一分货。","正文"],["2008 英一 · 阅读 · Part A · Text 2","It used to be so straightforward.","过去，事情非常简单明了。","正文"]],"used.mp3",{"r":[["词根","us-,ut- = use, 表示“用”。"],["后缀","-ed 形容词后缀，加在名词后表示“如...的”；加在动词后表示“被...的”。"]],"d":[]}],"uncle":[["ˈʌŋ.kᵊl","ˈʌŋ·kəl"],["中考","高中"],[["复数","uncles"]],[0,0.0,0,0,0],[["n.","舅父；叔父；伯父；姑父；姨父",0],["n.","（儿童用语，称呼父母的同辈男性朋友）叔叔，伯伯",0]],[],"uncle.mp3",null],"under":[["ˈʌn.dəʳ","ˌʌn·dər；ˈʌn·dər"],["中考","高中"],[],[60,4.5,28,44,12],[["prep.","在（或到、通过）…下面",2],["prep.","在…表面下；由…覆盖着",0],["prep.","少于；小于；不足；比…年轻",4],["prep.","由…造成；受…影响",23],["prep.","由…控制（或管理、经营）",10],["prep.","根据，按照（协议、法律或制度）",14],["prep.","在…过程中",5],["prep.","用，以（某一名字）",1],["prep.","在…项下；在（书等中的）某部分",0],["adv.","在下面",0],["adv.","在水下",0],["adv.","少于；小于；较年轻",0],["adv.","在昏迷中；陷入昏迷状态",0],["adj.","较低的；下面的",0],["idiom","（为了个人利益）出卖某人|牺牲某人|背叛某人",1]],[["2026 英二 · 阅读 · Part A · Text 1","There is an overall decline in visits and many are struggling as local authorities come under continued financial pressure.","总体到访人次在下降，许多图书馆因地方政府持续面临财政压力而举步维艰。","正文"],["2026 英一 · 阅读 · Part A · Text 4","Research shows that these prescribed burns make subsequent wildfires less severe, even if later fires happen under the most dangerous weather conditions.","研究表明，即使后续野火发生在最危险的天气条件下，计划烧除也能降低其严重程度。","正文"],["2026 英一 · 阅读 · Part A · Text 4","“Yet the combined consequences of suppression and climate change have eroded humanity’s ability to suppress fires, particularly those that ignite under the most dangerous weather conditions.”","“然而，灭火措施和气候变化的共同后果削弱了人类抑制火灾的能力，尤其是在最危险的天气条件下燃起的火灾。”","正文"],["2026 英一 · 阅读 · Part A · Text 4","“It’s a double-edged sword because wildfires are getting more severe and larger under climate change and we need this work even more, but then the work gets more challenging,” said Susan Prichard, a fire ecologist at the University of Washington.","华盛顿大学的火灾生态学家苏珊·普里查德说：“这是一把双刃剑。气候变化使野火越来越猛烈、规模越来越大，让我们更加需要做这项工作；但同时，这项工作也变得更难了。”","正文"],["2025 英二 · 阅读 · Part B","In other words, don’t throw old solutions under the bus to make your improvement stand out.","换句话说，别为了突出自己的改进，就把旧方案贬得一文不值。","正文"],["2024 英一 · 阅读 · Part A · Text 4","Will those jurisdictions extend the same protections now denied under Sackett v. EPA?","这些辖区会施行如今被“萨克特诉环保署案”裁决取消的同等保护吗？","正文"]],"under.mp3",{"r":[["前缀","under- = beneath, below, underneath, 表示“在…下”，源自古英语。和源自拉丁语的前缀 infra- 同源。"]],"d":[["underway","进行"],["thereunder","adv. 在那下面,依据"],["cross-under","穿接"]]}],"university":[["ˌjuː.nɪˈvɜː.sə.ti","ˌju·nəˈvɜr·sɪ·t̬i"],["中考","高中","CET4","CET6","考研"],[["复数","universities"]],[127,5.0,39,84,4],[["n.","（综合性）大学；高等学府",127]],[["2026 英二 · 阅读 · Part B","So is soil, says Cindy Prescott, a forest ecologist at the University of British Columbia in Vancouver.","温哥华不列颠哥伦比亚大学的森林生态学家辛迪·普雷斯科特说，土壤也是如此。","正文"],["2026 英一 · 阅读 · Part A · Text 1","“Through their DNA, the animals are telling their history themselves,” co-author Samantha Brooks, an equine researcher at the University of Florida, says in a statement.","共同作者、佛罗里达大学的马科动物研究员萨曼莎·布鲁克斯在一份声明中说：“通过DNA，这些动物自己讲述着自己的历史。”","正文"],["2026 英二 · 阅读 · Part B","“When you talk about conservation or restoration, the first question has to be restoration by whom, for whom?” says Daniel Janzen, a biologist at the University of Pennsylvania.","宾夕法尼亚大学的生物学家丹尼尔·简森说：“谈到保护或恢复，首先必须问：由谁来恢复？为谁恢复？”","正文"],["2026 英一 · 阅读 · Part A · Text 1","“Donkeys are champions when it comes to carrying stuff and are good at going at deserts,” co-author Ludovic Orlando, an evolutionary biologist at Paul Sabin University in France, tells the publication.","共同作者、法国保罗·萨班大学的进化生物学家卢多维克·奥兰多告诉该刊：“论驮运货物，驴是佼佼者，而且善于穿越沙漠。”","正文"],["2026 英一 · 阅读 · Part A · Text 4","But when Swetnam enrolled in graduate school at the University of Arizona’s Laboratory of Tree-Ring Research, he was surprised to find a record of repeated blazes dating back hundreds of years before European colonists arrived on the continent.","但后来，斯韦特南进入亚利桑那大学树木年轮研究实验室攻读研究生，却惊讶地发现一份记录：早在欧洲殖民者抵达这片大陆的几百年前，这里就反复发生过火灾。","正文"],["2026 英一 · 阅读 · Part A · Text 4","“It’s a double-edged sword because wildfires are getting more severe and larger under climate change and we need this work even more, but then the work gets more challenging,” said Susan Prichard, a fire ecologist at the University of Washington.","华盛顿大学的火灾生态学家苏珊·普里查德说：“这是一把双刃剑。气候变化使野火越来越猛烈、规模越来越大，让我们更加需要做这项工作；但同时，这项工作也变得更难了。”","正文"]],"university.mp3",{"r":[["前缀","un,uni = one, 表示“单一、一个”。"],["词根","ver-,vers-,vert-,vir- = turn, 表示“转”，来自拉丁语。"],["后缀","-ity 表名词，指具备某种性质。"]],"d":[["multiversity","n. 〈美〉巨型大学,(由多所学院组成的)多科大学"],["interuniversity","校际"]]}],"unless":[["ənˈles","ənˌles"],["中考","高中","CET4","CET6","考研","TOEFL"],[],[8,2.5,6,8,0],[["conj.","除非；除非在…情况下",2],["conj.","若非；如果不",5],["conj.","除非;除了在…的情况下",1]],[["2023 英一 · 阅读 · Part C","Therefore, unless customers are prepared to sign release agreements, the use of AI may become somewhat restricted in the future.","因此，除非客户愿意签署数据使用许可协议，否则人工智能的应用今后可能会受到一定限制。","正文"],["2020 英一 · 阅读 · Part A · Text 3","The US Supreme Court frowns on sex-based classifications unless they are designed to address an “important” policy interest.","美国最高法院不赞成按性别划分人群，除非这样做是为了实现一项“重要的”政策目标。","正文"],["2020 英一 · 阅读 · Part A · Text 4","France’s planned tax is a clear warning: Unless a broad consensus can be reached on reforming the international tax system, other nations are likely to follow suit, and American companies will face a cascade of different taxes from dozens of nations that will prove burdensome and costly.","法国计划征收的税发出了明确警告：除非各方就改革国际税收体系达成广泛共识，否则其他国家很可能效仿；届时美国公司将面对数十个国家接连征收的不同税种，负担沉重且代价高昂。","正文"],["2017 英一 · 阅读 · Part A · Text 4","Merely helping a gift-giver gain access to other officials, unless done with clear intent to pressure those officials, is not corruption, the justices found.","法官们认为，仅仅帮助送礼者接触其他官员，并不构成贪腐，除非此举明显意在向那些官员施压。","正文"],["2010 英一 · 阅读 · Part A · Text 4","And, unless banks carry toxic assets at prices that attract buyers, reviving the banking system will be difficult.","此外，除非银行把有毒资产的价格定在足以吸引买家的水平，否则银行体系将难以复苏。","正文"],["2010 英一 · 阅读 · Part A · Text 4","America’s new plan to buy up toxic assets will not work unless banks mark assets to levels which buyers find attractive.","除非银行将资产估值调至买家认为有吸引力的水平，否则美国收购有毒资产的新计划不会奏效。","正文"]],"unless.mp3",{"r":[["后缀","-less 表形容词，“无…的，不…的”，和单词loss同源。"]],"d":[]}],"up":[["ʌp","ʌp"],["中考","高中"],[["复数","ups"],["原形","up"],["第三人称单数","ups"],["第三人称单数","up or in intransitive verb sense 2"],["现在分词","upping"],["过去式","upped"],["过去式","up or in intransitive verb sense 2"],["过去分词","upped"]],[235,5.0,44,169,19],[["adv.","向（或在）较高位置；向上；在上面",11],["adv.","向（或在）较高水平；加大；增高",58],["adv.","朝（某人或某物）的方向；向…的地方",2],["adv.","未上床；起床",2],["adv.","到，朝，在（重要地方，尤指大城市）",0],["adv.","向（国家北部的地方）；向（北方）",0],["adv.","完全；彻底地",29],["adv.","（以便）完结，关闭",9],["adv.","成碎片；分开",5],["adv.","（以便）形成，聚拢",41],["adv.","已结束；已过去",0],["adv.","（尤指异常或不愉快的事情）发生，出现",12],["prep.","向，在（较高位置）",1],["prep.","沿着；顺着",2],["prep.","向…上游；溯流而上",0],["adj.","向上的；往上移动的",0],["adj.","高兴；快乐；激动",0],["adj.","在运行",0],["v.","突然移动；突然做（意想不到的事）",0],["v.","提高…的价格（或数量）",0],["v.","提高，增加，提升（价格）",1],["phr. v., v.","养育，抚养;教养",1],["phr. v., v.","占据（地方或时间）",1],["phr. v., v.","（某人）醒来;叫醒（某人），弄醒（某人）",4],["adv.","连续延伸到某一点；一直到",1],["phr. v., v.","（使）继续下去，（使）不停止;（使）不改变",1],["phr. v., v.","补偿，弥补",1],["idiom","真的，属实",1],["phr. v., v.","最后处于;最后成为;以…告终",7],["phr. v.","（碰巧或廉价地）买到",1],["phr. v., v.","注意到;察觉;看到",1],["prep.","是（某人）的职责",1],["adv.","是…的职责（或责任）；由…决定",2],["phr. v., v.","讨论;处理",1],["phrase","化成了烟，被大火烧毁",1],["adj.","现代的;最近的;包含最新信息的",1],["prep.","直到",1],["prep.","是（某人）的职责",2],["phr. v., v.","放弃（某物的所有权或使用权）；交出；让出",1],["phr. v.","引起对…的注意",2],["adv.","事先；提前",1],["phr. v., v.","忍受，忍耐",0],["phr. v., v.","支持，维护（想法、遭受指责或攻击的人）",1],["phr. v., v.","接受（提议、邀请等）",1],["v.","（使）（计算机）启动",1],["phr. v., v.","（电子设备）接收（信号）",1],["phr. v., v.","经得起，承受得住",1],["idiom","愤怒；发火",1],["phr. v., v.","敬仰，敬重",2],["phr. v.","提出（讨论等）",1],["adv.","（表示出现、发生、看到、给予考虑等）",2],["adv.","接近于；至多",3],["phr. v., v.","（尤指对有强烈感受的话题）公开发表意见，坦率说出",1],["phr. v., v.","开始（工作或活动）",3],["adj.","后续行动；后续事物",1],["phr. v., v.","开始谈论;提出（话题）",1],["idiom","坚持；不泄气",1],["v.","（常指不情愿地）被卷入，陷入",1],["phr. v., v.","分（菜）;分（饭）",1],["phr. v.","把某事归因于",1],["adv.","达到（某数量、程度等）；至多有",1],["phr. v., v.","接受，正视（困境）",1],["phr. v., v.","为…提供必需品",1],["phr. v., v.","查阅，检索;（在计算机中）搜索",1],["phr. v., v.","追查…的更多情况;对…采取进一步行动",0],["phr. v., v.","提出（观点）;推举，提名（某人）",1],["phr. v., v.","想出，提出（主意或计划）",1]],[["2026 英二 · 阅读 · Part A · Text 1","If we don’t use them, we will end up losing them.","如果我们不使用图书馆，最终就会失去它们。","正文"],["2026 英一 · 阅读 · Part A · Text 4","In 2022, Swetnam and other scientists teamed up to compile a database of fire-scarred trees from across the continent.","2022年，斯韦特南与其他科学家合作，汇集整个北美大陆有火灾疤痕的树木资料，建成数据库。","正文"],["2026 英一 · 阅读 · Part A · Text 4","To prevent entire ecosystems from going up in smoke, Martin said, people must bring healthy fire back to places that need it.","马丁说，为防止整个生态系统毁于火灾，人们必须让有益的火重新回到需要它的地方。","正文"],["2026 英一 · 阅读 · Part A · Text 4","Because flammable material couldn’t build up on the landscape, blazes tended to move Slowly and peter out when they reached the footprints of previous burns.","由于可燃物无法在地表大量堆积，火势通常蔓延缓慢，遇到以前火灾留下的烧灼地带便逐渐熄灭。","正文"],["2026 英二 · 阅读 · Part A · Text 1","As I visited libraries up and down the country, I was surprised to learn there are more than twice the number of libraries (2,892) as there are branches of McDonald’s.","走访全国各地的图书馆时，我惊讶地得知，图书馆共有 2,892 家，数量是麦当劳门店的两倍多。","正文"],["2026 英一 · 阅读 · Part A · Text 2","Georgia offers up to 30% in transferable tax credits on film and TV production costs, plus an additional 10% increase on the base tax credit if the project includes a Georgia promotional logo.","佐治亚州对影视制作成本提供最高30%的可转让税收抵免；如果项目加入佐治亚州的宣传标识，还可在基础抵免额上再增加10%。","正文"]],"up.mp3",null],"us":[["ʌs；ˌjuːˈes","ʌs；əs；ˈjuˈes"],["中考"],[],[124,5.0,33,91,4],[["pron.","我们",124],["pron.","我",0]],[["2026 英一 · 阅读 · Part A · Text 2","Let’s go on with the show...and make sure the show doesn’t go on without us.","让演出继续吧……也务必确保这场演出不会把我们落下。","正文"],["2026 英二 · 阅读 · Part A · Text 2","Our data shows that engaging with AI like this can leave us feeling heard and less isolated.","我们的数据显示，以这种方式与人工智能互动，能让我们感到有人倾听，也不那么孤独。","正文"],["2026 英二 · 阅读 · Part A · Text 2","But by building a culture of digital responsibility within our businesses, we can create a future where AI can help us without spilling the beans.","但只要在企业内部营造数字责任文化，我们就能创造一个未来，让人工智能帮助我们，同时不泄露秘密。","正文"],["2026 英一 · 阅读 · Part A · Text 3","But inventions shape all of us and it is worth noticing when techno-social habits do change, and asking whether to control them a bit or shield the youngest.","但发明会塑造我们每一个人。技术与社会习惯确实发生变化时，值得留意，并思考是否要稍加约束，或保护最年幼的人。","正文"],["2026 英一 · 阅读 · Part A · Text 3","And while it is wonderful to take a walk with anything in your headphones, infinite choice encourages us to shrink into niche interests and sympathetic beliefs.","而且，虽然散步时耳机里想听什么就听什么很美妙，无限的选择却会促使我们缩进兴趣和观点相近的小圈子。","正文"],["2026 英二 · 阅读 · Part A · Text 2","With AI’s potential to simplify our professional lives, do the admin and enhance the work experience, it’s up to us to navigate its usage cautiously so it supports us without compromising our privacy.","人工智能有望简化我们的工作生活、处理行政事务并改善工作体验；如何谨慎使用它，以便得到帮助又不损害隐私，取决于我们自己。","正文"]],"us.mp3",null],"use":[["juːz；juːs","juz；jus"],["中考","高中"],[["复数","uses"],["原形","use"],["第三人称单数","uses"],["现在分词","using"],["过去式","used"],["过去分词","used"],["形容词","useful",1],["形容词","useless",1],["副词","usefully",1],["副词","uselessly",1],["名词","uselessness",1]],[368,5.0,44,191,33],[["v.","使用；利用；运用",185],["v.","消耗",4],["v.","说，写，使用（词语或语言）",77],["v.","（施展手段）利用（别人）",0],["v.","吸（毒）；服用（毒品）",0],["n.","用；使用；得到利用",67],["n.","用途；功能；用法",2],["n.","使用权；使用的机会",0],["n.","运用头脑（或身体）的能力；功能",0],["n.","说，写，使用（词语或语言）",5],["modal v.","（用于过去持续或经常发生的事）曾经",3],["phrase","过去惯常，过去常常做…",4],["n.","不需要；用不着",1],["v.","过去惯常，过去常常做…",20]],[["2026 英二 · 阅读 · Part A · Text 1","If we don’t use them, we will end up losing them.","如果我们不使用图书馆，最终就会失去它们。","正文"],["2026 英二 · 阅读 · Part A · Text 2","According to our research, 25% have decided to either outright ban AI or regulate its use within their organisations.","根据我们的研究，25% 的雇主决定要么全面禁止使用人工智能，要么对其在机构内部的使用加以规范。","正文"],["2026 英一 · 阅读 · Part A · Text 4","At Yosemite National Park, Martin oversaw the use of what is known as prescribed burns to make the landscape more resilient.","在优胜美地国家公园，马丁曾监督开展所谓的“计划烧除”，以增强当地生态环境的韧性。","正文"],["2026 英二 · 阅读 · Part A · Text 2","They have their reasons — around 63% of them report that using AI increases their productivity, and some even feel AI offers more help than their human colleagues.","他们自有理由：其中约 63% 的人表示，使用人工智能提高了工作效率，有些人甚至觉得它比同事更能帮上忙。","正文"],["2026 英二 · 阅读 · Part A · Text 2","It grants Microsoft broad rights to the data inputted or outputted by any user — rights to use this data in any way it sees fit; it can even share it with third parties.","它赋予微软广泛的权利，可按其认为合适的任何方式使用任何用户输入或输出的数据，甚至可以将这些数据分享给第三方。","正文"],["2026 英一 · 阅读 · Part A · Text 1","The team reconstructed the animals’ evolutionary tree and used computer models to pinpoint the domestication event when herders in Kenya and the Horn of Africa tamed wild asses.","团队重建了这些动物的进化树，并用计算机模型确定驯化发生的时间：当时，肯尼亚及非洲之角的牧民驯服了野驴。","正文"]],"use.mp3",{"r":[["词根","us-,ut- = use, 表示“用”。"]],"d":[["usage","n. 用法；使用；惯例"],["used","1. adj. 习惯的；二手的，使用过的 2. v. 用；习惯（use的过去式）"],["useful","adj. 有用的，有益的；有帮助的"],["useless","adj. 无用的；无效的"],["user","1. 用户 2. 使用者"]]}],"usual":[["ˈjuː.ʒu.əl","ˈju·ʒu·əl"],["中考","高中","CET4","CET6","考研","IELTS"],[["复数","usuals"],["名词","usualness",1],["副词","usually",1],["形容词","unusual",1],["副词","unusually",1],["名词","unusualness",1]],[10,2.5,6,6,0],[["adj.","通常的；寻常的；惯常的",10],["adj.","惯常的事物；（尤指）常喝的饮料",0]],[["2016 英二 · 阅读 · Part A · Text 3","What makes the problem thornier is that the usual time-management techniques don’t seem sufficient.","问题更加棘手的是，通常的时间管理技巧似乎并不管用。","正文"],["2011 英一 · 阅读 · Part A · Text 2","Rather than cloaking his exit in the usual vague excuses, he came right out and said he was leaving “to pursue my goal of running a company.”","他没有用惯常的含糊托辞掩饰离职原因，而是直截了当地说，他离开是“为了实现经营一家公司的目标”。","正文"],["2011 英一 · 阅读 · Part A · Text 4","There are also stories about newly adoptive — and newly single — mom Sandra Bullock, as well as the usual “Jennifer Aniston is pregnant” news.","此外，还有关于刚成为养母且刚恢复单身的桑德拉·布洛克的报道，以及常见的“詹妮弗·安妮斯顿怀孕了”之类新闻。","正文"],["2005 英一 · 阅读 · Part B · 第45题 · 选项B","Or they could read Mr. Kirby’s report: “The substantial buying power of such an agency would strengthen the public prescription-drug insurance plans to negotiate the lowest possible purchase prices from drug companies.” So when the premiers gather in Niagara Falls to assemble their usual complaint list, they should also get cracking about something in their jurisdiction that would help their budgets and patients.","或者他们可以读读柯比先生的报告：“这样一个机构强大的购买力将增强公共处方药保险计划与制药公司谈判的能力，以争取尽可能低的采购价格。”所以，当省长们聚集在尼亚加拉瀑布市，准备列出惯常的抱怨清单时，也应该着手处理一件属于其职权范围内、能让预算和患者都受益的事情。","正文"],["2003 英一 · 阅读 · Part A · Text 1","Straitford’s briefs don’t sound like the usual Washington back-and-forthing, whereby agencies avoid dramatic declarations on the chance they might be wrong.","Straitford的简报不像华盛顿各机构惯有的那种反复拉扯的措辞：那些机构唯恐判断失误，因此回避鲜明的断言。","正文"],["2000 英一 · 阅读 · Part A · Text 5","Such, then, is the way things stand: on the left angry critics, on the right stupid supporters, and in the middle, as usual, the majority of earnest people trying to get on in life.","因而，现状是：左边是愤怒的批评者，右边是愚蠢的支持者，而中间照例是大多数勤恳的人，他们正努力改善生活。","正文"]],"usual.mp3",{"r":[["词根","us-,ut- = use, 表示“用”。"],["后缀","-al,-ial 表形容词，“…的”，一般缀于名词后。"]],"d":[["unusual","adj. 与众不同的；不寻常的；不平常的"],["usually","adv. 通常，经常"]]}],"usually":[["ˈjuː.ʒu.ə.li","ˈju.ʒu.ə.li"],["高中"],[],[33,4.0,22,18,8],[["adv.","通常地；正常地；一般地；经常地",33]],[["2026 英一 · 阅读 · Part A · Text 1","“We usually only get the human’s side of history through written accounts, but of course written history does not always record exactly how something happened.","“我们通常只能通过文字记载了解人类视角的历史；但文字记载当然并不总能准确记录事情的经过。","正文"],["2023 英二 · 阅读 · Part A · Text 1","However, supporters of fake grass point out that there is also an environmental impact with natural lawns, which need mowing and therefore usually consume electricity or petrol.","然而，人造草坪的支持者指出，天然草坪同样会影响环境，因为它需要修剪，通常因此要耗用电力或汽油。","正文"],["2022 英一 · 阅读 · Part C","(49) There may have been many spies and intelligence officers during the Napoleonic Wars, but it is usually extremely difficult to find the material they actually provided or worked on.","拿破仑战争期间或许有过许多间谍和情报官员，但要找到他们实际提供或处理过的材料，通常极为困难。","正文"],["2021 英二 · 阅读 · Part A · Text 1","When the skills mismatch is in the broader economy, though, the focus usually turns to government to handle.","不过，当技能错配存在于整个经济领域时，解决问题的重心通常会转向政府。","正文"],["2019 英一 · 阅读 · Part A · Text 4","The ruling is a victory for big chains with a presence in many states, since they usually collect sales tax on online purchases already.","这一裁决对在多个州设有经营场所的大型连锁企业是个好消息，因为它们通常早已对网上购物征收销售税。","正文"],["2019 英一 · 阅读 · Part A · Text 2","When this practice first started decades ago, it was usually limited to freshmen, to give them a second chance to take a class in their first year if they struggled in their transition to college-level courses.","几十年前，这种做法刚出现时，通常只面向大一新生：如果他们难以适应大学课程，就给他们一次重修第一年课程的机会。","正文"]],"usually.mp3",{"r":[["词根","us-,ut- = use, 表示“用”。"],["后缀","-al,-ial 表形容词，“…的”，一般缀于名词后。"],["后缀","-ly 表副词，通常缀于形容词后。"]],"d":[]}],"ultimately":[["ˈʌl.tɪ.mət.li","ˈʌl·tə·mət·li"],["CET4","CET6","IELTS"],[],[7,2.0,7,5,0],[["adv.","最终；最后；终归",5],["adv.","最基本地；根本上",2]],[["2025 英一 · 阅读 · Part A · Text 2","The carbon emissions from technological research are well spent: ultimately this research will safeguard the future of our planet.","技术研究产生的碳排放是值得的：归根结底，这项研究将保障我们星球的未来。","正文"],["2022 英二 · 阅读 · Part A · Text 2","“The most challenging moments in life are getting married, starting a family and ultimately retiring,” Weiss said.","“人生中最具挑战的时刻，是结婚、组建家庭，以及最终退休，”韦斯说。","正文"],["2019 英一 · 阅读 · Part A · Text 2","“Ultimately,” said Jack Miner, Ohio State University’s registrar, “we see students achieve more success because they retake a course and do better in subsequent courses or master the content that allows them to graduate on time.”","俄亥俄州立大学教务注册主任杰克·迈纳说：“归根结底，我们看到学生重修一门课后，在后续课程中表现得更好，或掌握了使他们能够按时毕业的内容，因此取得了更大成功。”","正文"],["2012 英二 · 阅读 · Part A · Text 4","And ultimately, it is likely to reshape our politics, our culture, and the character of our society for years.","最终，它还可能在未来多年重塑我们的政治、文化和社会风貌。","正文"],["2001 英一 · 阅读 · Part B","(44) But that, Pearson points out, is only the start of man-machine integration: “It will be the beginning of the long process of integration that will ultimately lead to a fully electronic human before the end of the next century.”","（44）但皮尔逊指出，那只是人机融合的开端：“这将是漫长融合过程的起点；这一过程最终会在下个世纪结束前造就完全电子化的人类。”","正文"],["2012 英一 · 阅读 · Part B · 选项A","A) Of course, it is precisely these superfluous things that define human culture and ultimately what it is to be human.","A）当然，正是这些非生存必需之物定义了人类文化，并最终界定了何以为人。",""]],"ultimately.mp3",{"r":[["词根","ultim- = last, 表示“最后的”。"],["后缀","-ly 表副词，通常缀于形容词后。"]],"d":[]}],"unacceptable":[["ˌʌn.əkˈsep.tə.bᵊl","ˌʌn·ɪkˈsep·tə·bəl"],[],[["名词","unacceptability",1],["副词","unacceptably",1]],[1,0.5,1,0,0],[["adj.","不能接受（或允许、同意）的",1]],[["2003 英一 · 阅读 · Part A · Text 2 · 第27题 · 选项B","Misled people tend to think that using an animal in research is inhuman and unacceptable.","受到误导的人往往认为，把动物用于研究是不人道且不可接受的。","选项"]],"unacceptable.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["前缀","ab,ac,ad,af,ag,al,an,ap,ar,as,at- 来自拉丁介词ad, 表示“朝、向、去，或弱化为强调”。在字母 b, f, g, l, n, p, r, s, t 前同化为 ab-, af-, ag-, al-, an-, ap-, ar-, as-, at-；在 c, k, qu 前同化为 ac-；在 sc, sp, st 前缩写成 a-."],["词根","cap-,capt-,cept-,ceiv-,cip-,cup- = take, hold, seize, 表示“拿，抓，握住”，来源于拉丁语。"],["后缀","-able 一般缀于动词后，构成形容词，表示“可…的，能…”。"]],"d":[]}],"unaccountably":[["ˌʌn.əˈkaʊn.tə.bᵊl.i","ˌʌnəˈkaʊntəbli"],[],[],[0,0.0,0,0,0],[["adv.","难以解释地；莫名其妙地；无明显原因地",0]],[],"unaccountably.mp3",null],"unacknowledged":[["ˌʌn.əkˈnɒl.ɪdʒd","ˌʌnəkˈnɑlɪdʒd"],[],[],[2,1.0,2,1,0],[["adj.","未得到应有的感激（或赞赏）的",0],["adj.","不被承认存在（或真实）的；未被意识到的",1],["adj.","未得到公开（或正式）承认的；非正式的",1]],[["2015 英一 · 阅读 · Part B · 第45题 · 选项A","Are we studying that text and trying to respond in a way that fulfils the requirement of a given course? Reading it simply for pleasure? Skimming it for information? Ways of reading on a train or in bed are likely to differ considerably from reading in a seminar room. Such dimensions of reading suggest — as others introduced later in the book will also do — that we bring an implicit (often unacknowledged) agenda to any act of reading.","我们是在研读那篇文章，并试图按某门课程的要求作出回应吗？只是为了乐趣而阅读它吗？为了获取信息而略读它吗？在火车上或床上阅读，与在研讨室里阅读的方式很可能大不相同。 阅读的这些维度提示我们——本书后文将介绍的其他维度也是如此——任何阅读行为都带着一种隐含的、往往未被承认的目的。","正文"],["2017 英一 · 阅读 · Part B · 选项F","He could not confide them even to his wife, although they provide the unacknowledged foundation of his fiction.","他甚至无法向妻子倾诉这些经历，尽管它们构成了其小说不为人知的根基。",""]],"unacknowledged.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["前缀","ab,ac,ad,af,ag,al,an,ap,ar,as,at- 来自拉丁介词ad, 表示“朝、向、去，或弱化为强调”。在字母 b, f, g, l, n, p, r, s, t 前同化为 ab-, af-, ag-, al-, an-, ap-, ar-, as-, at-；在 c, k, qu 前同化为 ac-；在 sc, sp, st 前缩写成 a-."],["后缀","-ed 形容词后缀，加在名词后表示“如...的”；加在动词后表示“被...的”。"]],"d":[]}],"unaffected":[["ˌʌn.əˈfek.tɪd","ˌʌn·əˈfek·tɪd"],["GRE"],[["副词","unaffectedly",1],["名词","unaffectedness",1]],[1,0.5,1,0,1],[["adj.","未被改变的；未受影响的；无动于衷的",1],["adj.","真诚自然的；真挚的；不做作的",0]],[["2016 英一 · 阅读 · Part A · Text 4 · 第39题 · 选项D","Peretti believes that, in a changing world, traditional luxuries can stay unaffected.","佩雷蒂认为，在不断变化的世界里，传统奢侈品可以不受影响。","选项"]],"unaffected.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["前缀","ab,ac,ad,af,ag,al,an,ap,ar,as,at- 来自拉丁介词ad, 表示“朝、向、去，或弱化为强调”。在字母 b, f, g, l, n, p, r, s, t 前同化为 ab-, af-, ag-, al-, an-, ap-, ar-, as-, at-；在 c, k, qu 前同化为 ac-；在 sc, sp, st 前缩写成 a-."],["词根","fac-,fact-,fect-,fic- = make, do, 表示“做，制作”，来自拉丁语 facere \"to make\"。"],["后缀","-ed 形容词后缀，加在名词后表示“如...的”；加在动词后表示“被...的”。"]],"d":[]}],"unaffordable":[["ˌʌn.əˈfɔː.də.bᵊl","ˌʌnəˈfɔrdəbl"],[],[["副词","unaffordably",1]],[2,1.0,2,0,2],[["adj.","买不起的；负担不起的",2]],[["2013 英一 · 阅读 · Part A · Text 1 · 第24题 · 选项C","Which of the following can be inferred from the last paragraph? People are more interested in unaffordable garments.","从最后一段可以推断出以下哪一项？人们对买不起的衣服更感兴趣。","选项"],["2003 英一 · 阅读 · Part A · Text 4 · 第37题 · 选项D","The author uses the example of cancer patients to show that medical costs are becoming unaffordable.","作者以癌症患者为例，是为了说明医疗费用正变得难以负担。","选项"]],"unaffordable.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["前缀","per- 表示“完全，贯穿，自始至终，向前”。forth, ford 是其同源词。"],["前缀","ab,ac,ad,af,ag,al,an,ap,ar,as,at- 来自拉丁介词ad, 表示“朝、向、去，或弱化为强调”。在字母 b, f, g, l, n, p, r, s, t 前同化为 ab-, af-, ag-, al-, an-, ap-, ar-, as-, at-；在 c, k, qu 前同化为 ac-；在 sc, sp, st 前缩写成 a-."],["后缀","-able 一般缀于动词后，构成形容词，表示“可…的，能…”。"]],"d":[]}],"unanswered":[["ʌnˈɑːn.səd","ʌnˈæn·sərd"],[],[],[3,1.5,2,2,0],[["adj.","未回答的；未解答的；悬而未决的",3],["adj.","未回复（或答复）的",0]],[["2012 英二 · 阅读 · Part A · Text 3","Despite the appeals court’s decision, big questions remain unanswered.","尽管上诉法院作出了判决，一些重大问题仍未得到解答。","正文"],["2005 英一 · 阅读 · Part A · Text 1","However, whether such a sense of fairness evolved independently in capuchins and humans, or whether it stems from the common ancestor that the species had 35 million years ago, is, as yet, an unanswered question.","不过，这种公平感究竟是在卷尾猴和人类身上分别独立进化而来，还是源于两个物种在3500万年前共有的祖先，至今仍是未解之谜。","正文"],["2012 英二 · 阅读 · Part A · Text 1 · 第24题 · 选项B","As mentioned in Paragraph 4, a key question unanswered about homework is whether it counts much in schooling.","如第四段所述，关于家庭作业仍未得到回答的一个关键问题是：它在学校教育中是否起着重要作用。","题干"]],"unanswered.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","swer- = to swear，表示“誓言”。"],["前缀","anti- 表示“反对，相反”，来源于希腊语。"],["后缀","-ed 形容词后缀，加在名词后表示“如...的”；加在动词后表示“被...的”。"]],"d":[]}],"unattractive":[["ˌʌn.əˈtræk.tɪv","ˌʌn·əˈtræk·tɪv"],[],[["副词","unattractively",1],["名词","unattractiveness",1]],[2,1.0,2,2,0],[["adj.","不悦目的；不漂亮的；难看的",1],["adj.","不好的；无趣的；令人反感的",1]],[["2013 英一 · 阅读 · Part A · Text 1","In the 2006 film version of The Devil Wears Prada, Miranda Priestly, played by Meryl Streep, scolds her unattractive assistant for imagining that high fashion doesn’t affect her.","在 2006 年的电影版《穿普拉达的女王》中，梅丽尔·斯特里普饰演的米兰达·普里斯特利斥责她那位其貌不扬的助理，因为助理以为高级时装不会影响自己。","正文"],["2000 英一 · 阅读 · Part A · Text 5","The attacks on ambition are many and come from various angles; its public defenders are few and unimpressive, where they are not extremely unattractive.","对雄心的抨击很多，来自不同角度；公开为它辩护的人寥寥无几，若非极不讨人喜欢，也缺乏说服力。","正文"]],"unattractive.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["前缀","ab,ac,ad,af,ag,al,an,ap,ar,as,at- 来自拉丁介词ad, 表示“朝、向、去，或弱化为强调”。在字母 b, f, g, l, n, p, r, s, t 前同化为 ab-, af-, ag-, al-, an-, ap-, ar-, as-, at-；在 c, k, qu 前同化为 ac-；在 sc, sp, st 前缩写成 a-."],["词根","trag-,tract- = draw, 表示“拉，拖”，源自拉丁语 trahere \"to draw, drag\"。"],["后缀","-ive,-ative,-itive 表形容词。"]],"d":[]}],"unaware":[["ˌʌn.əˈweəʳ","ˌʌn·əˈweər"],[],[["副词","unawarely",1],["名词","unawareness",1]],[4,1.5,4,3,0],[["adj.","不知道；没意识到；未察觉",4]],[["2009 英一 · 阅读 · Part A · Text 1","All of us work through problems in ways of which we’re unaware, she says.","她说，我们每个人都以自己没有察觉的方式来解决问题。","正文"],["2004 英一 · 阅读 · Part A · Text 2","This, for those as yet unaware of such a disadvantage, refers to discrimination against those whose surnames begin with a letter in the lower half of the alphabet.","对于尚未意识到这种不利处境的人来说，它指的是姓氏首字母位于字母表后半部分的人所遭受的歧视。","正文"],["2003 英一 · 阅读 · Part A · Text 2","To those who are unaware that animal research was needed to produce these treatments, as well as new treatments and vaccines, animal research seems wasteful at best and cruel at worst.","对那些不知道这些疗法以及新疗法和疫苗都离不开动物研究的人来说，动物研究轻则显得浪费，重则显得残忍。","正文"],["2023 英二 · 完形","Most customers were simply unaware of the premium version and what it offered.","大多数客户只是不知道有高级版，也不了解它提供哪些功能。",""]],"unaware.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["前缀","a- 加在单词前，表示“在…的”；表示“不、无、非”；表示“加强”。"],["词根","ware- = be wary，be careful 小心，意识到"]],"d":[]}],"unbearably":[["ʌnˈbeə.rə.bli","ʌnˈbeər·ə·bli"],[],[["副词","unbearably",1]],[1,0.5,1,1,0],[["adv.","难耐的；无法接受的；难以处理的",1]],[["2015 英一 · 阅读 · Part C","Sometimes storms blew the vessels far off their course, and often calm brought unbearably long delay.","风暴有时会把船只吹离航线很远，而无风的天气又常常造成漫长得难以忍受的延误。","正文"]],"unbearably.mp3",null],"unbiased":[["ʌnˈbaɪəst","ʌnˈbaɪəst"],["TOEFL"],[["名词","unbiasedness",1],["副词","unbiasedly",1]],[2,1.0,2,0,1],[["adj.","公正的；不偏不倚的；无偏见的",2]],[["2013 英一 · 完形","At first glance this might seem like a strength that grants the ability to make judgments which are unbiased by external factors.","乍看之下，这似乎是一种优势，使人能够作出不受外部因素影响的判断。",""],["2011 英二 · 阅读 · Part A · Text 1 · 第22题 · 选项B","We learn from Paragraph 2 that outside directors are supposed to be unbiased executives.","从第二段可以得知，外部董事本应是公正无偏的管理者。","选项"]],"unbiased.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["后缀","-ed 形容词后缀，加在名词后表示“如...的”；加在动词后表示“被...的”。"]],"d":[]}],"uncanny":[["ʌnˈkæn.i","ʌnˈkæn·i"],["TOEFL","GRE"],[["比较级","uncannier"],["最高级","uncanniest"],["副词","uncannily",1],["名词","uncanniness",1]],[1,0.5,1,1,0],[["adj.","异常的；难以解释的",1]],[["2013 英一 · 阅读 · Part C","In them we can see biophilia — a yearning for contact with nonhuman life — assuming uncanny representational forms.","在这些花园中，我们可以看到亲生命性——一种渴望接触非人类生命的情感——以奇特的表现形式呈现出来。","正文"]],"uncanny.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","gn-,gnos-,gnor- = know, 表示“知道”，来自拉丁语。"],["后缀","-y 表形容词，加在名词后变成形容词。"]],"d":[["uncannily","惊异"]]}],"uncertain":[["ʌnˈsɜː.tᵊn","ʌnˈsɜr·tᵊn"],["高中","CET4","CET6"],[["副词","uncertainly",1],["名词","uncertainness",1]],[8,2.5,7,3,2],[["adj.","无把握；犹豫；拿不准",1],["adj.","多变的；难预料的",2],["adj.","不确定的；未决定的",4],["adj.","信心不足的；迟疑的",0],["adj.","拿不定主意的，犹豫的",1]],[["2020 英二 · 阅读 · Part A · Text 3","But with legal battles ahead, the zone’s future looks uncertain at best.","但接下来还有法律争端，这个区域的前途充其量也只能说不明朗。","正文"],["2012 英二 · 阅读 · Part A · Text 4","But for the most part, these benefits seem thin, uncertain, and far off.","但总的来看，这些好处似乎微不足道、难以确定，而且还很遥远。","正文"],["2005 英一 · 阅读 · Part A · Text 2","That the evidence was inconclusive, the science uncertain?","他们说证据没有定论，科学结论也不确定。","正文"],["2022 英二 · 阅读 · Part A · Text 4 · 第39题 · 选项C","Nina Strohminger thinks that the effect of the intervention is uncertain.","妮娜·斯特罗明格认为，这项干预的效果尚不确定。","选项"],["2020 英一 · 阅读 · Part A · Text 4 · 第39题 · 选项C","It can be learned from Paragraph 5 that the OECD’s current work is faced with uncertain prospects.","从第五段可以得知，经济合作与发展组织（OECD）目前的工作面临不确定的前景。","选项"],["2005 英一 · 阅读 · Part A · Text 1 · 第25题 · 选项B","What can we infer from the last paragraph? Human indignation evolved from an uncertain source.","我们能从最后一段推断出什么？人类的义愤从何演化而来，尚不确定。","选项"]],"uncertain.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","cern-,cert-,cret-,crimin- = to separate 区分"]],"d":[["uncertainty","不确定"]]}],"uncharted":[["ʌnˈtʃɑː.tɪd","ʌnˈtʃɑr·t̬ɪd"],["TOEFL"],[],[1,0.5,1,1,0],[["adj.","地图上未绘出（或未标明）的",1]],[["2015 英一 · 阅读 · Part C","(46) This movement, driven by powerful and diverse motivations, built a nation out of a wilderness and, by its nature, shaped the character and destiny of an uncharted continent.","（46）这场由强大而多样的动机推动的人口迁移，在荒野中建立了一个国家，并以其自身特性塑造了一块尚未勘明的大陆的性格与命运。","正文"]],"uncharted.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","card-,chart- = paper, 表示“纸片”。"],["后缀","-ed 形容词后缀，加在名词后表示“如...的”；加在动词后表示“被...的”。"]],"d":[]}],"unclean":[["ʌnˈkliːn","ʌnˈklin"],[],[["名词","uncleanness",1],["副词","uncleanly",1],["名词","uncleanliness",1]],[1,0.5,1,1,0],[["adj.","肮脏的，不洁净的（因而容易致病）",0],["adj.","邪恶的；不洁的；（宗教上所指）不洁净的",1]],[["2009 英一 · 阅读 · Part A · Text 4","Sexual confusion, economic frustrations, and religious hope — all came together in a decisive moment when he opened the Bible, told his father that the first line he saw would settle his fate, and read the magical words: “Come out from among them, touch no unclean thing, and I will be your God and you shall be my people.”","性方面的困惑、经济上的挫折和宗教的希望，在决定性的一刻交织在一起：他打开《圣经》，告诉父亲，自己看到的第一行字将决定命运，随后读到了那些似有魔力的话：“你们务要从他们中间出来，不要沾染不洁之物；我必作你们的上帝，你们也必作我的子民。”","正文"]],"unclean.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","cl-,gl-,yell- 表示“光滑，发光”。"]],"d":[["uncleaned","未弄清洁的"]]}],"uncontrollable":[["ˌʌn.kənˈtrəʊ.lə.bᵊl","ˌʌn·kənˈtroʊ·lə·bəl"],[],[["名词","uncontrollability",1],["副词","uncontrollably",1]],[2,1.0,2,2,0],[["adj.","无法控制的；难以防止的；禁不住的",2]],[["2006 英一 · 阅读 · Part B","The fourth edition of the Diagnostic and Statistical Manual of Mental Disorders says “pathological gambling” involves persistent, recurring and uncontrollable pursuit less of money than of the thrill of taking risks in quest of a windfall.","《精神障碍诊断与统计手册》第四版指出，“病理性赌博”表现为一种持续、反复且无法控制的追逐：人们追逐的与其说是金钱，不如说是为了意外横财而冒险的刺激。","正文"],["2001 英一 · 阅读 · Part A · Text 4","Many in these countries are looking at this process and worrying: “Won’t the wave of business concentration turn into an uncontrollable anti-competitive force?”","这些国家的许多人注视着这一进程，忧心忡忡：“企业集中的浪潮会不会演变为无法控制的反竞争力量？”","正文"]],"uncontrollable.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["前缀","contra- = against, 表示“反对，相反”，来自拉丁语。com- \"with, together\" + -tr \"comparative suffix \"，本意放在一起比较。"],["词根","rol- = ring, circle, 表示“圆，环，滚动”。"],["后缀","-able 一般缀于动词后，构成形容词，表示“可…的，能…”。"]],"d":[]}],"unconventional":[["ˌʌn.kənˈven.ʃᵊn.ᵊl","ˌʌn·kənˈven·ʃə·nᵊl"],["CET6","TOEFL"],[["名词","unconventionality",1],["副词","unconventionally",1]],[3,1.5,3,3,0],[["adj.","不因循守旧的；不因袭的；新奇的",3]],[["2025 英二 · 阅读 · Part A · Text 4","As desire paths criss-cross through both physical and virtual landscapes, they stand as a proof of the collective insistence on forging unconventional routes and embracing the spirit of communal choice.","愿望路径纵横交错于现实与虚拟空间，证明人们始终坚持开辟不同寻常的路线，也认同群体自主选择的精神。","正文"],["2024 英二 · 阅读 · Part B","Joseph Adegboyega-Edun, a Maryland high school guidance counselor, says unconventional extracurricular activities can help students impress college admissions offices, assuming they demonstrated serious commitment.","马里兰州高中升学顾问约瑟夫·阿德格博耶加－埃敦说，只要学生表现出认真投入，不寻常的课外活动就能帮助他们给大学招生部门留下深刻印象。","正文"],["2011 英一 · 阅读 · Part A · Text 2","The decision to quit a senior position to look for a better one is unconventional.","辞去高管职位去寻找更好的职位，是一种不合常规的决定。","正文"]],"unconventional.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["前缀","co-,com-,con-,col-,cor- 来自拉丁语介词com，表示“与...一起，一起（with, together）”，或仅做强调。"],["词根","ven,vent- = come, 表示“来”，来自拉丁语。"],["后缀","-ion,-ation,-ition 表名词，“行为、动作、状态、过程、结果；物品”等。"],["后缀","-al,-ial 表形容词，“…的”，一般缀于名词后。"]],"d":[]}],"uncool":[["ʌnˈkuːl","ʌnˈkul"],[],[["最高级","uncoolest"]],[1,0.5,1,1,0],[["adj.","不时髦的；不帅的；不潇洒的；不 “酷” 的",1]],[["2012 英一 · 阅读 · Part A · Text 1","Rosenberg, the recipient of a Pulitzer Prize, offers a host of examples of the social cure in action: In South Carolina, a state-sponsored antismoking program called Rage Against the Haze sets out to make cigarettes uncool.","普利策奖得主罗森伯格举出了许多社会疗法付诸实践的例子：在南卡罗来纳州，一项名为“反抗烟霾”的州政府资助的反吸烟项目，旨在让香烟变得不酷。","正文"]],"uncool.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"]],"d":[]}],"undercut":[["ˌʌn.dəˈkʌt；ˈʌn.də.kʌt","ˌʌn·dərˈkʌt"],["GRE"],[["复数","undercuts"],["原形","undercut"],["第三人称单数","undercuts"],["现在分词","undercutting"],["过去式","undercut"],["过去分词","undercut"],["名词","undercutter",1]],[3,1.5,3,3,0],[["v.","削价竞争；以低于（竞争对手）的价格出售",0],["v.","削弱；使降低效力",3],["n.","大盖儿头发型；帽盔式发型；华盖式发型",0]],[["2024 英二 · 阅读 · Part A · Text 1","“An economy of tech millionaires or billionaires and gig workers, with middle-income jobs undercut by automation, will not be politically sustainable.”","“一个由科技行业的百万富翁、亿万富翁和零工构成，而中等收入岗位被自动化侵蚀的经济体，在政治上将难以持续。”","正文"],["2023 英二 · 阅读 · Part A · Text 2","Moreover, increased privatization would certainly undercut one of the major reasons why 300 million visitors come to the parks each year: to enjoy nature and get a break from the commercial drumbeat that overwhelms daily life.","此外，扩大私有化必定会损害每年吸引3亿游客前来公园的一大原因：亲近自然，暂时摆脱充斥日常生活的商业喧嚣。","正文"],["2021 英二 · 阅读 · Part B","When your body language communicates reluctance or anxiety, it undercuts the message.","当你的肢体语言流露出不情愿或焦虑时，你的话就失去了说服力。","正文"]],"undercut.mp3",{"r":[["前缀","under- = beneath, below, underneath, 表示“在…下”，源自古英语。和源自拉丁语的前缀 infra- 同源。"]],"d":[]}],"undesirable":[["ˌʌn.dɪˈzaɪə.rə.bᵊl","ˌʌn·dɪˈzɑɪər·ə·bəl"],["CET6","考研","GRE"],[["复数","undesirables"],["名词","undesirability",1],["名词","undesirableness",1],["副词","undesirably",1]],[3,1.5,3,1,1],[["adj.","不想要的；不得人心的；易惹麻烦的",3],["n.","不受欢迎的人；不良分子",0]],[["2008 英一 · 阅读 · Part A · Text 1","While still catching up to men in some spheres of modern life, women appear to be way ahead in at least one undesirable category.","虽然在现代生活的某些领域，女性仍在努力赶上男性，但至少在一个不受欢迎的类别里，她们似乎遥遥领先。","正文"],["2014 英一 · 阅读 · Part A · Text 3 · 第35题 · 选项C","The author believes that the new awards are subject to undesirable changes.","作者认为，新奖项容易发生不受欢迎的变化。","选项"],["2012 英一 · 阅读 · Part A · Text 1 · 第21题 · 选项D","According to the first paragraph, peer pressure often emerges as a cause of undesirable behaviors.","根据第一段，同辈压力往往是导致不良行为的一个原因。","选项"]],"undesirable.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","desider- = to want"],["后缀","-able 一般缀于动词后，构成形容词，表示“可…的，能…”。"]],"d":[]}],"undeveloped":[["ˌʌn.dɪˈvel.əpt","ˌʌn·dɪˈvel·əpt"],[],[],[1,0.5,1,1,0],[["adj.","未开垦的；未利用的；未开发的",0],["adj.","不发达的；落后的",1],["adj.","发育不良的；未充分发育的",0]],[["2009 英一 · 阅读 · Part C","In undeveloped social groups, we find very little formal teaching and training.","在发展程度较低的社会群体中，正规的教学与训练很少见。","正文"]],"undeveloped.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["前缀","de- 来自拉丁语介词形式de, 表示“从，从...离开，从...向下，向下”。由其基本词义引申词义 1.彻底离开，完全离开，完全下去，因而表完全，表整个，表加强；2.由离开表没有，相反，使相反，使反转。"],["词根","vel-, velop- = to cover, 表示“盖上”； = veil, 表示“膜”。"],["后缀","-ed 形容词后缀，加在名词后表示“如...的”；加在动词后表示“被...的”。"]],"d":[]}],"undoubted":[["ʌnˈdaʊ.tɪd","ʌnˈdaʊt̮əd"],[],[["副词","undoubtedly",1]],[1,0.5,1,0,0],[["adj.","无疑的；确实的；千真万确的",1]],[["2015 英一 · 阅读 · Part A · Text 1 · 第22题 · 选项A","Monarchs are kept as heads of state in Europe mostly owing to their undoubted and respectable status.","欧洲保留君主担任国家元首，主要是因为他们的地位毋庸置疑，而且受人尊敬。","选项"]],"undoubted.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","dubit- = to doubt, 表示“怀疑”。"],["后缀","-ed 形容词后缀，加在名词后表示“如...的”；加在动词后表示“被...的”。"]],"d":[["undoubtedly","adv. 毋庸置疑地,的确地"]]}],"undue":[["ʌnˈdʒuː","ʌnˈdu"],["IELTS"],[],[1,0.5,1,1,0],[["adj.","不适当的；过分的；过度的",1]],[["2007 英一 · 阅读 · Part C","While the quality of legal journalism varies greatly, there is an undue reliance amongst many journalists on interpretations supplied to them by lawyers.","尽管法律新闻报道的质量差异很大，许多记者却过度依赖律师提供的解释。","正文"]],"undue.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","deb- = to owe, 表示“欠债”，来自拉丁语。"]],"d":[["unduly","adv. 过度地；不适当地；不正当地"]]}],"uneconomic":[["ʌnˌiː.kəˈnɒm.ɪk","ˌʌnɛkəˈnɑmɪk；ˌʌnikəˈnɑmɪk"],[],[],[1,0.5,1,1,0],[["adj.","不赢利的；不赚钱的",1]],[["2010 英一 · 阅读 · Part C","It assumes, falsely, that the economic parts of the biotic clock will function without the uneconomic parts.","它错误地认为，生物时钟中有经济价值的部分可以离开那些没有经济价值的部分而正常运转。","正文"]],"uneconomic.mp3",{"r":[["后缀","-ic 表形容词，“…的”。"],["前缀","un- 表示“不，无，非，没有”。"],["词根","eco-,ecu-,oce- = house, 表示“家”，引申为环境，来自希腊语。"],["词根","nam-,nom-,-nomy = law，表示“法则”，引申为“管理”，用于后缀 -nomy = a field of knowledge, 表示“某一领域的知识”。"]],"d":[["uneconomical","adj. 浪费的;效率低的;不节约的"]]}],"unemployed":[["ˌʌn.ɪmˈplɔɪd","ˌʌn·ɪmˈplɔɪd"],["TOEFL"],[],[12,2.5,3,4,4],[["adj.","失业的；待业的；下岗的",12]],[["2021 英二 · 阅读 · Part A · Text 1","Of course, it is not like you can take an unemployed waiter and train him to be a doctor in a few weeks.","当然，不可能在几周内把一名失业服务员培训成医生。","正文"],["2014 英一 · 阅读 · Part A · Text 1","Ask anyone newly unemployed what they want and the answer is always: a job.","问问任何刚失业的人想要什么，答案总是：一份工作。","正文"],["2014 英一 · 阅读 · Part A · Text 1","Even the very phrase “jobseeker’s allowance” is about redefining the unemployed as a “jobseeker” who had no fundamental right to a benefit he or she has earned through making national insurance contributions.","甚至“求职者津贴”这个名称本身，也是在把失业者重新定义成“求职者”：尽管他们通过缴纳国民保险费赢得了领取福利的权利，却被说成并不享有这种基本权利。","正文"],["2014 英一 · 阅读 · Part A · Text 1","On first hearing, this was the socially concerned chancellor, trying to change lives for the better, complete with “reforms” to an obviously indulgent system that demands too little effort from the newly unemployed to find work, and subsidises laziness.","乍听之下，这位关心社会的财政大臣似乎在努力改善人们的生活，还要“改革”一个显然过于纵容的制度：它对新近失业者找工作要求太少，却补贴懒惰。","正文"],["2021 英二 · 阅读 · Part A · Text 1 · 第25题 · 选项A","Scandinavian Airlines decided to create job vacancies for the unemployed.","北欧航空决定为失业者创造就业岗位。","选项"],["2017 英二 · 完形","Indeed, today’s unemployed don’t seem to be having a great time.","的确，如今失业的人似乎过得并不愉快。",""]],"unemployed.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["前缀","em,en- 表示“入、内、在...之内、使...”，来自古法语 en-。在字母 b, m, p 前拼写同化为 em-。"],["词根","ploy- = use, 表示“用，参与”，和表示折叠的词根 ply- 同源。"],["后缀","-ed 形容词后缀，加在名词后表示“如...的”；加在动词后表示“被...的”。"]],"d":[]}],"uneven":[["ʌnˈiː.vᵊn","ʌnˈi·vən"],["IELTS"],[["副词","unevenly",1],["名词","unevenness",1]],[2,1.0,2,1,0],[["adj.","凹凸不平的；不平坦的",0],["adj.","无定型的；不规则的；无规律的",0],["adj.","质量不稳定的",1],["adj.","实力悬殊的；一边倒的；不在同一水平的",0],["adj.","不均衡的；不公平的；不规则的",1]],[["2025 英二 · 阅读 · Part A · Text 3","But implementation of existing HAPs has been uneven, according to a report from the center for Policy Research.","但政策研究中心的一份报告指出，现有高温应对计划的执行情况参差不齐。","正文"],["2024 英二 · 阅读 · Part A · Text 1 · 第24题 · 选项A","Several American cities are mentioned to show the uneven distribution of AI technologies in the US.","文中提到几座美国城市，是为了说明人工智能技术在美国分布不均。","选项"]],"uneven.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"]],"d":[["unevenly","adv. 不平坦地；不均衡地；不平行地"],["unevenness","n. 不平坦,不均衡"]]}],"unfairness":[["ʌnˈfeə.nəs","ʌnˈfer.nəs"],[],[["副词","unfairly",1]],[2,1.0,2,1,0],[["n.","不公平；不公正；不平等对待",2]],[["2004 英一 · 阅读 · Part A · Text 2","Over the past century, all kinds of unfairness and discrimination have been condemned or made illegal.","在过去一个世纪里，各种不公正和歧视都受到了谴责，或被定为非法。","正文"],["2005 英一 · 阅读 · Part A · Text 1 · 第22题 · 选项B","The statement “it is all too monkey” (Paragraph 1) implies that resenting unfairness is also monkeys’ nature.","第1段中“这也完全是猴子的本性”这一说法，暗示对不公平感到愤恨也是猴子的天性。","选项"]],"unfairness.mp3",null],"unfamiliar":[["ʌn.fəˈmɪl.i.əʳ","ˌʌn·fəˈmɪl·jər"],[],[["名词","unfamiliarity",1],["副词","unfamiliarly",1]],[5,2.0,5,0,0],[["adj.","陌生的；不熟悉的；不认识的",4],["adj.","无…的知识（或经验）",1]],[["2019 英一 · 完形","When you find yourself well off a trail, but not in a completely unfamiliar area of land, you have to answer two questions: Which way is downhill, in this particular area?","如果你发现自己已远离小径，但所处地区又并非完全陌生，就得回答两个问题：在这一带，哪边是下坡？",""],["2015 英一 · 阅读 · Part B · 选项C","C) If you are unfamiliar with words or idioms, you guess at their meaning, using clues presented in the context.","C）如果遇到不熟悉的词语或习语，你会利用上下文中呈现的线索推测其含义。",""],["2015 英二 · 完形","Strangers are inherently unfamiliar to us, so we are more likely to feel anxious when communicating with them compared with our friends and acquaintances.","陌生人对我们来说本就不熟悉，所以与他们交流时，我们比与朋友和熟人交流时更容易感到焦虑。",""],["2015 英一 · 阅读 · Part B · 第41题 · 选项C","If you are unfamiliar with words or idioms, you guess at their meaning, using clues presented in the context. On the assumption that they will become relevant later, you make a mental note of discourse entities as well as possible links between them. You begin to infer a context for the text, for instance, by making decisions about what kind of speech event is involved: who is making the utterance, to whom, when and where.","如果遇到不熟悉的词语或习语，你会利用上下文中呈现的线索推测其含义。你会假定这些指称对象及它们之间可能的联系稍后还会起作用，于是将其记在心里。 例如，你会通过判断涉及的是怎样的言语事件——是谁在说话、对谁说、何时何地说——来推断文本的语境。",""],["2010 英一 · 阅读 · Part B · 选项D","New skills and unfamiliar business models are needed too.","它们还需要新技能和不熟悉的商业模式。",""],["2005 英一 · 完形","The brain finds it best to keep smell receptors available for unfamiliar and emergency signals such as the smell of smoke, which might indicate the danger of fire.","大脑认为最好让嗅觉感受器随时能够识别陌生气味和紧急信号，例如烟味，因为烟味可能预示着火灾危险。",""]],"unfamiliar.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["后缀","-ar 表形容词，“…的”。"]],"d":[]}],"unfashionable":[["ʌnˈfæʃ.ᵊn.ə.bᵊl","ʌnˈfæʃ.ə.nə.bəl"],[],[["名词","unfashionableness",1],["副词","unfashionably",1]],[3,1.5,2,2,0],[["adj.","不时兴的；不时髦的；过时的",3]],[["2013 英一 · 阅读 · Part A · Text 3","Now utopia has grown unfashionable, as we have gained a deeper appreciation of the range of threats facing us, from asteroid strike to epidemic flu and to climate change.","如今，乌托邦式的憧憬已经不再流行，因为我们更深刻地认识到自己面临的种种威胁：小行星撞击、流感大流行以及气候变化。","正文"],["2010 英二 · 阅读 · Part A · Text 1","In the weeks and months that followed Mr. Hirst’s sale, spending of any sort became deeply unfashionable.","赫斯特拍卖会结束后的几周和几个月里，任何形式的花钱都变得极不合时宜。","正文"],["2010 英二 · 阅读 · Part A · Text 1 · 第22题 · 选项A","By saying “spending of any sort became deeply unfashionable” (Para.3), the author suggests that collectors were no longer actively involved in art-market auctions.","作者在第三段说“任何形式的花钱都变得极不合时宜”，意在指出收藏家不再积极参与艺术品市场的拍卖。","题干"]],"unfashionable.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","fac-,fact-,fect-,fic- = make, do, 表示“做，制作”，来自拉丁语 facere \"to make\"。"],["后缀","-ion,-ation,-ition 表名词，“行为、动作、状态、过程、结果；物品”等。"],["后缀","-able 一般缀于动词后，构成形容词，表示“可…的，能…”。"]],"d":[]}],"unfavorable":[["ʌnˈfeɪ.vᵊr.ə.bᵊl","ʌnˈfeɪ·vər·ə·bəl"],["TOEFL"],[["名词","unfavorableness",1],["副词","unfavorably",1]],[2,1.0,2,0,0],[["adj.","不利的；有害的",2],["adj.","不赞成的；否定的；不喜欢的",0]],[["2019 英一 · 阅读 · Part A · Text 4 · 第37题 · 选项D","It can be learned from paragraphs 2 and 3 that the overruled decisions were considered unfavorable by states.","从第二、三段可以得知，各州认为那些被推翻的判决对自己不利。","选项"],["2010 英一 · 阅读 · Part A · Text 4 · 第36题 · 选项A","Bankers complained that they were forced to follow unfavorable asset evaluation rules.","银行家抱怨说，他们被迫遵循对自己不利的资产评估准则。","选项"]],"unfavorable.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["后缀","-able 一般缀于动词后，构成形容词，表示“可…的，能…”。"]],"d":[]}],"unfeasible":[["ʌnˈfiː.zə.bᵊl","ʌnˈfizəbl"],[],[],[2,1.0,2,1,1],[["adj.","不可行的；难以实现的",2]],[["2013 英一 · 阅读 · Part C","In most of the homeless gardens of New York City the actual cultivation of plants is unfeasible, yet even so the compositions often seem to represent attempts to call forth the spirit of plant and animal life, if only symbolically, through a clumplike arrangement of materials, an introduction of colors, small pools of water, and a frequent presence of petals or leaves as well as of stuffed animals.","在纽约市无家可归者的大多数花园里，实际栽种植物并不可行；但即便如此，这些布置往往仍像是在尝试唤起动植物生命的气息，哪怕只是象征性地通过把材料堆成团、加入色彩和小水池，以及经常摆放花瓣、叶子和毛绒玩具来做到这一点。","正文"],["2023 英一 · 阅读 · Part A · Text 2 · 第30题 · 选项B","Horn holds that imposing registration requirements is an unfeasible proposal.","霍恩认为，实施登记要求是一项不可行的提议。","选项"]],"unfeasible.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","fac-,fact-,fect-,fic- = make, do, 表示“做，制作”，来自拉丁语 facere \"to make\"。"],["后缀","-ible 表形容词，“能…的”。"]],"d":[]}],"unfocused":[["ʌnˈfəʊ.kəst","ʌnˈfoʊkəst"],[],[],[3,1.5,2,2,0],[["adj.","目光分散的；漫不经心的",2],["adj.","目的不明确的；组织不严密的；松散的",1]],[["2018 英二 · 阅读 · Part A · Text 4","When our brains switch between being focused and unfocused on a task, they tend to be more efficient.","当我们的大脑在专注与不专注于任务的状态间切换时，往往能更高效地运作。","正文"],["2010 英一 · 阅读 · Part A · Text 1","We are even farther removed from the unfocused newspaper reviews published in England between the turn of the 20th century and the eve of World War Ⅱ, at a time when newsprint was dirt-cheap and stylish arts criticism was considered an ornament to the publications in which it appeared.","至于二十世纪初至第二次世界大战前夕英国报纸上那些主题散漫的评论，我们就更觉得遥远了：那时新闻纸便宜得惊人，而文笔优雅的艺术评论被视为所载报刊的点缀。","正文"],["2018 英二 · 阅读 · Part A · Text 4 · 第39题 · 选项B","Pillay believes that our brains’ shift between being focused and unfocused can bring about greater efficiency.","皮莱认为，我们的大脑在专注与非专注状态之间切换，能够提高效率。","题干"]],"unfocused.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","foc- = focus. 拉丁语中 focus“hearth, fireplace”表示火炉, 冬天火炉是家里活动中心, 所以后来引申为\"焦点\"。curfew 源于古法语 cuevrefeu 字面含义为 cuevre \"cover\" + feu \"fire\" 。"]],"d":[]}],"unification":[["ˌjuː.nɪ.fɪˈkeɪ.ʃᵊn","ˌju·nə·fəˈkeɪ·ʃən"],["GRE"],[],[2,1.0,1,2,0],[["n.","统一；使成一体；使一元化",2]],[["2012 英一 · 阅读 · Part C","Nonetheless, unification of sorts remains a major goal.","尽管如此，某种程度上的统一仍然是一个主要目标。","正文"],["2012 英一 · 阅读 · Part C","(46) In physics, one approach takes this impulse for unification to its extreme, and seeks a theory of everything — a single generative equation for all we see.","（46）在物理学中，一种研究路径把这种追求统一的冲动推向极致，力图找到一套包罗万象的理论，即一个能生成我们所见一切的方程式。","正文"]],"unification.mp3",{"r":[["后缀","-ion,-ation,-ition 表名词，“行为、动作、状态、过程、结果；物品”等。"],["前缀","un,uni = one, 表示“单一、一个”。"],["后缀","-fy,-ify 缀于名词或形容词后，构成表示“使成…”“…化”“作成…”等意思的动词"]],"d":[]}],"uniformly":[["ˈjuː.nɪ.fɔːm.li","ˈjuː.nə.fɔːrm.li"],["CET6"],[["复数","uniforms"],["原形","uniform"],["第三人称单数","uniforms"],["现在分词","uniforming"],["过去式","uniformed"],["过去分词","uniformed"],["副词","uniformly",1],["名词","uniformness",1],["形容词","uniformless",1],["形容词","uniformal",1],["形容词","ununiform",1],["副词","ununiformly",1]],[1,0.5,1,1,0],[["adv.","一致的；统一的；一律的",1]],[["2013 英一 · 阅读 · Part A · Text 3","Up until a few decades ago, our visions of the future were largely — though by no means uniformly — glowingly positive.","直到几十年前，我们对未来的想象总体上仍是光明乐观的，尽管也绝非一致如此。","正文"]],"uniformly.mp3",{"r":[["前缀","un,uni = one, 表示“单一、一个”。"],["词根","form- = shape, 表示“形状”，来自拉丁语 formare \"to shape, give form to\" 及 forma \"form\"。"],["后缀","-ly 表副词，通常缀于形容词后。"]],"d":[]}],"unilateral":[["ˌjuː.nɪˈlæt.ᵊr.ᵊl","ˌjun·ᵊlˈæt̬·ər·əl"],["IELTS","GRE"],[["副词","unilaterally",1]],[4,1.5,1,3,0],[["adj.","单方的",4]],[["2020 英一 · 阅读 · Part A · Text 4","The French tax is not just a unilateral move by one country in need of revenue.","法国的这项税收举措并非单纯是一个急需财政收入的国家的单边行动。","正文"],["2020 英一 · 阅读 · Part A · Text 4","In response to these many unilateral measures, the Organization for Economic Cooperation and Development (OECD) is currently working with 131 countries to reach a consensus by the end of 2020 on an international solution.","为应对这些众多的单边措施，经济合作与发展组织目前正与131个国家合作，争取在2020年底前就一项国际解决方案达成共识。","正文"],["2020 英一 · 阅读 · Part A · Text 4","These unilateral developments differ in their specifics, but they are all designed to tax multinationals on income and revenue that countries believe they should have a right to tax, even if international tax rules do not grant them that right.","这些单边举措在细节上各不相同，但目的都是对跨国公司的所得和收入征税；各国认为自己有权征税，即使国际税收规则并未赋予它们这项权利。","正文"],["2020 英一 · 阅读 · Part A · Text 4 · 第38题 · 选项B","The countries adopting the unilateral measures share the opinion that the current international tax system needs upgrading.","采取这些单边措施的国家都认为，现行国际税收体系需要升级。","题干"]],"unilateral.mp3",{"r":[["前缀","un,uni = one, 表示“单一、一个”。"],["词根","later- = side, 表示“边”，来源于拉丁语。"],["后缀","-al,-ial 表形容词，“…的”，一般缀于名词后。"]],"d":[["unilaterally","单方面"],["unilateralism","n. 单方,片面"],["unilateralization","n. 单向化"]]}],"unimaginable":[["ˌʌn.ɪˈmædʒ.ɪ.nə.bᵊl","ˌʌn·ɪˈmædʒ·ə·nə·bəl"],["TOEFL"],[["副词","unimaginably",1]],[1,0.5,1,1,0],[["adj.","难以置信的；不可想象的",1]],[["2003 英一 · 阅读 · Part A · Text 4","Such advances offer the aging population a quality of life that was unimaginable when I entered medicine 50 years ago.","这些进步让老年人享有我50年前从医时无法想象的生活品质。","正文"]],"unimaginable.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","imag-,imit- = imagine, likeness, 表示“想象，相像”，来自拉丁语。"],["后缀","-able 一般缀于动词后，构成形容词，表示“可…的，能…”。"]],"d":[]}],"unintentional":[["ˌʌn.ɪnˈten.ʃᵊn.ᵊl","ˌʌn·ɪnˈten·ʃən·ᵊl"],[],[["副词","unintentionally",1]],[2,1.0,2,0,0],[["adj.","无意的；非故意的；偶然的",2]],[["2016 英二 · 阅读 · Part A · Text 2 · 第28题 · 选项A","It can be learned from Paragraph 3 that unintentional harm-doers will not be prosecuted if they agree to pay a sum for compensation.","从第3段可以得知，无意中造成伤害的人只要同意支付一笔补偿款，就不会被起诉。","题干"],["2004 英一 · 阅读 · Part A · Text 2 · 第30题 · 选项D","Which of the following is true according to the text? Putting things alphabetically may lead to unintentional bias.","根据文章，下列哪一项是正确的？按字母顺序排列事物可能造成无意中的偏见。","选项"]],"unintentional.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["前缀","im-,in-,il-,ir- 来自拉丁语in-，表示“在内，进入，使...”。该拉丁语前缀进入古法语和西班牙语时拼写演变为 en-，这些词进入英语后导致在现代英语里少数单词存在两种拼写形式，如 insure, ensure, 确保；inquire, enquire, 查询。该前缀在字母 b, m, p 前拼写变体为 im-；在字母l前拼写同化为 il-；在字母r前拼写同化为 ir-。"],["词根","tend-,tent-,tens- = stretch, 表示“伸展”，引申为“触角”、“倾向”等，源自拉丁语 tenere \"to hold\"。"],["后缀","-ion,-ation,-ition 表名词，“行为、动作、状态、过程、结果；物品”等。"],["后缀","-al,-ial 表形容词，“…的”，一般缀于名词后。"]],"d":[]}],"unionize":[["ˈjuː.njə.naɪz","ˈjun·jəˌnɑɪz"],[],[["原形","unionize"],["第三人称单数","unionizes"],["现在分词","unionizing"],["过去式","unionized"],["过去分词","unionized"],["形容词","unionizable",1]],[1,0.5,1,1,0],[["v.","组织（或成立）工会；加入工会",1]],[["2012 英一 · 阅读 · Part A · Text 4","In Britain, more than half of public-sector workers but only about 15% of private-sector ones are unionized.","在英国，超过一半的公共部门雇员加入了工会，而私营部门的这一比例仅约为15%。","正文"]],"unionize.mp3",{"r":[["前缀","un,uni = one, 表示“单一、一个”。"],["后缀","-ion,-ation,-ition 表名词，“行为、动作、状态、过程、结果；物品”等。"],["后缀","-ise, -ize 动词后缀，一般缀于形容词后。-ise 是英式英语，-ize 是美式英语。"]],"d":[]}],"universality":[["ˌjuː.nɪ.vɜːˈsæl.ə.ti","ˌjuː.nə.vɝːˈsæl.ə.t̬i"],[],[["复数","universalities"]],[5,2.0,2,5,0],[["n.","普遍的；全体的；全世界的；共同的",2],["n.","普遍存在的；广泛适用的",3]],[["2025 英一 · 阅读 · Part A · Text 4","Yet how was that universality of access made possible and, perhaps more importantly, how is it maintained?","然而，这种普遍便利是如何实现的？或许更重要的是，它又如何得以维持？","正文"],["2025 英一 · 阅读 · Part A · Text 4","Librarians’ selfless devotion can act against us when users point to universality of access by holding up a cellphone and saying, “it’s all in here” as evidence that libraries are less vital for researchers today.","图书馆员无私的奉献有时反而对我们不利：用户举起手机说“全都在这里”，以信息获取的普遍便利为证，认为如今图书馆对研究者没那么重要了。","正文"],["2012 英一 · 阅读 · Part C","Russell Gray at the University of Auckland and his colleagues consider the evolution of grammars in the light of two previous attempts to find universality in language.","奥克兰大学的拉塞尔·格雷及其同事，结合此前两次寻找语言普遍性的尝试，考察语法的演变。","正文"],["2012 英一 · 阅读 · Part C","(49) The second, by Joshua Greenberg, takes a more empirical approach to universality, identifying traits (particularly in word order) shared by many languages, which are considered to represent biases that result from cognitive constraints.","（49）第二项尝试由约书亚·格林伯格提出，采用更重实证的方法研究普遍性：找出许多语言共有的特征，尤其是语序特征；这些特征被认为反映了认知限制所导致的偏向。","正文"],["2012 英一 · 阅读 · Part C","(50) Chomsky’s grammar should show patterns of language change that are independent of the family tree or the pathway tracked through it, whereas Greenbergian universality predicts strong co-dependencies between particular types of word-order relations.","（50）按照乔姆斯基的语法理论，语言变化的模式应独立于语系谱系树或其中所循的演化路径；而格林伯格式的普遍性理论则预言，特定类型的语序关系之间存在很强的相互依赖。","正文"]],"universality.mp3",{"r":[["前缀","un,uni = one, 表示“单一、一个”。"],["词根","ver-,vers-,vert-,vir- = turn, 表示“转”，来自拉丁语。"],["后缀","-al,-ial 表形容词，“…的”，一般缀于名词后。"],["后缀","-ity 表名词，指具备某种性质。"]],"d":[]}],"unjust":[["ʌnˈdʒʌst","ʌnˈdʒʌst"],["CET4","CET6"],[["副词","unjustly",1],["名词","unjustness",1]],[1,0.5,1,0,0],[["adj.","不公平的；不公正的；非正义的",1]],[["2012 英一 · 完形","When the court deals with social policy decisions, the law it shapes is inescapably political — which is why decisions split along ideological lines are so easily dismissed as unjust.","当法院处理社会政策决定时，它所塑造的法律不可避免地带有政治性，因此，沿意识形态分歧作出的裁决很容易被斥为不公。",""]],"unjust.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","just- = right, 表示“正直，法律”，来自拉丁语。"]],"d":[["unjustly","adv. 不义地；不法地"]]}],"unknowable":[["ʌnˈnəʊəbl","ʌnˈnoʊəbl"],[],[["名词","unknowability",1]],[1,0.5,1,1,0],[["adj.","无法知道的；不可知的",1]],[["2010 英一 · 阅读 · Part A · Text 4","The details may be unknowable, but the independence of standard-setters, essential to the proper functioning of capital markets, is being compromised.","具体情况也许无从得知，但准则制定者的独立性正在受到侵蚀，而这种独立性对资本市场的正常运转至关重要。","正文"]],"unknowable.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["后缀","-able 一般缀于动词后，构成形容词，表示“可…的，能…”。"]],"d":[]}],"unlearned":[["ʌnˈlɜːnɪd；ʌnˈlɜːnd","ʌnˈlɝnɪd；ʌnˈlɝnd"],[],[["副词","unlearnedly",1]],[1,0.5,1,1,0],[["adj.","学识不足的；未受教育的；缺乏学术素养的；显露无知的",0],["adj.","非经学习、训练或经验获得的；本能的",1]],[["2016 英一 · 阅读 · Part C","It’s a form of innate or unlearned optimism.","这是一种与生俱来、无需习得的乐观态度。","正文"]],"unlearned.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","las-,lear-,lir-,lor- 原意表示“地垄沟”，引申为“轨迹”，进一步引申为“知识...”。"],["后缀","-ed 形容词后缀，加在名词后表示“如...的”；加在动词后表示“被...的”。"]],"d":[]}],"unleash":[["ʌnˈliːʃ","ʌnˈliʃ"],["GRE"],[["原形","unleash"],["第三人称单数","unleashes"],["现在分词","unleashing"],["过去式","unleashed"],["过去分词","unleashed"]],[2,1.0,2,2,0],[["v.","发泄；突然释放；使爆发",2]],[["2021 英二 · 阅读 · Part A · Text 4","Intuition’s special powers are unleashed only in certain circumstances.","直觉的特殊力量只在特定情况下才会发挥出来。","正文"],["2017 英二 · 阅读 · Part A · Text 4","At the same time, people continue to treat fire as an event that needs to be wholly controlled and unleashed only out of necessity, says Professor Balch at the University of Colorado.","科罗拉多大学的鲍尔奇教授说，与此同时，人们仍把火视为一种必须完全控制、只有在必要时才能让它燃烧的现象。","正文"]],"unleash.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","lax-,leas-,lang- = loose, 表示“松”；= languid, 表示“疲倦”。原始印欧语形式为 *(s)leg- \"to be slack, be languid\" 。"]],"d":[]}],"unnatural":[["ʌnˈnætʃ.ᵊr.ᵊl","ʌnˈnætʃ·ər·əl"],[],[["副词","unnaturally",1],["名词","unnaturalness",1]],[2,1.0,2,1,1],[["adj.","不自然的；勉强的；反常的",2],["adj.","不正常的；怪异的",0]],[["2004 英一 · 阅读 · Part A · Text 4","Ralph Waldo Emerson and other Transcendentalist philosophers thought schooling and rigorous book learning put unnatural restraints on children: “We are shut up in schools and college recitation rooms for 10 or 15 years and come out at last with a bellyful of words and do not know a thing.”","拉尔夫·沃尔多·爱默生和其他超验主义哲学家认为，学校教育和严格的书本学习给儿童施加了不自然的束缚：“我们被关在学校和大学的诵读教室里十年或十五年，最后出来时满肚子词句，却什么都不懂。”","正文"],["2014 英二 · 阅读 · Part A · Text 2 · 第26题 · 选项C","According to the first paragraph, social psychologists have found that our need for leadership is unnatural.","根据第一段，社会心理学家发现，我们对领导力的需求并不自然。","选项"]],"unnatural.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","nat-,nai- = born, 表示“出生的”，来自古典拉丁语 gnasci，由词根 gen-（出生，产生）组成。"],["后缀","-ture,-ature,-iture 表名词，通常在单词或词根以t结尾时使用，表示“一般状态，行为”。"],["后缀","-al,-ial 表形容词，“…的”，一般缀于名词后。"]],"d":[]}],"unnecessarily":[["ʌnˈnes.ə.sᵊr.ᵊl.i","ʌnˌnes.əˈser.ᵊl.i. ʌnˈnes.ə.ser.ᵊl.i"],[],[],[1,0.5,1,0,0],[["adv.","不必要地",1]],[["2010 英一 · 阅读 · Part A · Text 2 · 第29题 · 选项B","We learn from the last two paragraphs that business-method patents are often unnecessarily issued.","从最后两段可知，商业方法专利往往在没有必要的情况下获得授权。","选项"]],"unnecessarily.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","neg- = deny, 表示“否认”，原始印欧语形式为 *ne- (no, not)，和词根 un- 同源。"],["词根","ced-,ceed-,cess- = go away; withdraw, yield, 表示“走开，撤退，屈服”。来自拉丁语。"],["后缀","-ary 表形容词，“…的”。"],["后缀","-ly 表副词，通常缀于形容词后。"]],"d":[]}],"unprecedented":[["ʌnˈpres.ɪ.den.tɪd","ʌnˈpres·ɪˌden·tɪd"],["CET6","TOEFL","GRE"],[["副词","unprecedentedly",1]],[2,1.0,2,1,1],[["adj.","前所未有的；空前的；没有先例的",2]],[["2006 英一 · 阅读 · Part A · Text 1","Writing for the National Immigration Forum, Gregory Rodriguez reports that today’s immigration is neither at unprecedented levels nor resistant to assimilation.","格雷戈里·罗德里格斯为全国移民论坛撰文指出，如今的移民规模既未达到空前水平，移民也并非抗拒同化。","正文"],["2017 英二 · 阅读 · Part A · Text 4 · 第36题 · 选项A","More frequent wildfires have become a national concern because in 2015 they exhausted unprecedented management efforts.","更加频繁的野火已成为全国关注的问题，因为在二〇一五年，应对这些野火耗尽了前所未有的大量管理精力。","选项"]],"unprecedented.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["前缀","pre- 表示“…前的，预先”，来自拉丁语，一般放在动词性词根前。"],["词根","ced-,ceed-,cess- = go away; withdraw, yield, 表示“走开，撤退，屈服”。来自拉丁语。"],["后缀","-ed 形容词后缀，加在名词后表示“如...的”；加在动词后表示“被...的”。"]],"d":[]}],"unpredictability":[["ˌʌn.prɪˌdɪk.təˈbɪl.ə.ti","ˌʌn.prɪˌdɪk.təˈbɪl.ə.t̬i"],[],[["复数","unpredictabilities"],["副词","unpredictably",1],["名词","unpredictability",1]],[2,1.0,2,0,1],[["n.","（人）善变的，难以捉摸的",0],["n.","不可预测性",2]],[["2026 英一 · 阅读 · Part B · 选项E","E) We are living through a golden age of science writing, so lucid and accessible that even lay readers can relish the unpredictability of discovery.","E）我们正处于科学写作的黄金时代：作品清晰易懂，甚至普通读者也能享受科学发现的不可预测性。",""],["2003 英一 · 阅读 · Part A · Text 1 · 第24题 · 选项C","It can be learned from paragraph 4 that Straitford’s business is characterized by unpredictability.","从第四段可以得知，Straitford的业务以不可预测性为特点。","选项"]],"unpredictability.mp3",null],"unpredictable":[["ˌʌn.prɪˈdɪk.tə.bᵊl","ˌʌn·prɪˈdɪk·tə·bəl"],["TOEFL"],[["副词","unpredictably",1],["名词","unpredictability",1]],[2,1.0,2,0,1],[["adj.","无法预言的；不可预测的；难以预料的",2],["adj.","（人）善变的，难以捉摸的",0]],[["2024 英一 · 阅读 · Part A · Text 3 · 第32题 · 选项B","The problem with open-source AI art generators is that they produce artworks in unpredictable styles.","开源人工智能绘画生成器的问题在于，它们生成的艺术作品风格难以预测。","选项"],["2000 英一 · 完形","He must use this surplus in three ways: as seed for sowing, as an insurance against the unpredictable effects of bad weather and as a commodity which he must sell in order to replace old agricultural implements and obtain chemical fertilizers to feed the soil.","他必须把这些余粮用于三个方面：留作播种的种子；作为保障，以应对恶劣天气难以预测的影响；作为出售的商品，用所得收入更换旧农具并购买化肥来滋养土壤。",""]],"unpredictable.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["前缀","pre- 表示“…前的，预先”，来自拉丁语，一般放在动词性词根前。"],["词根","dict-,dic- = say, declare, 表示“说话，断言”，来自拉丁语 dicere \"to say, to declare\"。"],["后缀","-able 一般缀于动词后，构成形容词，表示“可…的，能…”。"]],"d":[]}],"unpretentious":[["ˌʌn.prɪˈten.ʃəs","ˌʌnprɪˈtɛnʃəs"],["GRE"],[["副词","unpretentiously",1],["名词","unpretentiousness",1]],[2,1.0,2,2,0],[["adj.","谦虚谨慎的；不事张扬的；不爱炫耀的",2]],[["2026 英一 · 阅读 · Part A · Text 3","In my own book about radio I recorded how, on one drive: “I caught up with the news, learnt some 17th-century history, and was startlingly educated by an unpretentious programme on the history of the stethoscope.”","在我自己写的广播著作中，我记下一次开车时的经历：“我了解了最新消息，学到一些17世纪的历史知识，还被一档讲述听诊器历史的朴实节目意外地上了一课。”","正文"],["2011 英一 · 阅读 · Part A · Text 1","Even Tommasini, who had advocated Gilbert's appointment in the Times, calls him “an unpretentious musician with no air of the formidable conductor about him.”","即使是在《纽约时报》上力荐吉尔伯特出任此职的托马西尼，也称他是“一位谦逊的音乐家，身上没有那种令人望而生畏的指挥家气派”。","正文"]],"unpretentious.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["前缀","pre- 表示“…前的，预先”，来自拉丁语，一般放在动词性词根前。"],["词根","tend-,tent-,tens- = stretch, 表示“伸展”，引申为“触角”、“倾向”等，源自拉丁语 tenere \"to hold\"。"],["后缀","-ous,-itious,-eous,-ious,-uous 表形容词，表示“…的”，用于化学领域表示“亚酸的，低价（金属）的”。"]],"d":[]}],"unrealistic":[["ˌʌn.rɪəˈlɪs.tɪk","ʌnˌri·əˈlɪs·tɪk"],[],[["副词","unrealistically",1]],[5,2.0,5,2,3],[["adj.","不切实际的；不实事求是的",5]],[["2021 英二 · 阅读 · Part B","Your senior colleague outlines a project timeline you believe is unrealistic.","一位资深同事提出项目时间表，而你认为这个安排不切实际。","正文"],["2011 英一 · 阅读 · Part A · Text 4","Of course, the image of parenthood that celebrity magazines like Us Weekly and People present is hugely unrealistic, especially when the parents are single mothers like Bullock.","当然，《美国周刊》和《人物》等明星杂志描绘的为人父母的画面极不真实，尤其当父母是布洛克这样的单身母亲时。","正文"],["2024 英二 · 阅读 · Part A · Text 3 · 第32题 · 选项B","The American Medical Association’s advice is generally considered unrealistic.","美国医学会的建议普遍被认为不切实际。","选项"],["2017 英二 · 阅读 · Part A · Text 3 · 第32题 · 选项A","Studies from the US and Australia imply that taking a gap year helps keep students from being unrealistic.","美国和澳大利亚的研究表明，选择间隔年有助于避免学生抱有不切实际的想法。","选项"],["2015 英二 · 阅读 · Part A · Text 1 · 第21题 · 选项A","According to Paragraph 1, most previous surveys found that home was an unrealistic place for relaxation.","根据第一段，以往的大多数调查发现，家作为放松的场所并不现实。","选项"]],"unrealistic.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","re-,res- 表示“事情、真实的、事物”。"],["后缀","-ist 表名词，表示“信仰者，专家或从事某活动的人”。"],["后缀","-ic 表形容词，“…的”。"]],"d":[]}],"unreasonable":[["ʌnˈriː.zᵊn.ə.bᵊl","ʌnˈri·zə·nə·bəl"],["CET6"],[["名词","unreasonableness",1],["副词","unreasonably",1]],[5,2.0,5,2,1],[["adj.","不合理的；不公正的；期望过高的",5]],[["2015 英一 · 阅读 · Part A · Text 2","Citizens still have a right to expect private documents to remain private and protected by the Constitution’s prohibition on unreasonable searches.","公民仍有权期待私人文件保持私密，并受到宪法中禁止不合理搜查条款的保护。","正文"],["2000 英一 · 阅读 · Part A · Text 3","When a new movement in art attains a certain fashion, it is advisable to find out what its advocates are aiming at, for, however farfetched and unreasonable their principles may seem today, it is possible that in years to come they may be regarded as normal.","当一种新的艺术运动开始流行时，最好弄清其倡导者的目标；因为不论他们的原则今天看来多么牵强或不合情理，若干年后仍有可能被视为正常。","正文"],["2023 英二 · 阅读 · Part A · Text 4 · 第36题 · 选项B","According to Paragraph 1, children growing into adolescence tend to see the world in an unreasonable way.","根据第一段，进入青春期的孩子往往会以不合理的方式看待世界。","选项"],["2021 英一 · 阅读 · Part A · Text 1 · 第21题 · 选项D","The author holds that this year’s increase in rail passenger fares remains an unreasonable measure.","作者认为，今年提高铁路客运票价仍是不合理的举措。","选项"],["2017 英一 · 阅读 · Part A · Text 1 · 第24题 · 选项D","One problem with the PreCheck program is an unreasonable price for enrollment.","PreCheck（预检）计划的一个问题是，加入该计划的费用不合理。","选项"]],"unreasonable.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","rat-,reas- = calculate, 表示“计算”，引申为“思考”。"],["后缀","-able 一般缀于动词后，构成形容词，表示“可…的，能…”。"]],"d":[["unreasonably","adv. 不合理地"]]}],"unrecognized":[["ʌnˈrek.əɡ.naɪzd","ʌnˈrɛkəɡˌnaɪzd"],[],[],[1,0.5,1,1,0],[["adj.","未被意识到的；被忽略的；不受重视的",1],["adj.","被埋没的；未得到赏识的",0]],[["2008 英一 · 阅读 · Part A · Text 3","The trend in sports, though, may be obscuring an unrecognized reality: Americans have generally stopped growing.","不过，体育界的这种趋势可能掩盖一个尚未得到认识的事实：美国人的身高总体上已经停止增长。","正文"]],"unrecognized.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["前缀","re- 表示“向后，往回，相反，相对，再”，或仅作强调用，在元音前 red-, reh-。源自拉丁语 re- \"again, back, anew, against.\""],["前缀","co-,com-,con-,col-,cor- 来自拉丁语介词com，表示“与...一起，一起（with, together）”，或仅做强调。"],["词根","gn-,gnos-,gnor- = know, 表示“知道”，来自拉丁语。"],["后缀","-ise, -ize 动词后缀，一般缀于形容词后。-ise 是英式英语，-ize 是美式英语。"],["后缀","-ed 形容词后缀，加在名词后表示“如...的”；加在动词后表示“被...的”。"]],"d":[]}],"unrelated":[["ˌʌn.rɪˈleɪ.tɪd","ˌʌn·rɪˈleɪ·t̬ɪd"],[],[["名词","unrelatedness",1]],[5,2.0,3,2,0],[["adj.","无关联的；不相关的",3],["adj.","不属于同一家族（或同一科等）的；无亲缘关系的",2]],[["2014 英一 · 阅读 · Part A · Text 2","There is just one path for a lawyer in most American states: a four-year undergraduate degree in some unrelated subject, then a three-year law degree at one of 200 law schools authorized by the American Bar Association and an expensive preparation for the bar exam.","在美国大多数州，成为律师基本只有一条路：先获得某个不相关专业的四年制本科学位，再到美国律师协会认可的两百所法学院之一攻读三年法律学位，并花大钱准备律师资格考试。","正文"],["2008 英一 · 阅读 · Part B","Once you have a first draft on paper, you can delete material that is unrelated to your thesis and add material necessary to illustrate your points and make your paper convincing.","初稿写到纸上后，可以删去与论点无关的材料，并补充阐明观点、增强文章说服力所需的材料。","正文"],["2015 英一 · 完形","The study is a genome-wide analysis conducted on 1,932 unique subjects which compared pairs of unrelated friends and unrelated strangers.","这项研究对1932名不同的受试者进行了全基因组分析，将互无亲缘关系的朋友组合与互无亲缘关系的陌生人组合进行比较。",""],["2008 英一 · 完形","These facts, however, have previously been thought unrelated.","然而，以前人们认为这两类事实之间没有关联。",""]],"unrelated.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["前缀","re- 表示“向后，往回，相反，相对，再”，或仅作强调用，在元音前 red-, reh-。源自拉丁语 re- \"again, back, anew, against.\""],["词根","lat- = bring out, 表示“拿出，带出”，源自拉丁语 latum \"to carry, to bring , to bear\"。"]],"d":[]}],"unrepresentative":[["ˌʌn.rep.rɪˈzen.tə.tɪv","ˌʌnrɛprɪˈzɛntət̮ɪv"],[],[["名词","unrepresentativeness",1]],[2,1.0,2,2,0],[["adj.","不典型的；无代表性的",2]],[["2014 英一 · 阅读 · Part A · Text 3","The Breakthrough Prize in Life Sciences, launched this year, takes an unrepresentative view of what the life sciences include.","今年创设的生命科学突破奖，对生命科学所涵盖的领域认识得不够全面。","正文"],["2010 英二 · 阅读 · Part A · Text 4","This practice was justified by the claim that women were needed at home, and it kept juries unrepresentative of women through the 1960s.","人们声称女性需要留在家里，以此为这种做法辩护；直到20世纪60年代，它仍使陪审团无法充分代表女性。","正文"]],"unrepresentative.mp3",null],"unseat":[["ʌnˈsiːt","ʌnˈsit"],[],[["原形","unseat"],["第三人称单数","unseats"],["现在分词","unseating"],["过去式","unseated"],["过去分词","unseated"]],[1,0.5,1,0,0],[["v.","罢免；解除职务；赶下台",1],["v.","使摔下马（或自行车）",0]],[["2010 英一 · 阅读 · Part B · 选项D","Big retailers must understand these differences before they can identify the segments of European wholesaling in which their particular abilities might unseat smaller but entrenched competitors.","大型零售商必须了解这些差异，才能找出欧洲批发市场中哪些细分领域可凭借自身的特殊能力，击败规模较小但根基牢固的竞争对手。",""]],"unseat.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","sid-,sed-,sess- = sit, 表示“坐”，来自拉丁语。"]],"d":[]}],"unsettle":[["ʌnˈset.ᵊl","ʌnˈsɛt̮l"],["GRE"],[["原形","unsettle"],["第三人称单数","unsettles"],["现在分词","unsettling"],["过去式","unsettled"],["过去分词","unsettled"]],[1,0.5,1,1,0],[["v.","使心神不宁；扰乱；使担忧",1]],[["2015 英一 · 阅读 · Part A · Text 4","Two years ago, Rupert Murdoch’s daughter, Elisabeth, spoke of the “unsettling dearth of integrity across so many of our institutions”.","两年前，鲁珀特·默多克的女儿伊丽莎白谈到“我们众多机构中令人不安的诚信匮乏”。","正文"]],"unsettle.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","set- = fix, 表示“安置好”。"]],"d":[["unsettled","未处理的， 未决定的"],["unsettling","adj. 使人不安的;(消息)混乱的"]]}],"unsurprisingly":[["ʌn.səˈpraɪ.zɪŋ.li","ʌn.sɚˈpraɪ.zɪŋ.li"],[],[],[1,0.5,1,0,0],[["adv.","不出所料地；不足为奇地",1]],[["2011 英一 · 阅读 · Part B · 选项C","C) Equally unsurprisingly, only about half end up with professorships for which they entered graduate school.","C）同样不足为奇的是，这些研究生中最终只有大约一半获得了当初读研所追求的教授职位。",""]],"unsurprisingly.mp3",null],"untested":[["ʌnˈtest.ɪd","ʌnˈtɛstəd"],[],[],[1,0.5,1,1,0],[["adj.","未经试验（或考验）的",1]],[["2010 英一 · 阅读 · Part A · Text 3","The supposed importance of influentials derives from a plausible-sounding but largely untested theory called the “two-step flow of communication”: Information flows from the media to the influentials and from them to everyone else.","人们之所以认为影响者很重要，是基于一种听起来可信、却基本未经检验的“传播的两级流动”理论：信息先从媒体流向影响者，再由他们传给其他所有人。","正文"]],"untested.mp3",null],"unwieldy":[["ʌnˈwiːl.di","ʌnˈwil·di"],["TOEFL","GRE"],[["副词","unwieldily",1],["名词","unwieldiness",1]],[1,0.5,1,1,0],[["adj.","笨重的；笨拙的；不灵巧的",0],["adj.","难控制（或操纵、管理）的；运转不灵的；尾大不掉的",1]],[["2022 英一 · 阅读 · Part A · Text 4","However, the mechanisms proposed were unwieldy and the Bill was voted down following the change in government later that year.","然而，拟议的机制过于繁琐；当年晚些时候政府更迭，法案随后遭否决。","正文"]],"unwieldy.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["后缀","-y 表形容词，加在名词后变成形容词。"]],"d":[["unwieldiness","n. 笨拙"]]}],"unworthy":[["ʌnˈwɜː.ði","ʌnˈwərði"],[],[["比较级","unworthier"],["最高级","unworthiest"],["副词","unworthily",1],["名词","unworthiness",1]],[2,1.0,2,0,2],[["adj.","不值得（尊重）的；不配的",2],["adj.","格格不入的；不能接受的；（与…的身份）不相称的",0]],[["2014 英一 · 阅读 · Part A · Text 3 · 第35题 · 选项D","The author believes that the new awards are unworthy of public attention.","作者认为，新奖项不值得公众关注。","选项"]],"unworthy.mp3",{"r":[["前缀","un- 表示“不，无，非，没有”。"],["词根","worth- = value, 表示“价值”，和表示“转”的词根 ver- 同源"],["后缀","-y 表形容词，加在名词后变成形容词。"]],"d":[["unworthily","adv. 可耻地,不相称地"]]}],"upcoming":[["ˈʌpˌkʌm.ɪŋ","ˈʌpˌkʌm·ɪŋ"],[],[],[3,1.5,3,1,0],[["adj.","即将发生（或来临）的",3]],[["2017 英一 · 阅读 · Part A · Text 1","Upcoming reforms might bring the price to a more reasonable level.","即将实施的改革也许能把价格降到更合理的水平。","正文"],["2020 英一 · 写作 · Part A · 第51题","The student union of your university has assigned you to inform the international students about an upcoming singing contest.","你所在大学的学生会委托你向留学生告知即将举行的歌唱比赛。",""],["2013 英一 · 写作 · Part A · 第51题","Write an e-mail of about 100 words to a foreign teacher in your college, inviting him/her to be a judge for the upcoming English speech contest.","给你所在大学的一位外籍教师写一封约 100 词的电子邮件，邀请他或她担任即将举行的英语演讲比赛的评委。",""]],"upcoming.mp3",{"r":[["词根","up- = up, over, 表示“向上”。"],["后缀","-ing 表形容词，“正…的”，“令人…的”。"]],"d":[]}],"upfront":[["ʌpˈfrʌnt","ˈʌpˈfrʌnt"],["GRE"],[],[1,0.5,1,1,0],[["adj.","坦率的；诚实的；直爽的",0],["adj.","预付的；预交的",0],["attributive adjective in a policy name","预先进行的；在领取福利前先行的",1]],[["2014 英一 · 阅读 · Part A · Text 1","In order to “change lives for the better” and reduce “dependency”, George Osborne, Chancellor of the Exchequer, introduced the “upfront work search” scheme.","为“改善生活”并减少“依赖”，英国财政大臣乔治·奥斯本推出了“预先求职”计划。","正文"]],"upfront.mp3",{"r":[["词根","up- = up, over, 表示“向上”。"],["词根","front- = forehead, 表示“前额”，来自拉丁语。"]],"d":[]}],"upheaval":[["ʌpˈhiː.vᵊl","ˌʌpˈhi·vəl"],["TOEFL","GRE"],[["复数","upheavals"]],[1,0.5,1,1,0],[["n.","剧变；激变；动乱；动荡",1]],[["2018 英一 · 阅读 · Part A · Text 1","Optimists point out that technological upheaval has benefited workers in the past.","乐观者指出，过去的技术变革曾使劳动者受益。","正文"]],"upheaval.mp3",{"r":[["词根","up- = up, over, 表示“向上”。"],["词根","cap-,capt-,cept-,ceiv-,cip-,cup- = take, hold, seize, 表示“拿，抓，握住”，来源于拉丁语。"]],"d":[]}],"upholster":[["ʌpˈhəʊl.stəʳ","əˈpoʊl·stər"],[],[["原形","upholster"],["第三人称单数","upholsters"],["现在分词","upholstering"],["过去式","upholstered"],["过去分词","upholstered"]],[1,0.5,1,1,0],[["v.","为（椅子等）装软垫（或套子等）",0],["v.","装上软垫或装饰；以类似方式修饰",1]],[["2010 英一 · 阅读 · Part A · Text 1","Journalistic tastes had changed long before his death, and postmodern readers have little use for the richly upholstered Vicwardian prose in which he specialized.","早在他去世很久以前，报业的品味就已改变；后现代读者对他所擅长的辞藻华丽的维多利亚—爱德华时代文风也不大感兴趣。","正文"]],"upholster.mp3",{"r":[["词根","up- = up, over, 表示“向上”。"]],"d":[["upholstery","n. 家具装饰业;家具装饰材料"],["upholsterer","家具商"]]}],"upkeep":[["ˈʌp.kiːp","ˈʌpˌkip"],["IELTS"],[["复数","upkeeps"]],[2,1.0,2,1,0],[["n.","保养（费）；维修（费）",2],["n.","抚养（费）；喂养（成本）",0]],[["2017 英二 · 阅读 · Part A · Text 4","In effect, fewer federal funds today are going towards the agency’s other work — such as forest conservation, watershed and cultural resources management, and infrastructure upkeep — that affect the lives of all Americans.","实际上，如今用于该机构其他工作的联邦资金减少了；这些工作包括森林保护、流域与文化资源管理及基础设施维护，都关系到全体美国人的生活。","正文"],["2009 英一 · 完形","It takes more upkeep, burns more fuel and is slow off the starting line because it depends on learning — a(n) gradual process — instead of instinct.","它需要更多维护，消耗更多能量，而且起步较慢，因为它依赖学习这一渐进的过程，而非本能。",""]],"upkeep.mp3",{"r":[["词根","up- = up, over, 表示“向上”。"]],"d":[]}],"uplifting":[["ʌpˈlɪf.tɪŋ","ˈʌpˈlɪf·tɪŋ"],[],[["复数","uplifts"],["原形","uplift"],["第三人称单数","uplifts"],["现在分词","uplifting"],["过去式","uplifted"],["过去分词","uplifted"],["名词","uplifter",1],["名词","upliftment",1]],[1,0.5,1,1,0],[["adj.","令人振奋的；鼓舞人心的；催人奋进的",1]],[["2016 英一 · 阅读 · Part A · Text 1","Such measures have a couple of uplifting motives.","这些措施有两个令人鼓舞的动机。","正文"]],"uplifting.mp3",null],"upload":[["ʌpˈləʊd；ˈʌp.ləʊd","ˈʌpˌləʊd"],[],[["原形","upload"],["第三人称单数","uploads"],["现在分词","uploading"],["过去式","uploaded"],["过去分词","uploaded"]],[8,2.5,2,5,1],[["v.","上传",7],["n.","上载（或上传）的数据",1]],[["2025 英一 · 阅读 · Part A · Text 3","Initially the rise of legitimate online businesses such as Netflix actually helped curb digital piracy, which had largely been based on file uploads.","起初，奈飞等合法在线业务的兴起实际上有助于遏制数字盗版，当时的盗版主要以文件上传为基础。","正文"],["2012 英一 · 阅读 · Part B","What counts as meaningful uploading?","怎样的上传才算有意义？","正文"],["2012 英一 · 阅读 · Part B","All animals download, but only a few upload.","所有动物都会“下载”，但只有少数会“上传”。","正文"],["2012 英一 · 阅读 · Part B","Second, the majority of people who use networked computers to upload are not even aware of the significance of what they are doing.","第二，大多数使用联网计算机上传内容的人，甚至没有意识到自己所做之事的意义。","正文"],["2012 英一 · 阅读 · Part B","Even after the advent of widespread social media, a pyramid of production remains, with a small number of people uploading material, a slightly larger group commenting on or modifying that content, and a huge percentage remaining content to just consume.","即使在社交媒体兴起并广泛普及之后，内容生产仍呈金字塔结构：少数人上传素材，稍多一些的人评论或修改这些内容，而绝大多数人仍满足于只做消费者。","正文"],["2025 英一 · 阅读 · Part A · Text 3 · 第32题 · 选项D","It can be learned that streamers like Netflix used to collaborate with file-uploading platforms.","可以得知，奈飞等流媒体服务商曾与文件上传平台合作。","选项"]],"upload.mp3",{"r":[["词根","lead-,lod- 表示“走”，原始印欧语形式为 *leit-。"]],"d":[]}],"upscale":[["ˈʌp.skeɪl","ˈʌpˌskeɪl"],["TOEFL"],[["原形","upscale"],["第三人称单数","upscales"],["现在分词","upscaling"],["过去式","upscaled"],["过去分词","upscaled"]],[1,0.5,1,1,0],[["adj.","高档的；高级的",1],["v.","改进；扩大；升级",0],["v.","使（产品）更高档",0]],[["2001 英一 · 阅读 · Part A · Text 3","Replies show that compared with other Americans, journalists are more likely to live in upscale neighborhoods, have maids, own Mercedeses, and trade stocks, and they’re less likely to go to church, do volunteer work, or put down roots in a community.","答复表明，与其他美国人相比，记者更可能住在高档社区、雇佣女佣、拥有奔驰车和买卖股票；他们较少去教堂、参加志愿服务或在某个社区扎根。","正文"]],"upscale.mp3",{"r":[["词根","scilp-,sculpt- 表示“砍、切”"]],"d":[]}],"upside":[["ˈʌp.saɪd","ˈʌpˌsɑɪd"],[],[["复数","upsides"]],[3,1.5,3,3,0],[["n.","（糟糕局面的）好的一面，光明的一面，正面",3]],[["2023 英二 · 阅读 · Part A · Text 3","Some worry that this is having a destructive effect on society, but Sparrow sees an upside.","有人担心这会对社会造成破坏性影响，但斯帕罗看到了积极的一面。","正文"],["2011 英一 · 阅读 · Part C","(50) The upside is the possibilities contained in knowing that everything is up to us; where before we were experts in the array of limitations, now we become authorities of what is possible.","（50）好的一面在于：明白一切都取决于我们自己，就会看到其中蕴含的种种可能；过去我们是各种限制的专家，如今却成为各种可能性的行家。","正文"],["2004 英一 · 阅读 · Part A · Text 3","Diners might see an upside, too.","外出就餐的人也可能看到好处。","正文"]],"upside.mp3",{"r":[["词根","up- = up, over, 表示“向上”。"]],"d":[["upside-down","颠倒的;混乱的"]]}],"upstart":[["ˈʌp.stɑːt","ˈʌpˌstɑrt"],["GRE"],[["复数","upstarts"],["原形","upstart"],["第三人称单数","upstarts"],["现在分词","upstarting"],["过去式","upstarted"],["过去分词","upstarted"]],[1,0.5,1,1,0],[["n.","自命不凡的新上任者；狂妄自大的新手",1]],[["2014 英一 · 阅读 · Part A · Text 3","You cannot buy class, as the old saying goes, and these upstart entrepreneurs cannot buy their prizes the prestige of the Nobels.","俗话说，格调是买不来的；这些新贵企业家也无法为自己的奖项买来诺贝尔奖那样的声望。","正文"]],"upstart.mp3",{"r":[["词根","up- = up, over, 表示“向上”。"]],"d":[]}],"usher":[["ˈʌʃ.əʳ","ˈʌʃ·ər"],["TOEFL"],[["复数","ushers"],["原形","usher"],["第三人称单数","ushers"],["现在分词","ushering"],["过去式","ushered"],["过去分词","ushered"],["形容词","usherless",1],["名词","usherer",1]],[1,0.5,1,1,0],[["n.","引座员",0],["n.","（法院的）传达员，门卫，门房",0],["n.","男傧相",0],["v.","把…引往；引导；引领",1]],[["2010 英二 · 阅读 · Part A · Text 4","In 1968, the Congress of the United States passed the Jury Selection and Service Act, ushering in a new era of democratic reforms for the jury.","1968年，美国国会通过《陪审员选拔与服务法》，开启了陪审制度民主改革的新时代。","正文"]],"usher.mp3",{"r":[["词根","or-,ora-,orat-,os- = mouth, 表示“嘴，说”。"]],"d":[["usherette","女引座员"],["ushership","n. 引座员职务;领宾员职位"]]}],"utopia":[["juːˈtəʊ.pi.ə","juˈtoʊ·pi·ə"],["GRE"],[["复数","utopias"]],[3,1.5,2,3,0],[["n.","乌托邦；空想的完美境界",3]],[["2013 英一 · 阅读 · Part A · Text 3","Now utopia has grown unfashionable, as we have gained a deeper appreciation of the range of threats facing us, from asteroid strike to epidemic flu and to climate change.","如今，乌托邦式的憧憬已经不再流行，因为我们更深刻地认识到自己面临的种种威胁：小行星撞击、流感大流行以及气候变化。","正文"],["2000 英一 · 阅读 · Part A · Text 2","For us, this means that evolution is over; the biological Utopia has arrived.","对我们来说，这意味着进化已经结束；生物学意义上的理想国已经到来。","正文"],["2000 英一 · 阅读 · Part A · Text 2","But however amazed our descendants may be at how far from Utopia we were, they will look just like us.","但无论我们的后代对我们当年离理想国有多远感到多么惊讶，他们的外貌仍会与我们一样。","正文"]],"utopia.mp3",null]};